INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C1','math',4,2,'u5',2,'꺾은선그래프의 뜻 — 시간에 따라 변화하는 양을 점으로 표시하고 그 점들을 선분으로 이어 그린 그래프로, 막대그래프보다 변화하는 모습을 알아보기 쉽다',ARRAY['4수04-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C2','math',4,2,'u5',2,'가로·세로와 눈금 읽기 — 가로·세로가 무엇을 나타내는지와 세로 눈금 한 칸의 크기를 먼저 확인하고 점의 값과 두 때의 차를 읽는다',ARRAY['4수04-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C3','math',4,2,'u5',2,'사이 값 짐작과 물결선 — 이웃한 두 점을 이은 선분으로 조사하지 않은 때의 값을 짐작하고, 물결선으로 필요 없는 부분을 줄이면 변화가 뚜렷하게 보인다',ARRAY['4수04-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C4','math',4,2,'u5',3,'나타내는 다섯 걸음 — 제목, 가로·세로에 나타낼 것, 눈금의 단위, 세로 눈금 한 칸의 크기를 정한 뒤 점을 찍고 가로 눈금의 순서대로 선분으로 잇는다',ARRAY['4수04-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C5','math',4,2,'u5',3,'눈금 한 칸 정하기 — 가장 큰 값까지 나타낼 수 있고 값이 눈금 위에 오도록 자료에 알맞게 세로 눈금 한 칸을 정하며, 한 칸이 클수록 변화가 덜 뚜렷하다',ARRAY['4수04-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C6','math',4,2,'u5',4,'물결선의 자리 — 물결선은 0과 가장 작은 값 사이에 넣고, 자료의 수 범위 안에 넣으면 기울어진 정도가 사실과 달라진다',ARRAY['4수04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C7','math',4,2,'u5',4,'값이 큰 자료 나타내기 — 값이 크거나 서로 가까운 자료는 물결선과 작은 눈금 칸으로 나타내고, 아주 큰 자료는 공학 도구로 쉽고 빠르게 나타낸다',ARRAY['4수04-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C8','math',4,2,'u5',5,'값과 변화 읽기 — 꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것, 평평하면 변하지 않은 것으로 읽고 두 때의 차를 구한다',ARRAY['4수04-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C9','math',4,2,'u5',5,'가장 많이 변한 때와 앞날 짐작 — 선분이 가파를수록 많이 변한 것이고, 가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾으며, 흐름으로 앞날을 짐작한다',ARRAY['4수04-03']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C10','math',4,2,'u5',6,'자료를 모아 나타내기 — 시간에 따라 달라지는 주제를 정하고 믿을 수 있는 누리집에서 최근 자료를 출처와 함께 모아 표로 정리한 뒤 꺾은선그래프로 나타내 읽는다',ARRAY['4수04-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C11','math',4,2,'u5',7,'알맞은 그래프 고르기 — 그림그래프·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞고, 자료를 모은 목적과 특성을 함께 생각해 고르며 이어진 자료를 막대로 나타내도 틀린 것은 아니다',ARRAY['4수04-03']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u5-C12','math',4,2,'u5',8,'두 자료를 한 그래프에 — 같은 가로 눈금 위에 두 값을 찍고 선의 색과 이름표로 구별하며, 두 값의 차와 변화를 견주고, 물결선을 쓴 그래프와 쓰지 않은 그래프 모두 맞다',ARRAY['4수04-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X01','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C4']::text[],'가로와 세로를 바꾸어 읽거나 바꾸어 정한다 — 가로에 양을, 세로에 때를 놓는다','가로는 때, 세로는 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X02','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C5','M4-2-u5-C8']::text[],'세로 눈금 한 칸의 크기를 확인하지 않고 눈금 칸 수를 그대로 값으로 읽는다','눈금 한 칸이 얼마인지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X03','math',4,'u5',ARRAY['M4-2-u5-C1']::text[],'꺾은선그래프와 막대그래프·그림그래프를 구별하지 못한다','점과 선분으로 이었는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X04','math',4,'u5',ARRAY['M4-2-u5-C3']::text[],'조사하지 않은 때의 값은 전혀 알 수 없다고 하거나 이웃한 한쪽 값을 그대로 쓴다','이웃한 두 점을 이은 선분 위에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X05','math',4,'u5',ARRAY['M4-2-u5-C3','M4-2-u5-C6','M4-2-u5-C7']::text[],'물결선을 쓰면 값이 바뀌거나 물결선 아래 값이 사라진다고 생각한다 — 물결선의 쓰임을 모른다','물결선은 필요 없는 부분만 줄임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X06','math',4,'u5',ARRAY['M4-2-u5-C1','M4-2-u5-C4']::text[],'점을 가로 눈금의 순서대로 잇지 않거나 곡선으로 잇거나 잇지 않아도 된다고 생각한다','순서대로, 선분으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X07','math',4,'u5',ARRAY['M4-2-u5-C5']::text[],'세로 눈금 한 칸의 크기를 자료에 맞지 않게 정한다 — 가장 큰 값까지 못 나타내거나 값이 눈금 사이에 온다','가장 큰 값까지, 눈금 위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X08','math',4,'u5',ARRAY['M4-2-u5-C3','M4-2-u5-C5','M4-2-u5-C7']::text[],'세로 눈금 한 칸이 크든 작든 변화가 똑같이 보인다고 생각한다','한 칸이 작을수록 뚜렷') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X09','math',4,'u5',ARRAY['M4-2-u5-C6']::text[],'물결선을 자료의 수 범위 안이나 가장 큰 값 근처에 넣는다','0과 가장 작은 값 사이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X10','math',4,'u5',ARRAY['M4-2-u5-C8','M4-2-u5-C9']::text[],'오른쪽 위로 올라가면 줄어든 것, 아래로 내려가면 늘어난 것으로 거꾸로 읽는다','오른쪽 위 = 늘어남') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X11','math',4,'u5',ARRAY['M4-2-u5-C9']::text[],'가장 많이 변한 때를 늘어난 곳에서만 찾는다 — 줄어든 것도 변한 것임을 놓친다','줄어든 것도 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X12','math',4,'u5',ARRAY['M4-2-u5-C8','M4-2-u5-C9']::text[],'점이 가장 높은(값이 가장 큰) 때를 가장 많이 늘어나거나 변한 때로 생각한다 — 높이와 기울기를 섞는다','높이가 아니라 기울기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X13','math',4,'u5',ARRAY['M4-2-u5-C8']::text[],'선분이 평평한 곳(변하지 않은 때)을 읽지 못한다','평평하면 변화 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X14','math',4,'u5',ARRAY['M4-2-u5-C2','M4-2-u5-C7','M4-2-u5-C8']::text[],'두 때의 차를 구할 때 다른 때의 값을 쓰거나 차 대신 합을 구하거나 받아내림을 틀린다','묻는 두 때의 값으로 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X15','math',4,'u5',ARRAY['M4-2-u5-C10']::text[],'시간과 관계없는 자료(지역별·학교별 등)를 꺾은선그래프의 조사 주제로 고른다','시간에 따라 달라지는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X16','math',4,'u5',ARRAY['M4-2-u5-C10']::text[],'자료를 아무 곳에서나·오래된 것으로 모으거나 출처를 적지 않아도 된다고 생각한다','믿을 수 있는 곳, 최근, 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X17','math',4,'u5',ARRAY['M4-2-u5-C11']::text[],'자료를 모은 목적과 특성을 생각하지 않고 그래프를 고른다 — 항목끼리 견주는 자료에 꺾은선그래프를 고르거나 한 그래프가 언제나 좋다고 한다','견주기인지 변화인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X18','math',4,'u5',ARRAY['M4-2-u5-C11']::text[],'이어진 자료를 막대그래프로 나타내면 틀린 것이라고 생각한다','틀린 것은 아님, 쓰임이 다름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X19','math',4,'u5',ARRAY['M4-2-u5-C12']::text[],'두 자료를 나타낸 그래프에서 선(이름표)을 바꾸어 읽거나 두 값의 차를 잘못 읽는다','이름표로 선을 먼저 가리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X20','math',4,'u5',ARRAY['M4-2-u5-C12']::text[],'물결선을 쓴 그래프와 쓰지 않은 그래프 가운데 하나만 맞다고 생각한다','둘 다 맞음, 뚜렷함만 다름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u5-X21','math',4,'u5',ARRAY['M4-2-u5-C1','M4-2-u5-C2','M4-2-u5-C3','M4-2-u5-C4','M4-2-u5-C5','M4-2-u5-C6','M4-2-u5-C7','M4-2-u5-C8','M4-2-u5-C9','M4-2-u5-C10','M4-2-u5-C11','M4-2-u5-C12']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못↔바르게, 늘어난↔줄어든','물음의 핵심 낱말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#1','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',1,'mc','auto','시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?',ARRAY['M4-2-u5-X03']::text[],true,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프는 어떻게 그린 그래프인가요?","options":[{"t":"변화하는 양을 점으로 표시하고 점들을 선분으로 이은 그래프","correct":true},{"t":"수량을 막대 모양으로 나타낸 그래프","mis":"M4-2-u5-X03"},{"t":"수량을 그림의 크기와 수로 나타낸 그래프","mis":"M4-2-u5-X03"},{"t":"점을 찍고 곡선으로 부드럽게 이은 그래프","mis":"M4-2-u5-X06"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null},{"stem":"꺾은선그래프로 나타내기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"달마다 잰 나무의 키","correct":true},{"t":"우리 반 학생들이 좋아하는 과일","mis":"M4-2-u5-X15"},{"t":"도시별 도서관 수","mis":"M4-2-u5-X15"},{"t":"반별 안경 쓴 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#2','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C2',1,'mc','auto','아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 운동장의 기온","correct":true},{"t":"가로: 운동장의 기온, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 운동장의 기온, 세로: 운동장의 기온","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각, 세로에는 운동장의 기온을 °C 단위로 나타냈어요.","가로: 시각, 세로: 운동장의 기온이에요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,20,24,26,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 운동장의 기온","correct":true},{"t":"가로: 운동장의 기온, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 운동장의 기온, 세로: 운동장의 기온","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각, 세로에는 운동장의 기온을 °C 단위로 나타냈어요.","가로: 시각, 세로: 운동장의 기온이에요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[26,30,24,32,30]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 선인장 줄기의 길이","correct":true},{"t":"가로: 선인장 줄기의 길이, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 선인장 줄기의 길이, 세로: 선인장 줄기의 길이","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 선인장 줄기의 길이를 cm 단위로 나타냈어요.","가로: 월, 세로: 선인장 줄기의 길이예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[16,28,36,42,46]}],"step":2,"ymax":48,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#3','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C2',1,'sa','auto','「미세 먼지 나쁨 일수」 꺾은선그래프에서 세로 눈금 5칸이 5일을 나타내요. 세로 눈금 한 칸은 며칠을 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C2","difficulty":1,"kind":"sa","stem":"「미세 먼지 나쁨 일수」 꺾은선그래프에서 세로 눈금 5칸이 5일을 나타내요. 세로 눈금 한 칸은 며칠을 나타내나요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 눈금 5칸이 5일이에요.","한 칸은 5 ÷ 5로 구해요.","세로 눈금 한 칸은 1일이에요."],"variant_rule":{"alt":[{"stem":"「교실 온도」 꺾은선그래프에서 세로 눈금 5칸이 10 °C를 나타내요. 세로 눈금 한 칸은 몇 °C를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 5칸이 10 °C예요.","한 칸은 10 ÷ 5로 구해요.","세로 눈금 한 칸은 2 °C예요."],"asset":null},{"stem":"「줄넘기 기록」 꺾은선그래프에서 세로 눈금 5칸이 25회를 나타내요. 세로 눈금 한 칸은 몇 회를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 5칸이 25회예요.","한 칸은 25 ÷ 5로 구해요.","세로 눈금 한 칸은 5회예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#4','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',1,'mc','auto','아래 그래프는 무엇인가요?',ARRAY['M4-2-u5-X03']::text[],true,'{"seq":4,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"아래 그래프는 무엇인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["수량을 막대 모양으로 나타내면 막대그래프, 점을 찍고 선분으로 이으면 꺾은선그래프예요.","이 그래프는 점을 찍고 선분으로 이었어요.","그래서 꺾은선그래프예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[2,6,9,16,24]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수","mode":"line"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 그래프는 무엇인가요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["수량을 막대 모양으로 나타내면 막대그래프, 점을 찍고 선분으로 이으면 꺾은선그래프예요.","이 그래프는 막대로 나타냈어요.","그래서 막대그래프예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[100,85,130,120,70]}],"step":5,"ymax":135,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록","mode":"bar"}},{"stem":"이번에는 다른 그림이에요. 아래 그래프는 무엇인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["수량을 막대 모양으로 나타내면 막대그래프, 점을 찍고 선분으로 이으면 꺾은선그래프예요.","이 그래프는 점을 찍고 선분으로 이었어요.","그래서 꺾은선그래프예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[9,15,23,19,20]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수","mode":"line"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#5','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C2',2,'sa','auto','4월의 도서관에서 빌려 간 책 수는 몇 권인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C2","difficulty":2,"kind":"sa","stem":"4월의 도서관에서 빌려 간 책 수는 몇 권인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["세로 눈금 한 칸은 10권이에요.","4월의 점은 0에서 7칸 위에 있어요.","7 × 10 = 70 — 4월의 도서관에서 빌려 간 책 수는 70권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[200,70,170,80,190]}],"step":10,"ymax":210,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"},"variant_rule":{"alt":[{"stem":"4월의 해바라기의 키는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금 한 칸은 5 cm예요.","4월의 점은 0에서 6칸 위에 있어요.","6 × 5 = 30 — 4월의 해바라기의 키는 30 cm예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[30,50,55,65,100,125]}],"step":5,"ymax":130,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키"}},{"stem":"11시의 운동장의 기온은 몇 °C인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금 한 칸은 2 °C예요.","11시의 점은 0에서 15칸 위에 있어요.","15 × 2 = 30 — 11시의 운동장의 기온은 30 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[34,22,30,32,26]}],"step":2,"ymax":36,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#6','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C3',2,'mc','auto','7월에는 조사하지 않았어요. 7월의 해바라기의 키는 약 몇 cm였을까요?',ARRAY['M4-2-u5-X04']::text[],true,'{"seq":6,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"7월에는 조사하지 않았어요. 7월의 해바라기의 키는 약 몇 cm였을까요?","options":[{"t":"약 100 cm","correct":true},{"t":"약 70 cm","mis":"M4-2-u5-X04"},{"t":"약 130 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["6월과 8월의 두 점을 이은 선분을 봐요.","7월 위의 선분은 70 cm와 130 cm의 한가운데쯤을 지나요.","그래서 약 100 cm였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[35,65,70,null,130]}],"step":5,"ymax":135,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키"},"variant_rule":{"alt":[{"stem":"2020년에는 조사하지 않았어요. 2020년의 폭염 일수는 약 며칠이었을까요?","options":[{"t":"약 18일","correct":true},{"t":"약 16일","mis":"M4-2-u5-X04"},{"t":"약 20일","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["2019년과 2021년의 두 점을 이은 선분을 봐요.","2020년 위의 선분은 16일과 20일의 한가운데쯤을 지나요.","그래서 약 18일이었을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[6,10,16,null,20]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}},{"stem":"2017년에는 조사하지 않았어요. 2017년의 미세 먼지 나쁨 일수는 약 며칠이었을까요?","options":[{"t":"약 19일","correct":true},{"t":"약 12일","mis":"M4-2-u5-X04"},{"t":"약 26일","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["2016년과 2018년의 두 점을 이은 선분을 봐요.","2017년 위의 선분은 12일과 26일의 한가운데쯤을 지나요.","그래서 약 19일이었을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[12,null,26,19,15]}],"step":1,"ymax":27,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#7','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C3',2,'mc','auto','꺾은선그래프에서 물결선(≈)을 쓰면 어떤 점이 좋은가요?',ARRAY['M4-2-u5-X05']::text[],true,'{"seq":7,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"꺾은선그래프에서 물결선(≈)을 쓰면 어떤 점이 좋은가요?","options":[{"t":"필요 없는 부분을 줄여 변화하는 모습이 잘 보여요.","correct":true},{"t":"나타낼 값이 많아져요.","mis":"M4-2-u5-X05"},{"t":"자료의 값이 커져요.","mis":"M4-2-u5-X05"},{"t":"가로 눈금이 촘촘해져요.","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"variant_rule":{"alt":[{"stem":"물결선(≈)은 꺾은선그래프의 어디에 넣나요?","options":[{"t":"세로 눈금에서 필요 없는 아랫부분","correct":true},{"t":"가로 눈금의 맨 끝","mis":"M4-2-u5-X09"},{"t":"가장 큰 값 위쪽","mis":"M4-2-u5-X09"},{"t":"점과 점 사이","mis":"M4-2-u5-X06"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null},{"stem":"물결선을 넣고 세로 눈금 한 칸을 작게 하면 그래프가 어떻게 달라지나요?","options":[{"t":"변화하는 모습이 더 뚜렷하게 보여요.","correct":true},{"t":"자료의 값이 달라져요.","mis":"M4-2-u5-X05"},{"t":"변화하는 모습이 덜 보여요.","mis":"M4-2-u5-X08"},{"t":"가로 눈금이 사라져요.","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#8','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C2',2,'sa','auto','줄넘기 기록은 3월부터 7월까지 몇 회 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C2","difficulty":2,"kind":"sa","stem":"줄넘기 기록은 3월부터 7월까지 몇 회 늘어났나요? 숫자로 쓰세요.","answer":["95"],"explanation":["3월의 값은 25회, 7월의 값은 120회예요.","처음과 끝 두 때의 값만 써서 빼요.","120 − 25 = 95 — 95회 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[25,45,75,115,120]}],"step":5,"ymax":125,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"교실 온도는 9시부터 14시까지 몇 °C 늘어났나요? 숫자로 쓰세요.","answer":["3"],"explanation":["9시의 값은 17 °C, 14시의 값은 20 °C예요.","처음과 끝 두 때의 값만 써서 빼요.","20 − 17 = 3 — 3 °C 늘어났어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[17,24,23,21,15,20]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}},{"stem":"나무의 키는 3월부터 11월까지 몇 cm 늘어났나요? 숫자로 쓰세요.","answer":["140"],"explanation":["3월의 값은 60 cm, 11월의 값은 200 cm예요.","처음과 끝 두 때의 값만 써서 빼요.","200 − 60 = 140 — 140 cm 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","5월","7월","9월","11월"],"series":[{"vals":[60,100,110,170,200]}],"step":10,"ymax":210,"ylab":"(cm)","xlab":"(월)","title":"월별 나무의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#9','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C1',2,'mc','auto','같은 자료를 막대그래프와 꺾은선그래프로 나타냈어요. 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X03']::text[],true,'{"seq":9,"concept":"M4-2-u5-C1","difficulty":2,"kind":"mc","stem":"같은 자료를 막대그래프와 꺾은선그래프로 나타냈어요. 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"막대그래프는 막대로, 꺾은선그래프는 점과 선분으로 나타내요.","correct":true},{"t":"나타낸 자료가 서로 달라요.","mis":"M4-2-u5-X03"},{"t":"꺾은선그래프에는 가로 눈금이 없어요.","mis":"M4-2-u5-X03"},{"t":"막대그래프에만 세로 눈금이 있어요.","mis":"M4-2-u5-X03"}],"explanation":["같은 자료를 막대그래프와 꺾은선그래프로 모두 나타낼 수 있어요.","막대그래프는 막대로, 꺾은선그래프는 점과 선분으로 나타내요.","선분이 기울어진 모양으로 늘어남·줄어듦이 보여서 변화를 알아보기 좋아요."],"variant_rule":{"alt":[{"stem":"같은 자료를 막대그래프와 꺾은선그래프로 나타냈어요. 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 자료를 나타내요.","correct":true},{"t":"둘 다 막대로 나타내요.","mis":"M4-2-u5-X03"},{"t":"둘 다 점을 선분으로 이어요.","mis":"M4-2-u5-X03"},{"t":"둘 다 물결선이 꼭 있어요.","mis":"M4-2-u5-X05"}],"explanation":["같은 자료를 막대그래프와 꺾은선그래프로 모두 나타낼 수 있어요.","막대그래프는 막대로, 꺾은선그래프는 점과 선분으로 나타내요.","선분이 기울어진 모양으로 늘어남·줄어듦이 보여서 변화를 알아보기 좋아요."],"asset":null},{"stem":"나무의 키가 어떻게 달라졌는지 한눈에 알아보기에 더 좋은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["같은 자료를 막대그래프와 꺾은선그래프로 모두 나타낼 수 있어요.","막대그래프는 막대로, 꺾은선그래프는 점과 선분으로 나타내요.","선분이 기울어진 모양으로 늘어남·줄어듦이 보여서 변화를 알아보기 좋아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_basic#10','math',4,2,'u5','L02','g4_2_math_u5_L02_basic','lesson_basic','M4-2-u5-C3',3,'sa','auto','7월에는 조사하지 않았어요. 7월의 값이 6월의 값과 8월의 값의 꼭 한가운데였다면 7월의 자외선 지수 매우 높음 일수는 며칠이었을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u5-C3","difficulty":3,"kind":"sa","stem":"7월에는 조사하지 않았어요. 7월의 값이 6월의 값과 8월의 값의 꼭 한가운데였다면 7월의 자외선 지수 매우 높음 일수는 며칠이었을까요? 숫자로 쓰세요.","answer":["21"],"explanation":["6월의 값은 18일, 8월의 값은 24일이에요.","두 값의 차는 6이고, 한가운데는 그 절반만큼 커진 곳이에요.","18과 24의 한가운데는 21일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[2,13,18,null,24]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"6월에는 조사하지 않았어요. 6월의 값이 5월의 값과 7월의 값의 꼭 한가운데였다면 6월의 줄넘기 기록은 몇 회였을까요? 숫자로 쓰세요.","answer":["45"],"explanation":["5월의 값은 50회, 7월의 값은 40회예요.","두 값의 차는 10이고, 한가운데는 그 절반만큼 커진 곳이에요.","50과 40의 한가운데는 45회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[25,75,50,null,40]}],"step":5,"ymax":80,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"11시에는 조사하지 않았어요. 11시의 값이 10시의 값과 12시의 값의 꼭 한가운데였다면 11시의 운동장의 기온은 몇 °C였을까요? 숫자로 쓰세요.","answer":["16"],"explanation":["10시의 값은 12 °C, 12시의 값은 20 °C예요.","두 값의 차는 8이고, 한가운데는 그 절반만큼 커진 곳이에요.","12와 20의 한가운데는 16 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[8,12,null,20,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#1','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',2,'sa','auto','5월의 자외선 지수 매우 높음 일수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u5-C2","difficulty":2,"kind":"sa","stem":"5월의 자외선 지수 매우 높음 일수는 며칠인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["세로 눈금 한 칸은 1일이에요.","5월의 점을 따라 세로 눈금을 읽어요.","5월의 자외선 지수 매우 높음 일수는 20일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[13,20,19,8,6]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"6월의 선인장 줄기의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금 한 칸은 2 cm예요.","6월의 점은 0에서 6칸 위에 있어요.","6 × 2 = 12 — 6월의 선인장 줄기의 길이는 12 cm예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월","11월"],"series":[{"vals":[12,24,28,30,36,46]}],"step":2,"ymax":48,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"}},{"stem":"6월의 도서관에서 빌려 간 책 수는 몇 권인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["세로 눈금 한 칸은 10권이에요.","6월의 점은 0에서 4칸 위에 있어요.","4 × 10 = 40 — 6월의 도서관에서 빌려 간 책 수는 40권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[290,250,120,40,150]}],"step":10,"ymax":300,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#2','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C1',2,'ox','auto','꺾은선그래프는 점과 점 사이를 선분으로 이어요.',ARRAY['M4-2-u5-X06']::text[],true,'{"seq":2,"concept":"M4-2-u5-C1","difficulty":2,"kind":"ox","stem":"꺾은선그래프는 점과 점 사이를 선분으로 이어요.","answer":"O","reason_options":[{"t":"변화하는 양을 점으로 표시하고 선분으로 잇는 그래프라서","correct":true},{"t":"점은 곡선으로 이어야 해서","mis":"M4-2-u5-X06"}],"mis":"M4-2-u5-X06","explanation":["꺾은선그래프는 점을 찍고 선분으로 이은 그래프예요.","세로 눈금 한 칸의 크기는 그래프마다 달라 먼저 확인해요.","선분 위에서 조사하지 않은 때의 값도 짐작할 수 있어요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프에서는 조사하지 않은 때의 값을 전혀 짐작할 수 없어요.","answer":"X","reason_options":[{"t":"이웃한 두 점을 이은 선분으로 사이 값을 짐작할 수 있어서","correct":true},{"t":"점이 찍힌 때의 값만 알 수 있어서","mis":"M4-2-u5-X04"}],"explanation":["꺾은선그래프는 점을 찍고 선분으로 이은 그래프예요.","세로 눈금 한 칸의 크기는 그래프마다 달라 먼저 확인해요.","선분 위에서 조사하지 않은 때의 값도 짐작할 수 있어요."],"asset":null},{"stem":"막대그래프보다 꺾은선그래프가 시간에 따른 변화를 알아보기 쉬워요.","answer":"O","reason_options":[{"t":"선분이 기울어진 모양으로 늘어남과 줄어듦이 보여서","correct":true},{"t":"두 그래프는 언제나 똑같이 보여서","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 점을 찍고 선분으로 이은 그래프예요.","세로 눈금 한 칸의 크기는 그래프마다 달라 먼저 확인해요.","선분 위에서 조사하지 않은 때의 값도 짐작할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#3','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C3',3,'mc','auto','「시각별 수영장 물의 온도」를 두 그래프로 나타냈어요. 가 그래프는 물결선을 넣고 세로 눈금 한 칸을 1 °C로 했어요, 나 그래프는 0부터 세로 눈금 한 칸을 10 °C로 했어요. 달라지는 모습이 더 뚜렷한 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X08','M4-2-u5-X05']::text[],true,'{"seq":3,"concept":"M4-2-u5-C3","difficulty":3,"kind":"mc","stem":"「시각별 수영장 물의 온도」를 두 그래프로 나타냈어요. 가 그래프는 물결선을 넣고 세로 눈금 한 칸을 1 °C로 했어요, 나 그래프는 0부터 세로 눈금 한 칸을 10 °C로 했어요. 달라지는 모습이 더 뚜렷한 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 세로 눈금 한 칸이 작아서","correct":true},{"t":"나 — 세로 눈금 한 칸이 커서","mis":"M4-2-u5-X08"},{"t":"나 — 물결선이 없어서","mis":"M4-2-u5-X05"},{"t":"두 그래프가 똑같아요.","mis":"M4-2-u5-X08"}],"explanation":["두 그래프가 나타내는 값은 같아요.","가 그래프는 물결선으로 필요 없는 부분을 줄이고 한 칸을 1 °C로 작게 잡았어요.","그래서 가 그래프가 변화가 더 뚜렷해요."],"variant_rule":{"alt":[{"stem":"「연도별 어느 마을의 가구 수」를 두 그래프로 나타냈어요. 가 그래프는 0부터 세로 눈금 한 칸을 50가구로 했어요, 나 그래프는 물결선을 넣고 세로 눈금 한 칸을 10가구로 했어요. 달라지는 모습이 더 뚜렷한 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 세로 눈금 한 칸이 작아서","correct":true},{"t":"가 — 세로 눈금 한 칸이 커서","mis":"M4-2-u5-X08"},{"t":"가 — 물결선이 없어서","mis":"M4-2-u5-X05"},{"t":"두 그래프가 똑같아요.","mis":"M4-2-u5-X08"}],"explanation":["두 그래프가 나타내는 값은 같아요.","나 그래프는 물결선으로 필요 없는 부분을 줄이고 한 칸을 10가구로 작게 잡았어요.","그래서 나 그래프가 변화가 더 뚜렷해요."],"asset":null},{"stem":"「연도별 어느 도시의 인구수」를 두 그래프로 나타냈어요. 가 그래프는 물결선을 넣고 세로 눈금 한 칸을 1만 명으로 했어요, 나 그래프는 0부터 세로 눈금 한 칸을 10만 명으로 했어요. 달라지는 모습이 더 뚜렷한 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 — 세로 눈금 한 칸이 작아서","correct":true},{"t":"나 — 세로 눈금 한 칸이 커서","mis":"M4-2-u5-X08"},{"t":"나 — 물결선이 없어서","mis":"M4-2-u5-X05"},{"t":"두 그래프가 똑같아요.","mis":"M4-2-u5-X08"}],"explanation":["두 그래프가 나타내는 값은 같아요.","가 그래프는 물결선으로 필요 없는 부분을 줄이고 한 칸을 1만 명으로 작게 잡았어요.","그래서 가 그래프가 변화가 더 뚜렷해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#4','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',3,'mc','auto','3월의 줄넘기 기록은 몇 회인가요?',ARRAY['M4-2-u5-X02']::text[],true,'{"seq":4,"concept":"M4-2-u5-C2","difficulty":3,"kind":"mc","stem":"3월의 줄넘기 기록은 몇 회인가요?","options":[{"t":"75회","correct":true},{"t":"15회","mis":"M4-2-u5-X02"},{"t":"80회","mis":"M4-2-u5-X02"},{"t":"70회","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 5회예요.","3월의 점은 0에서 15칸 위에 있어요.","15 × 5 = 75 — 3월의 줄넘기 기록은 75회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[75,30,85,80,145]}],"step":5,"ymax":150,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"4월의 도서관에서 빌려 간 책 수는 몇 권인가요?","options":[{"t":"170권","correct":true},{"t":"17권","mis":"M4-2-u5-X02"},{"t":"180권","mis":"M4-2-u5-X02"},{"t":"160권","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 10권이에요.","4월의 점은 0에서 17칸 위에 있어요.","17 × 10 = 170 — 4월의 도서관에서 빌려 간 책 수는 170권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[120,170,180,250,270,300]}],"step":10,"ymax":310,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"11시의 운동장의 기온은 몇 °C인가요?","options":[{"t":"18 °C","correct":true},{"t":"9 °C","mis":"M4-2-u5-X02"},{"t":"20 °C","mis":"M4-2-u5-X02"},{"t":"16 °C","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 2 °C예요.","11시의 점은 0에서 9칸 위에 있어요.","9 × 2 = 18 — 11시의 운동장의 기온은 18 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[14,12,18,14,26]}],"step":2,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#5','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C3',3,'sa','auto','11시에는 조사하지 않았어요. 11시의 값이 10시의 값과 12시의 값의 꼭 한가운데였다면 11시의 교실 온도는 몇 °C였을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C3","difficulty":3,"kind":"sa","stem":"11시에는 조사하지 않았어요. 11시의 값이 10시의 값과 12시의 값의 꼭 한가운데였다면 11시의 교실 온도는 몇 °C였을까요? 숫자로 쓰세요.","answer":["21"],"explanation":["10시의 값은 18 °C, 12시의 값은 24 °C예요.","두 값의 차는 6이고, 한가운데는 그 절반만큼 커진 곳이에요.","18과 24의 한가운데는 21 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[23,18,null,24,17]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"5월에는 조사하지 않았어요. 5월의 값이 4월의 값과 6월의 값의 꼭 한가운데였다면 5월의 도서관에서 빌려 간 책 수는 몇 권이었을까요? 숫자로 쓰세요.","answer":["160"],"explanation":["4월의 값은 140권, 6월의 값은 180권이에요.","두 값의 차는 40이고, 한가운데는 그 절반만큼 커진 곳이에요.","140과 180의 한가운데는 160권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[200,140,null,180,250]}],"step":10,"ymax":260,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"10시에는 조사하지 않았어요. 10시의 값이 9시의 값과 11시의 값의 꼭 한가운데였다면 10시의 교실 온도는 몇 °C였을까요? 숫자로 쓰세요.","answer":["16"],"explanation":["9시의 값은 14 °C, 11시의 값은 18 °C예요.","두 값의 차는 4이고, 한가운데는 그 절반만큼 커진 곳이에요.","14와 18의 한가운데는 16 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[14,null,18,23,27]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#6','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C1',3,'error','auto','꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X02','M4-2-u5-X21']::text[],true,'{"seq":6,"concept":"M4-2-u5-C1","difficulty":3,"kind":"error","stem":"꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「꺾은선그래프에서 세로 눈금 한 칸은 언제나 1이야.」","correct":true,"mis_target":"M4-2-u5-X02"},{"t":"시우 — 「꺾은선그래프는 시간에 따른 변화를 보기 좋아.」","mis":"M4-2-u5-X21"},{"t":"은우 — 「가로와 세로가 무엇인지 먼저 봐야 해.」","mis":"M4-2-u5-X21"},{"t":"하랑 — 「물결선으로 필요 없는 부분을 줄일 수 있어.」","mis":"M4-2-u5-X21"}],"explanation":["꺾은선그래프는 점을 찍고 선분으로 이은 그래프예요.","서윤의 말은 꺾은선그래프의 성질과 맞지 않아요.","세로 눈금 한 칸은 그래프마다 다르고, 선분으로 사이 값을 짐작할 수 있어요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「조사하지 않은 달의 값은 짐작할 수 없어.」","correct":true,"mis_target":"M4-2-u5-X04"},{"t":"은우 — 「가로와 세로가 무엇인지 먼저 봐야 해.」","mis":"M4-2-u5-X21"},{"t":"하랑 — 「물결선으로 필요 없는 부분을 줄일 수 있어.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「점을 찍고 선분으로 이어.」","mis":"M4-2-u5-X21"}],"explanation":["꺾은선그래프는 점을 찍고 선분으로 이은 그래프예요.","시우의 말은 꺾은선그래프의 성질과 맞지 않아요.","세로 눈금 한 칸은 그래프마다 다르고, 선분으로 사이 값을 짐작할 수 있어요."],"asset":null},{"stem":"꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「꺾은선그래프는 점을 곡선으로 부드럽게 이어.」","correct":true,"mis_target":"M4-2-u5-X06"},{"t":"하랑 — 「물결선으로 필요 없는 부분을 줄일 수 있어.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「점을 찍고 선분으로 이어.」","mis":"M4-2-u5-X21"},{"t":"준서 — 「꺾은선그래프는 시간에 따른 변화를 보기 좋아.」","mis":"M4-2-u5-X21"}],"explanation":["꺾은선그래프는 점을 찍고 선분으로 이은 그래프예요.","은우의 말은 꺾은선그래프의 성질과 맞지 않아요.","세로 눈금 한 칸은 그래프마다 다르고, 선분으로 사이 값을 짐작할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#7','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',3,'sa','auto','「나무의 키」 꺾은선그래프에서 세로 눈금 5칸이 50 cm를 나타내요. 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u5-C2","difficulty":3,"kind":"sa","stem":"「나무의 키」 꺾은선그래프에서 세로 눈금 5칸이 50 cm를 나타내요. 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 5칸이 50 cm예요.","한 칸은 50 ÷ 5로 구해요.","세로 눈금 한 칸은 10 cm예요."],"variant_rule":{"alt":[{"stem":"「빌려 간 책 수」 꺾은선그래프에서 세로 눈금 5칸이 100권을 나타내요. 세로 눈금 한 칸은 몇 권을 나타내나요? 숫자로 쓰세요.","answer":["20"],"explanation":["세로 눈금 5칸이 100권이에요.","한 칸은 100 ÷ 5로 구해요.","세로 눈금 한 칸은 20권이에요."],"asset":null},{"stem":"「선인장 줄기의 길이」 꺾은선그래프에서 세로 눈금 10칸이 20 cm를 나타내요. 세로 눈금 한 칸은 몇 cm를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["세로 눈금 10칸이 20 cm예요.","한 칸은 20 ÷ 10으로 구해요.","세로 눈금 한 칸은 2 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#8','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',4,'sa','auto','나무의 키가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C2","difficulty":4,"kind":"sa","stem":"나무의 키가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 cm인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["이웃한 두 때의 차를 차례로 구해요: 30, 20, 10, 70.","선분이 가장 가파른 곳은 9월과 11월 사이예요.","가장 많이 늘어난 정도는 70 cm예요."],"asset":{"type":"lgraph","xs":["3월","5월","7월","9월","11월"],"series":[{"vals":[60,90,110,120,190]}],"step":10,"ymax":200,"ylab":"(cm)","xlab":"(월)","title":"월별 나무의 키"},"variant_rule":{"alt":[{"stem":"폭염 일수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 며칠인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이웃한 두 때의 차를 차례로 구해요: 1, 3, 5, 2, 4.","선분이 가장 가파른 곳은 2019년과 2020년 사이예요.","가장 많이 늘어난 정도는 5일이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[5,6,9,14,16,20]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}},{"stem":"자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["이웃한 두 때의 차를 차례로 구해요: 1, 3, 11, 5, 2.","선분이 가장 가파른 곳은 6월과 7월 사이예요.","가장 많이 늘어난 정도는 11일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[2,3,6,17,22,24]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#9','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C2',4,'sa','auto','물결선이 있는 꺾은선그래프예요. 물결선 바로 위 세로 눈금이 30이고 세로 눈금 5칸이 10 °C를 나타내요. 어떤 점이 물결선 바로 위 눈금에서 7칸 위에 있다면 그 점의 값은 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C2","difficulty":4,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 물결선 바로 위 세로 눈금이 30이고 세로 눈금 5칸이 10 °C를 나타내요. 어떤 점이 물결선 바로 위 눈금에서 7칸 위에 있다면 그 점의 값은 몇 °C인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["세로 눈금 한 칸은 10 ÷ 5 = 2 °C예요.","물결선 위 눈금에서 7칸 위는 7 × 2 = 14만큼 더 큰 값이에요.","30 + 14 = 44 — 44 °C예요."],"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 물결선 바로 위 세로 눈금이 100이고 세로 눈금 5칸이 50 cm를 나타내요. 어떤 점이 물결선 바로 위 눈금에서 4칸 위에 있다면 그 점의 값은 몇 cm인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["세로 눈금 한 칸은 50 ÷ 5 = 10 cm예요.","물결선 위 눈금에서 4칸 위는 4 × 10 = 40만큼 더 큰 값이에요.","100 + 40 = 140 — 140 cm예요."],"asset":null},{"stem":"물결선이 있는 꺾은선그래프예요. 물결선 바로 위 세로 눈금이 20이고 세로 눈금 5칸이 20일을 나타내요. 어떤 점이 물결선 바로 위 눈금에서 9칸 위에 있다면 그 점의 값은 며칠인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["세로 눈금 한 칸은 20 ÷ 5 = 4일이에요.","물결선 위 눈금에서 9칸 위는 9 × 4 = 36만큼 더 큰 값이에요.","20 + 36 = 56 — 56일이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L02_challenge#10','math',4,2,'u5','L02','g4_2_math_u5_L02_challenge','lesson_challenge','M4-2-u5-C1',4,'essay','teacher','같은 「월별 나무의 키」를 막대그래프와 꺾은선그래프로 나타냈어요. 나무의 키가 어떻게 달라졌는지 알아보기에 어느 그래프가 더 좋은지와 그 까닭을 쓰고, 키를 재지 않은 달의 키를 짐작하는 방법도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C1","difficulty":4,"kind":"essay","stem":"같은 「월별 나무의 키」를 막대그래프와 꺾은선그래프로 나타냈어요. 나무의 키가 어떻게 달라졌는지 알아보기에 어느 그래프가 더 좋은지와 그 까닭을 쓰고, 키를 재지 않은 달의 키를 짐작하는 방법도 써 보세요.","answer_guide":{"answer":"예: 꺾은선그래프가 더 좋다. 점들을 선분으로 이어서 선분이 기울어진 모양으로 키가 얼마나 늘어났는지 한눈에 보이기 때문이다. 키를 재지 않은 달은 앞뒤 두 달의 점을 이은 선분이 그 달을 지나는 곳을 읽어 짐작한다.","scoring_points":["꺾은선그래프를 골랐는가","선분의 기울어진 모양으로 변화가 보인다고 썼는가","이웃한 두 점을 이은 선분으로 짐작한다고 썼는가"]},"explanation":["꺾은선그래프는 점을 선분으로 이어요.","선분이 가파를수록 많이 자란 거예요.","재지 않은 달은 앞뒤 두 점을 이은 선분 위에서 읽어요."],"asset":{"type":"lgraph","xs":["3월","5월","7월","9월","11월"],"series":[{"vals":[60,90,110,140,150]}],"step":10,"ymax":160,"ylab":"(cm)","xlab":"(월)","title":"월별 나무의 키"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#1','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',1,'mc','auto','표를 보고 꺾은선그래프로 나타낼 때 맨 마지막에 하는 일은 무엇인가요?',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":1,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"표를 보고 꺾은선그래프로 나타낼 때 맨 마지막에 하는 일은 무엇인가요?","options":[{"t":"점을 찍고 순서대로 선분으로 이어요.","correct":true},{"t":"제목을 써요.","mis":"M4-2-u5-X21"},{"t":"가로와 세로에 나타낼 것을 정해요.","mis":"M4-2-u5-X21"},{"t":"세로 눈금 한 칸의 크기를 정해요.","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸의 크기를 정할 때 꼭 생각해야 하는 것은 무엇인가요?","options":[{"t":"가장 큰 값까지 나타낼 수 있는지","correct":true},{"t":"가장 작은 값만 나타낼 수 있는지","mis":"M4-2-u5-X07"},{"t":"가로 눈금이 몇 개인지","mis":"M4-2-u5-X07"},{"t":"제목이 얼마나 긴지","mis":"M4-2-u5-X07"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null},{"stem":"꺾은선그래프로 나타내는 다섯 걸음 가운데 맨 처음에 하는 일은 무엇인가요?","options":[{"t":"알맞은 제목을 써요.","correct":true},{"t":"점을 찍어요.","mis":"M4-2-u5-X21"},{"t":"점을 선분으로 이어요.","mis":"M4-2-u5-X21"},{"t":"세로 눈금 한 칸의 크기를 정해요.","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#2','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',1,'mc','auto','「월별 해바라기의 키」를 꺾은선그래프로 나타내려고 해요. 가로와 세로에 무엇을 나타내야 하나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":2,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"「월별 해바라기의 키」를 꺾은선그래프로 나타내려고 해요. 가로와 세로에 무엇을 나타내야 하나요?","options":[{"t":"가로: 월, 세로: 해바라기의 키","correct":true},{"t":"가로: 해바라기의 키, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 해바라기의 키, 세로: 해바라기의 키","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","때(월)는 가로에, 양(해바라기의 키)은 세로에 나타내요.","가로: 월, 세로: 해바라기의 키예요."],"variant_rule":{"alt":[{"stem":"「연도별 미세 먼지 나쁨 일수」를 꺾은선그래프로 나타내려고 해요. 가로와 세로에 무엇을 나타내야 하나요?","options":[{"t":"가로: 연도, 세로: 미세 먼지 나쁨 일수","correct":true},{"t":"가로: 미세 먼지 나쁨 일수, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 미세 먼지 나쁨 일수, 세로: 미세 먼지 나쁨 일수","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","때(연도)는 가로에, 양(미세 먼지 나쁨 일수)은 세로에 나타내요.","가로: 연도, 세로: 미세 먼지 나쁨 일수예요."],"asset":null},{"stem":"「연도별 폭염 일수」를 꺾은선그래프로 나타내려고 해요. 가로와 세로에 무엇을 나타내야 하나요?","options":[{"t":"가로: 연도, 세로: 폭염 일수","correct":true},{"t":"가로: 폭염 일수, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 연도, 세로: 연도","mis":"M4-2-u5-X01"},{"t":"가로: 폭염 일수, 세로: 폭염 일수","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","때(연도)는 가로에, 양(폭염 일수)은 세로에 나타내요.","가로: 연도, 세로: 폭염 일수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#3','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',1,'sa','auto','표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["125"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 125회예요.","그래서 세로 눈금은 적어도 125회까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[20,35,75,125,60],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["32"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 32 °C예요.","그래서 세로 눈금은 적어도 32 °C까지 나타내요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[10,20,22,28,32],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"}},{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 며칠까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["23"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 23일이에요.","그래서 세로 눈금은 적어도 23일까지 나타내요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021","2022"],"counts":[20,15,14,23,13,9],"vh":"폭염 일수","unit":"일","title":"연도별 폭염 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#4','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',1,'mc','auto','가로 눈금과 세로 눈금이 만나는 곳에는 무엇을 하나요?',ARRAY['M4-2-u5-X03','M4-2-u5-X05']::text[],true,'{"seq":4,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"가로 눈금과 세로 눈금이 만나는 곳에는 무엇을 하나요?","options":[{"t":"점을 찍어요.","correct":true},{"t":"막대를 그려요.","mis":"M4-2-u5-X03"},{"t":"물결선을 넣어요.","mis":"M4-2-u5-X05"},{"t":"그림을 붙여요.","mis":"M4-2-u5-X03"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"점을 이을 때 지켜야 할 것은 무엇인가요?","options":[{"t":"가로 눈금의 순서대로 선분으로 이어요.","correct":true},{"t":"큰 값부터 차례로 이어요.","mis":"M4-2-u5-X06"},{"t":"곡선으로 부드럽게 이어요.","mis":"M4-2-u5-X06"},{"t":"이웃하지 않은 점끼리 이어요.","mis":"M4-2-u5-X06"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null},{"stem":"연도별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"가로: 년, 세로: 일","correct":true},{"t":"가로: 일, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 년, 세로: 년","mis":"M4-2-u5-X01"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#5','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',2,'mc','auto','선인장 줄기의 길이는 8 cm, 18 cm, 20 cm, 26 cm, 28 cm예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?',ARRAY['M4-2-u5-X07']::text[],true,'{"seq":5,"concept":"M4-2-u5-C5","difficulty":2,"kind":"mc","stem":"선인장 줄기의 길이는 8 cm, 18 cm, 20 cm, 26 cm, 28 cm예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?","options":[{"t":"2 cm","correct":true},{"t":"5 cm","mis":"M4-2-u5-X07"},{"t":"10 cm","mis":"M4-2-u5-X07"},{"t":"1 cm","mis":"M4-2-u5-X07"}],"explanation":["값이 모두 2의 배수인지 살펴봐요.","2보다 큰 칸으로 하면 눈금 사이에 오는 값이 생기고, 더 작은 칸으로 하면 판이 길어져요.","그래서 세로 눈금 한 칸은 2 cm로 해요."],"variant_rule":{"alt":[{"stem":"줄넘기 기록은 35회, 40회, 50회, 55회, 60회예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?","options":[{"t":"5회","correct":true},{"t":"10회","mis":"M4-2-u5-X07"},{"t":"20회","mis":"M4-2-u5-X07"},{"t":"1회","mis":"M4-2-u5-X07"}],"explanation":["값이 모두 5의 배수인지 살펴봐요.","5보다 큰 칸으로 하면 눈금 사이에 오는 값이 생기고, 더 작은 칸으로 하면 판이 길어져요.","그래서 세로 눈금 한 칸은 5회로 해요."],"asset":null},{"stem":"빌려 간 책 수는 40권, 60권, 70권, 90권, 140권이에요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?","options":[{"t":"10권","correct":true},{"t":"20권","mis":"M4-2-u5-X07"},{"t":"1권","mis":"M4-2-u5-X07"},{"t":"2권","mis":"M4-2-u5-X07"}],"explanation":["값이 모두 10의 배수인지 살펴봐요.","10보다 큰 칸으로 하면 눈금 사이에 오는 값이 생기고, 더 작은 칸으로 하면 판이 길어져요.","그래서 세로 눈금 한 칸은 10권로 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#6','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',2,'sa','auto','세로 눈금 한 칸이 2 cm인 꺾은선그래프예요. 10 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 2 cm인 꺾은선그래프예요. 10 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸이 2 cm이니 한 칸 올라갈 때마다 2씩 커져요.","10 ÷ 2 = 5로 구해요.","10 cm는 0에서 5째 눈금이에요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 5회인 꺾은선그래프예요. 35회는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸이 5회이니 한 칸 올라갈 때마다 5씩 커져요.","35 ÷ 5 = 7로 구해요.","35회는 0에서 7째 눈금이에요."],"asset":null},{"stem":"세로 눈금 한 칸이 10권인 꺾은선그래프예요. 60권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 칸이 10권이니 한 칸 올라갈 때마다 10씩 커져요.","60 ÷ 10 = 6으로 구해요.","60권은 0에서 6째 눈금이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#7','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',2,'mc','auto','아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07']::text[],true,'{"seq":7,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 순서대로 잇지 않았어요.","correct":true},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 순서대로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[24,17,19,25,21]}],"step":1,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도","order":[0,2,1,3,4]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 선분이 아니라 곡선으로 이었어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[30,45,90,110,145]}],"step":5,"ymax":150,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록","curve":true}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점만 찍고 선분으로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[3,4,10,5,2]}],"step":1,"ymax":11,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수","dots":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#8','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C4',2,'sa','auto','표를 보고 답하세요. 선인장 줄기의 길이는 6월부터 10월까지 몇 cm 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C4","difficulty":2,"kind":"sa","stem":"표를 보고 답하세요. 선인장 줄기의 길이는 6월부터 10월까지 몇 cm 늘어났나요? 숫자로 쓰세요.","answer":["34"],"explanation":["6월 8 cm, 10월 42 cm예요.","처음과 끝 두 때의 값으로 빼요.","42 − 8 = 34 — 34 cm 늘어났어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6월","7월","8월","9월","10월"],"counts":[8,20,34,36,42],"vh":"선인장 줄기의 길이","unit":"cm","title":"월별 선인장 줄기의 길이"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 운동장의 기온은 9시부터 13시까지 몇 °C 늘어났나요? 숫자로 쓰세요.","answer":["2"],"explanation":["9시 12 °C, 13시 14 °C예요.","처음과 끝 두 때의 값으로 빼요.","14 − 12 = 2 — 2 °C 늘어났어요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[12,22,24,18,14],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"}},{"stem":"표를 보고 답하세요. 해바라기의 키는 4월부터 8월까지 몇 cm 늘어났나요? 숫자로 쓰세요.","answer":["65"],"explanation":["4월 60 cm, 8월 125 cm예요.","처음과 끝 두 때의 값으로 빼요.","125 − 60 = 65 — 65 cm 늘어났어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월"],"counts":[60,95,105,120,125],"vh":"해바라기의 키","unit":"cm","title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#9','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',2,'sa','auto','가장 큰 값이 25일인 자료를 세로 눈금 한 칸이 1일인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C5","difficulty":2,"kind":"sa","stem":"가장 큰 값이 25일인 자료를 세로 눈금 한 칸이 1일인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["25"],"explanation":["가장 큰 값 25일까지 나타내야 해요.","한 칸이 1이니 25 ÷ 1을 구해요.","세로 눈금은 적어도 25칸이 있어야 해요."],"variant_rule":{"alt":[{"stem":"가장 큰 값이 32 cm인 자료를 세로 눈금 한 칸이 2 cm인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["16"],"explanation":["가장 큰 값 32 cm까지 나타내야 해요.","한 칸이 2이니 32 ÷ 2를 구해요.","세로 눈금은 적어도 16칸이 있어야 해요."],"asset":null},{"stem":"가장 큰 값이 85회인 자료를 세로 눈금 한 칸이 5회인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["17"],"explanation":["가장 큰 값 85회까지 나타내야 해요.","한 칸이 5이니 85 ÷ 5를 구해요.","세로 눈금은 적어도 17칸이 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_basic#10','math',4,2,'u5','L03','g4_2_math_u5_L03_basic','lesson_basic','M4-2-u5-C5',3,'mc','auto','세로 눈금 한 칸의 크기를 2 cm에서 10 cm로 바꾸면 그래프는 어떻게 되나요?',ARRAY['M4-2-u5-X08','M4-2-u5-X05']::text[],true,'{"seq":10,"concept":"M4-2-u5-C5","difficulty":3,"kind":"mc","stem":"세로 눈금 한 칸의 크기를 2 cm에서 10 cm로 바꾸면 그래프는 어떻게 되나요?","options":[{"t":"달라지는 모습이 덜 뚜렷하게 보여요.","correct":true},{"t":"값을 더 정확하게 찍을 수 있어요.","mis":"M4-2-u5-X08"},{"t":"자료의 값이 커져요.","mis":"M4-2-u5-X05"},{"t":"가로 눈금이 촘촘해져요.","mis":"M4-2-u5-X08"}],"explanation":["같은 차이도 한 칸이 작으면 여러 칸, 크면 적은 칸으로 그려져요.","한 칸이 작을수록 선분이 가파르게 보여 변화가 뚜렷해요.","한 칸이 크면 꺾은선이 평평해 보여 변화가 잘 안 보여요 — 값은 그대로예요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸의 크기를 10에서 2로 작게 하면 그래프는 어떻게 되나요?","options":[{"t":"달라지는 모습이 더 뚜렷하게 보여요.","correct":true},{"t":"자료의 값이 작아져요.","mis":"M4-2-u5-X05"},{"t":"달라지는 모습이 덜 보여요.","mis":"M4-2-u5-X08"},{"t":"점을 찍을 수 없어요.","mis":"M4-2-u5-X07"}],"explanation":["같은 차이도 한 칸이 작으면 여러 칸, 크면 적은 칸으로 그려져요.","한 칸이 작을수록 선분이 가파르게 보여 변화가 뚜렷해요.","한 칸이 크면 꺾은선이 평평해 보여 변화가 잘 안 보여요 — 값은 그대로예요."],"asset":null},{"stem":"값이 31, 33, 34, 36, 38인 자료를 세로 눈금 한 칸이 10인 그래프로 0부터 그리면 어떻게 보이나요?","options":[{"t":"꺾은선이 거의 평평해서 변화가 잘 안 보여요.","correct":true},{"t":"변화가 아주 뚜렷하게 보여요.","mis":"M4-2-u5-X08"},{"t":"모든 점을 눈금 위에 정확히 찍을 수 있어요.","mis":"M4-2-u5-X07"},{"t":"물결선이 저절로 생겨요.","mis":"M4-2-u5-X05"}],"explanation":["같은 차이도 한 칸이 작으면 여러 칸, 크면 적은 칸으로 그려져요.","한 칸이 작을수록 선분이 가파르게 보여 변화가 뚜렷해요.","한 칸이 크면 꺾은선이 평평해 보여 변화가 잘 안 보여요 — 값은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#1','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',2,'sa','auto','세로 눈금 한 칸이 2 °C인 꺾은선그래프예요. 18 °C는 0에서 몇째 눈금인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u5-C5","difficulty":2,"kind":"sa","stem":"세로 눈금 한 칸이 2 °C인 꺾은선그래프예요. 18 °C는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 2 °C이니 한 칸 올라갈 때마다 2씩 커져요.","18 ÷ 2 = 9로 구해요.","18 °C는 0에서 9째 눈금이에요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 20권인 꺾은선그래프예요. 80권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 칸이 20권이니 한 칸 올라갈 때마다 20씩 커져요.","80 ÷ 20 = 4로 구해요.","80권은 0에서 4째 눈금이에요."],"asset":null},{"stem":"세로 눈금 한 칸이 5 cm인 꺾은선그래프예요. 40 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 칸이 5 cm이니 한 칸 올라갈 때마다 5씩 커져요.","40 ÷ 5 = 8로 구해요.","40 cm는 0에서 8째 눈금이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#2','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',2,'mc','auto','아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07']::text[],true,'{"seq":2,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 순서대로 잇지 않았어요.","correct":true},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 순서대로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[26,22,30,18,20]}],"step":2,"ymax":32,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온","order":[0,2,1,3,4]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 선분이 아니라 곡선으로 이었어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[55,75,80,125,140]}],"step":5,"ymax":145,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키","curve":true}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점만 찍고 선분으로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[13,17,20,9,7]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수","dots":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#3','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',3,'mc','auto','운동장의 기온은 8 °C, 16 °C, 18 °C, 22 °C, 28 °C예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?',ARRAY['M4-2-u5-X07']::text[],true,'{"seq":3,"concept":"M4-2-u5-C5","difficulty":3,"kind":"mc","stem":"운동장의 기온은 8 °C, 16 °C, 18 °C, 22 °C, 28 °C예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?","options":[{"t":"2 °C","correct":true},{"t":"5 °C","mis":"M4-2-u5-X07"},{"t":"10 °C","mis":"M4-2-u5-X07"},{"t":"1 °C","mis":"M4-2-u5-X07"}],"explanation":["값이 모두 2의 배수인지 살펴봐요.","2보다 큰 칸으로 하면 눈금 사이에 오는 값이 생기고, 더 작은 칸으로 하면 판이 길어져요.","그래서 세로 눈금 한 칸은 2 °C로 해요."],"variant_rule":{"alt":[{"stem":"해바라기의 키는 20 cm, 25 cm, 35 cm, 55 cm, 60 cm예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?","options":[{"t":"5 cm","correct":true},{"t":"10 cm","mis":"M4-2-u5-X07"},{"t":"20 cm","mis":"M4-2-u5-X07"},{"t":"1 cm","mis":"M4-2-u5-X07"}],"explanation":["값이 모두 5의 배수인지 살펴봐요.","5보다 큰 칸으로 하면 눈금 사이에 오는 값이 생기고, 더 작은 칸으로 하면 판이 길어져요.","그래서 세로 눈금 한 칸은 5 cm로 해요."],"asset":null},{"stem":"나무의 키는 20 cm, 40 cm, 80 cm, 110 cm, 140 cm예요. 세로 눈금 한 칸을 얼마로 하면 모든 값을 눈금 위에 정확히 찍으면서 판이 가장 짧아질까요?","options":[{"t":"10 cm","correct":true},{"t":"20 cm","mis":"M4-2-u5-X07"},{"t":"1 cm","mis":"M4-2-u5-X07"},{"t":"2 cm","mis":"M4-2-u5-X07"}],"explanation":["값이 모두 10의 배수인지 살펴봐요.","10보다 큰 칸으로 하면 눈금 사이에 오는 값이 생기고, 더 작은 칸으로 하면 판이 길어져요.","그래서 세로 눈금 한 칸은 10 cm로 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#4','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',3,'sa','auto','가장 큰 값이 230권인 자료를 세로 눈금 한 칸이 10권인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"가장 큰 값이 230권인 자료를 세로 눈금 한 칸이 10권인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["23"],"explanation":["가장 큰 값 230권까지 나타내야 해요.","한 칸이 10이니 230 ÷ 10을 구해요.","세로 눈금은 적어도 23칸이 있어야 해요."],"variant_rule":{"alt":[{"stem":"가장 큰 값이 26 °C인 자료를 세로 눈금 한 칸이 2 °C인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["13"],"explanation":["가장 큰 값 26 °C까지 나타내야 해요.","한 칸이 2이니 26 ÷ 2를 구해요.","세로 눈금은 적어도 13칸이 있어야 해요."],"asset":null},{"stem":"가장 큰 값이 115 cm인 자료를 세로 눈금 한 칸이 5 cm인 꺾은선그래프로 나타내려고 해요. 0부터 세로 눈금은 적어도 몇 칸이 있어야 하나요? 숫자로 쓰세요.","answer":["23"],"explanation":["가장 큰 값 115 cm까지 나타내야 해요.","한 칸이 5이니 115 ÷ 5를 구해요.","세로 눈금은 적어도 23칸이 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#5','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',3,'ox','auto','점을 찍은 뒤에는 큰 값부터 차례로 선분으로 이어요.',ARRAY['M4-2-u5-X06']::text[],true,'{"seq":5,"concept":"M4-2-u5-C4","difficulty":3,"kind":"ox","stem":"점을 찍은 뒤에는 큰 값부터 차례로 선분으로 이어요.","answer":"X","reason_options":[{"t":"가로 눈금의 순서대로 이어야 해서","correct":true},{"t":"큰 값부터 이어야 변화가 잘 보여서","mis":"M4-2-u5-X06"}],"mis":"M4-2-u5-X06","explanation":["세로 눈금은 가장 큰 값까지, 값이 눈금 위에 오도록 정해요.","점은 가로 눈금의 순서대로 선분으로 이어요.","그래야 사이 값을 바르게 짐작할 수 있어요."],"variant_rule":{"alt":[{"stem":"세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요.","answer":"O","reason_options":[{"t":"가장 큰 값을 찍을 자리가 있어야 해서","correct":true},{"t":"가장 작은 값까지만 있으면 되어서","mis":"M4-2-u5-X07"}],"explanation":["세로 눈금은 가장 큰 값까지, 값이 눈금 위에 오도록 정해요.","점은 가로 눈금의 순서대로 선분으로 이어요.","그래야 사이 값을 바르게 짐작할 수 있어요."],"asset":null},{"stem":"점과 점은 곡선으로 부드럽게 이어도 돼요.","answer":"X","reason_options":[{"t":"곡선으로 이으면 사이 값을 바르게 짐작할 수 없어서","correct":true},{"t":"곡선이 더 보기 좋아서","mis":"M4-2-u5-X06"}],"explanation":["세로 눈금은 가장 큰 값까지, 값이 눈금 위에 오도록 정해요.","점은 가로 눈금의 순서대로 선분으로 이어요.","그래야 사이 값을 바르게 짐작할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#6','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',3,'error','auto','표를 보고 꺾은선그래프를 그린 친구들이에요. 잘못 그린 친구는 누구인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X21']::text[],true,'{"seq":6,"concept":"M4-2-u5-C4","difficulty":3,"kind":"error","stem":"표를 보고 꺾은선그래프를 그린 친구들이에요. 잘못 그린 친구는 누구인가요?","options":[{"t":"은우 — 「점을 큰 값부터 차례로 이었어.」","correct":true,"mis_target":"M4-2-u5-X06"},{"t":"하랑 — 「제목부터 썼어.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「가장 큰 값까지 세로 눈금을 나타냈어.」","mis":"M4-2-u5-X21"},{"t":"준서 — 「점을 가로 눈금 순서대로 선분으로 이었어.」","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — 제목, 가로·세로, 단위, 눈금 한 칸, 점 찍고 순서대로 잇기.","은우의 방법은 이 걸음과 맞지 않아요.","가로에는 때, 세로에는 양, 세로 눈금은 가장 큰 값까지, 점은 순서대로 이어요."],"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프를 그린 친구들이에요. 잘못 그린 친구는 누구인가요?","options":[{"t":"하랑 — 「세로 눈금을 가장 작은 값까지만 나타냈어.」","correct":true,"mis_target":"M4-2-u5-X07"},{"t":"지아 — 「가장 큰 값까지 세로 눈금을 나타냈어.」","mis":"M4-2-u5-X21"},{"t":"준서 — 「점을 가로 눈금 순서대로 선분으로 이었어.」","mis":"M4-2-u5-X21"},{"t":"민서 — 「눈금의 단위를 정했어.」","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — 제목, 가로·세로, 단위, 눈금 한 칸, 점 찍고 순서대로 잇기.","하랑의 방법은 이 걸음과 맞지 않아요.","가로에는 때, 세로에는 양, 세로 눈금은 가장 큰 값까지, 점은 순서대로 이어요."],"asset":null},{"stem":"표를 보고 꺾은선그래프를 그린 친구들이에요. 잘못 그린 친구는 누구인가요?","options":[{"t":"지아 — 「가로에 일수, 세로에 연도를 나타냈어.」","correct":true,"mis_target":"M4-2-u5-X01"},{"t":"준서 — 「점을 가로 눈금 순서대로 선분으로 이었어.」","mis":"M4-2-u5-X21"},{"t":"민서 — 「눈금의 단위를 정했어.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「제목부터 썼어.」","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — 제목, 가로·세로, 단위, 눈금 한 칸, 점 찍고 순서대로 잇기.","지아의 방법은 이 걸음과 맞지 않아요.","가로에는 때, 세로에는 양, 세로 눈금은 가장 큰 값까지, 점은 순서대로 이어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#7','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',3,'mc','auto','표를 보고 그린 꺾은선그래프예요. 표 — 3월 50 cm, 5월 70 cm, 7월 130 cm, 9월 160 cm, 11월 170 cm. 그래프에서 잘못 찍은 점은 어느 때인가요?',ARRAY['M4-2-u5-X02']::text[],true,'{"seq":7,"concept":"M4-2-u5-C4","difficulty":3,"kind":"mc","stem":"표를 보고 그린 꺾은선그래프예요. 표 — 3월 50 cm, 5월 70 cm, 7월 130 cm, 9월 160 cm, 11월 170 cm. 그래프에서 잘못 찍은 점은 어느 때인가요?","options":[{"t":"11월","correct":true},{"t":"3월","mis":"M4-2-u5-X02"},{"t":"5월","mis":"M4-2-u5-X02"},{"t":"7월","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 10 cm예요.","11월의 점은 150 cm에 찍혀 있지만 표에서는 170 cm예요.","잘못 찍은 점은 11월이에요."],"asset":{"type":"lgraph","xs":["3월","5월","7월","9월","11월"],"series":[{"vals":[50,70,130,160,150]}],"step":10,"ymax":170,"ylab":"(cm)","xlab":"(월)","title":"월별 나무의 키"},"variant_rule":{"alt":[{"stem":"표를 보고 그린 꺾은선그래프예요. 표 — 2016년 9일, 2017년 16일, 2018년 20일, 2019년 25일, 2020년 26일. 그래프에서 잘못 찍은 점은 어느 때인가요?","options":[{"t":"2016년","correct":true},{"t":"2017년","mis":"M4-2-u5-X02"},{"t":"2018년","mis":"M4-2-u5-X02"},{"t":"2019년","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 1일이에요.","2016년의 점은 11일에 찍혀 있지만 표에서는 9일이에요.","잘못 찍은 점은 2016년이에요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[11,16,20,25,26]}],"step":1,"ymax":27,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}},{"stem":"표를 보고 그린 꺾은선그래프예요. 표 — 2016년 6일, 2017년 8일, 2018년 11일, 2019년 15일, 2020년 25일. 그래프에서 잘못 찍은 점은 어느 때인가요?","options":[{"t":"2019년","correct":true},{"t":"2016년","mis":"M4-2-u5-X02"},{"t":"2017년","mis":"M4-2-u5-X02"},{"t":"2018년","mis":"M4-2-u5-X02"}],"explanation":["세로 눈금 한 칸은 1일이에요.","2019년의 점은 14일에 찍혀 있지만 표에서는 15일이에요.","잘못 찍은 점은 2019년이에요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[6,8,11,14,25]}],"step":1,"ymax":26,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#8','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C4',4,'sa','auto','표를 보고 답하세요. 자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C4","difficulty":4,"kind":"sa","stem":"표를 보고 답하세요. 자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["이웃한 두 때의 변화: +7, −11, +9, +1.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 5월과 6월 사이로 11일 줄어들었어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월"],"counts":[12,19,8,17,18],"vh":"자외선 지수 매우 높음 일수","unit":"일","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 교실 온도가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이웃한 두 때의 변화: −4, +2, +3, +5.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 12시와 13시 사이로 5 °C 늘어났어요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[21,17,19,22,27],"vh":"교실 온도","unit":"°C","title":"시각별 교실 온도"}},{"stem":"표를 보고 답하세요. 도서관에서 빌려 간 책 수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 권인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["이웃한 두 때의 변화: −90, +40, +10, −60.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 때는 3월과 4월 사이로 90권 줄어들었어요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[230,140,180,190,130],"vh":"도서관에서 빌려 간 책 수","unit":"권","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#9','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',4,'sa','auto','선인장 줄기의 길이는 4 cm, 24 cm, 32 cm, 34 cm, 36 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C5","difficulty":4,"kind":"sa","stem":"선인장 줄기의 길이는 4 cm, 24 cm, 32 cm, 34 cm, 36 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["가장 큰 값은 36 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 1이면 20칸으로 20까지밖에 못 나타내요.","한 칸이 2이면 40까지 나타낼 수 있고 값도 모두 2의 배수라 답은 2예요."],"variant_rule":{"alt":[{"stem":"줄넘기 기록은 45회, 60회, 70회, 75회, 85회예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 큰 값은 85회예요 — 20칸 안에 들어가야 해요.","한 칸이 2이면 20칸으로 40까지밖에 못 나타내요.","한 칸이 5이면 100까지 나타낼 수 있고 값도 모두 5의 배수라 답은 5예요."],"asset":null},{"stem":"빌려 간 책 수는 90권, 100권, 120권, 140권, 170권이에요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 큰 값은 170권이에요 — 20칸 안에 들어가야 해요.","한 칸이 5이면 20칸으로 100까지밖에 못 나타내요.","한 칸이 10이면 200까지 나타낼 수 있고 값도 모두 10의 배수라 답은 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L03_challenge#10','math',4,2,'u5','L03','g4_2_math_u5_L03_challenge','lesson_challenge','M4-2-u5-C5',4,'essay','teacher','선인장 줄기의 길이는 10, 18, 26, 30, 32 cm예요. 세로 눈금 한 칸을 2 cm로 정하면 좋은 까닭을 쓰고, 한 칸을 10 cm로 정하면 어떤 점이 아쉬운지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C5","difficulty":4,"kind":"essay","stem":"선인장 줄기의 길이는 10, 18, 26, 30, 32 cm예요. 세로 눈금 한 칸을 2 cm로 정하면 좋은 까닭을 쓰고, 한 칸을 10 cm로 정하면 어떤 점이 아쉬운지 써 보세요.","answer_guide":{"answer":"예: 값이 모두 짝수라서 한 칸을 2 cm로 하면 모든 값을 눈금 위에 정확히 찍을 수 있고, 가장 큰 값 32 cm까지 16칸이면 되어 판이 너무 길어지지 않는다. 한 칸을 10 cm로 하면 18, 26, 32처럼 눈금 사이에 오는 값이 생겨 정확히 찍기 어렵고 달라지는 모습도 덜 뚜렷하게 보인다.","scoring_points":["값이 모두 짝수(2의 배수)라고 썼는가","가장 큰 값까지 알맞은 칸 수로 나타낼 수 있다고 썼는가","10 cm로 하면 눈금 사이 값이 생기거나 변화가 덜 뚜렷하다고 썼는가"]},"explanation":["값이 모두 2의 배수예요.","한 칸 2 cm면 32 cm까지 16칸이에요.","한 칸 10 cm면 눈금 사이 값이 생기고 변화가 덜 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#1','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',1,'mc','auto','준우의 몸무게는 31 kg부터 42 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":1,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"준우의 몸무게는 31 kg부터 42 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 31 kg 사이","correct":true},{"t":"31 kg과 35 kg 사이","mis":"M4-2-u5-X09"},{"t":"35 kg과 42 kg 사이","mis":"M4-2-u5-X09"},{"t":"42 kg 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 31 kg이에요.","그래서 물결선은 0과 31 kg 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"어느 마을의 가구 수는 430가구부터 580가구까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 430가구 사이","correct":true},{"t":"430가구와 500가구 사이","mis":"M4-2-u5-X09"},{"t":"500가구와 580가구 사이","mis":"M4-2-u5-X09"},{"t":"580가구 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 430가구예요.","그래서 물결선은 0과 430가구 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"어느 도시의 인구수는 33만 명부터 51만 명까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 33만 명 사이","correct":true},{"t":"33만 명과 43만 명 사이","mis":"M4-2-u5-X09"},{"t":"43만 명과 51만 명 사이","mis":"M4-2-u5-X09"},{"t":"51만 명 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 33만 명이에요.","그래서 물결선은 0과 33만 명 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#2','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',1,'sa','auto','어느 도시의 인구수는 2017년에 37만 명, 2021년에 52만 명이었어요. 몇만 명 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u5-C7","difficulty":1,"kind":"sa","stem":"어느 도시의 인구수는 2017년에 37만 명, 2021년에 52만 명이었어요. 몇만 명 늘어났나요? 숫자로 쓰세요.","answer":["15"],"explanation":["두 때의 값으로 빼요.","52 − 37 = 15.","15만 명 늘어났어요."],"variant_rule":{"alt":[{"stem":"우유 생산량은 2017년에 190만 톤, 2021년에 209만 톤이었어요. 몇만 톤 늘어났나요? 숫자로 쓰세요.","answer":["19"],"explanation":["두 때의 값으로 빼요.","209 − 190 = 19.","19만 톤 늘어났어요."],"asset":null},{"stem":"1인당 하루 물 사용량은 2016년에 286 L, 2020년에 298 L였어요. 몇 L 늘어났나요? 숫자로 쓰세요.","answer":["12"],"explanation":["두 때의 값으로 빼요.","298 − 286 = 12.","12 L 늘어났어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#3','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',1,'mc','auto','물결선을 자료의 수 범위 안에 그으면 안 되는 까닭은 무엇인가요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":3,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"물결선을 자료의 수 범위 안에 그으면 안 되는 까닭은 무엇인가요?","options":[{"t":"꺾은선이 기울어진 정도가 사실과 다르게 나타나서","correct":true},{"t":"그래프가 짧아져서","mis":"M4-2-u5-X09"},{"t":"제목을 쓸 자리가 없어져서","mis":"M4-2-u5-X09"},{"t":"가로 눈금이 사라져서","mis":"M4-2-u5-X09"}],"explanation":["물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","자료의 수 범위 안에 넣으면 어떤 값은 물결선 아래로 사라지고 기울어진 정도가 사실과 달라져요.","그래서 가장 작은 값을 먼저 찾고 그보다 아래에 넣어요."],"variant_rule":{"alt":[{"stem":"물결선은 어느 값보다 아래에 놓아야 하나요?","options":[{"t":"가장 작은 값","correct":true},{"t":"가장 큰 값","mis":"M4-2-u5-X09"},{"t":"가운데 값","mis":"M4-2-u5-X09"},{"t":"처음 조사한 값","mis":"M4-2-u5-X09"}],"explanation":["물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","자료의 수 범위 안에 넣으면 어떤 값은 물결선 아래로 사라지고 기울어진 정도가 사실과 달라져요.","그래서 가장 작은 값을 먼저 찾고 그보다 아래에 넣어요."],"asset":null},{"stem":"물결선을 넣을 자리를 정하려면 표에서 무엇을 먼저 찾아야 하나요?","options":[{"t":"가장 작은 값","correct":true},{"t":"가장 큰 값","mis":"M4-2-u5-X09"},{"t":"모든 값의 합","mis":"M4-2-u5-X09"},{"t":"처음 조사한 값","mis":"M4-2-u5-X09"}],"explanation":["물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","자료의 수 범위 안에 넣으면 어떤 값은 물결선 아래로 사라지고 기울어진 정도가 사실과 달라져요.","그래서 가장 작은 값을 먼저 찾고 그보다 아래에 넣어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#4','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',1,'mc','auto','이지통계 같은 공학 도구를 쓰면 어떤 점이 편리한가요?',ARRAY['M4-2-u5-X16','M4-2-u5-X09','M4-2-u5-X07']::text[],true,'{"seq":4,"concept":"M4-2-u5-C7","difficulty":1,"kind":"mc","stem":"이지통계 같은 공학 도구를 쓰면 어떤 점이 편리한가요?","options":[{"t":"값이 큰 자료도 쉽고 빠르게 나타낼 수 있어요.","correct":true},{"t":"자료를 조사하지 않아도 돼요.","mis":"M4-2-u5-X16"},{"t":"물결선을 쓰지 않아도 돼요.","mis":"M4-2-u5-X09"},{"t":"제목을 쓰지 않아도 돼요.","mis":"M4-2-u5-X07"}],"explanation":["값이 아주 크면 손으로 그리기 어려워요.","공학 도구에 표를 입력하면 제목·축 이름·눈금·물결선을 정해 쉽고 빠르게 나타낼 수 있어요.","눈금의 간격을 작게 하면 변화가 더 잘 보여요."],"variant_rule":{"alt":[{"stem":"공학 도구에서 세로 눈금의 간격을 더 작게 바꾸면 그래프가 어떻게 달라지나요?","options":[{"t":"한 칸이 나타내는 크기가 작아져 변화를 더 잘 알 수 있어요.","correct":true},{"t":"자료의 값이 작아져요.","mis":"M4-2-u5-X05"},{"t":"가로 눈금이 사라져요.","mis":"M4-2-u5-X05"},{"t":"물결선이 저절로 생겨요.","mis":"M4-2-u5-X05"}],"explanation":["값이 아주 크면 손으로 그리기 어려워요.","공학 도구에 표를 입력하면 제목·축 이름·눈금·물결선을 정해 쉽고 빠르게 나타낼 수 있어요.","눈금의 간격을 작게 하면 변화가 더 잘 보여요."],"asset":null},{"stem":"값이 334856, 353803처럼 아주 큰 자료를 나타내기에 알맞은 방법은 어느 것인가요?","options":[{"t":"공학 도구에 표를 입력해 나타내요.","correct":true},{"t":"0부터 한 칸을 1로 손으로 그려요.","mis":"M4-2-u5-X08"},{"t":"값이 커서 그래프로 나타낼 수 없어요.","mis":"M4-2-u5-X07"},{"t":"막대그래프로만 나타내야 해요.","mis":"M4-2-u5-X18"}],"explanation":["값이 아주 크면 손으로 그리기 어려워요.","공학 도구에 표를 입력하면 제목·축 이름·눈금·물결선을 정해 쉽고 빠르게 나타낼 수 있어요.","눈금의 간격을 작게 하면 변화가 더 잘 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#5','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 3월의 준우의 몸무게는 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 3월의 준우의 몸무게는 몇 kg인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["물결선 바로 위 세로 눈금은 25이고, 한 칸은 1 kg이에요.","3월의 점은 25에서 13칸 위에 있어요.","25 + 13 = 38 — 38 kg이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[38,32,30,35,36]}],"step":1,"ymax":39,"ylab":"(kg)","xlab":"(월)","title":"월별 준우의 몸무게","y0":25,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 2021년의 1인당 하루 물 사용량은 몇 L인가요? 숫자로 쓰세요.","answer":["301"],"explanation":["물결선 바로 위 세로 눈금은 275이고, 한 칸은 1 L예요.","2021년의 점은 275에서 26칸 위에 있어요.","275 + 26 = 301 — 301 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[279,282,288,292,293,301]}],"step":1,"ymax":302,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":275,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 2021년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.","answer":["490"],"explanation":["물결선 바로 위 세로 눈금은 450이고, 한 칸은 10가구예요.","2021년의 점은 450에서 4칸 위에 있어요.","450 + 40 = 490 — 490가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[550,580,620,600,490]}],"step":10,"ymax":630,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":450,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#6','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 정원 해바라기의 키가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C7","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 정원 해바라기의 키가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이웃한 두 때의 변화: +3, +2, +4, +1.","오른쪽 위로 가장 가파르게 올라간 곳은 8월과 9월 사이예요.","가장 많이 늘어난 정도는 4 cm예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[181,184,186,190,191]}],"step":1,"ymax":192,"ylab":"(cm)","xlab":"(월)","title":"월별 정원 해바라기의 키","y0":180,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 수영장 물의 온도가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이웃한 두 때의 변화: +4, +1, +3, −2, −5.","오른쪽 위로 가장 가파르게 올라간 곳은 9시와 10시 사이예요.","가장 많이 늘어난 정도는 4 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[23,27,28,31,29,24]}],"step":1,"ymax":32,"ylab":"(°C)","xlab":"(시)","title":"시각별 수영장 물의 온도","y0":20,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 어느 마을의 가구 수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 가구인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이웃한 두 때의 변화: +30, +100, +10, +50.","오른쪽 위로 가장 가파르게 올라간 곳은 2018년과 2019년 사이예요.","가장 많이 늘어난 정도는 100가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[410,440,540,550,600]}],"step":10,"ymax":610,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#7','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',2,'ox','auto','물결선은 0과 가장 작은 값 사이에 넣어요.',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":7,"concept":"M4-2-u5-C6","difficulty":2,"kind":"ox","stem":"물결선은 0과 가장 작은 값 사이에 넣어요.","answer":"O","reason_options":[{"t":"필요 없는 아랫부분만 줄여야 해서","correct":true},{"t":"자료의 가운데에 넣어야 변화가 잘 보여서","mis":"M4-2-u5-X09"}],"mis":"M4-2-u5-X09","explanation":["물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","값은 그대로이고, 한 칸을 작게 잡을 수 있어 변화가 뚜렷해져요.","자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"물결선을 쓰면 자료의 값이 달라져요.","answer":"X","reason_options":[{"t":"물결선은 그래프의 필요 없는 부분만 줄인 것이라서","correct":true},{"t":"물결선 아래 값이 빠져서","mis":"M4-2-u5-X05"}],"explanation":["물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","값은 그대로이고, 한 칸을 작게 잡을 수 있어 변화가 뚜렷해져요.","자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"물결선은 가장 큰 값과 가장 작은 값 사이 아무 곳에나 넣어도 돼요.","answer":"X","reason_options":[{"t":"자료의 수 범위 안에 넣으면 기울어진 정도가 사실과 달라져서","correct":true},{"t":"어디에 넣든 그래프는 같아서","mis":"M4-2-u5-X09"}],"explanation":["물결선은 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","값은 그대로이고, 한 칸을 작게 잡을 수 있어 변화가 뚜렷해져요.","자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#8','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C7',2,'mc','auto','공학 도구로 꺾은선그래프를 그릴 때 먼저 해야 하는 일은 무엇인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X05']::text[],true,'{"seq":8,"concept":"M4-2-u5-C7","difficulty":2,"kind":"mc","stem":"공학 도구로 꺾은선그래프를 그릴 때 먼저 해야 하는 일은 무엇인가요?","options":[{"t":"자료를 표에 입력해요.","correct":true},{"t":"점을 손으로 찍어요.","mis":"M4-2-u5-X06"},{"t":"곡선을 그려요.","mis":"M4-2-u5-X06"},{"t":"물결선을 지워요.","mis":"M4-2-u5-X05"}],"explanation":["값이 아주 크면 손으로 그리기 어려워요.","공학 도구에 표를 입력하면 제목·축 이름·눈금·물결선을 정해 쉽고 빠르게 나타낼 수 있어요.","눈금의 간격을 작게 하면 변화가 더 잘 보여요."],"variant_rule":{"alt":[{"stem":"공학 도구에서 세로 눈금의 간격을 더 작게 바꾸면 그래프가 어떻게 달라지나요?","options":[{"t":"한 칸이 나타내는 크기가 작아져 변화를 더 잘 알 수 있어요.","correct":true},{"t":"자료의 값이 작아져요.","mis":"M4-2-u5-X05"},{"t":"가로 눈금이 사라져요.","mis":"M4-2-u5-X05"},{"t":"물결선이 저절로 생겨요.","mis":"M4-2-u5-X05"}],"explanation":["값이 아주 크면 손으로 그리기 어려워요.","공학 도구에 표를 입력하면 제목·축 이름·눈금·물결선을 정해 쉽고 빠르게 나타낼 수 있어요.","눈금의 간격을 작게 하면 변화가 더 잘 보여요."],"asset":null},{"stem":"값이 334856, 353803처럼 아주 큰 자료를 나타내기에 알맞은 방법은 어느 것인가요?","options":[{"t":"공학 도구에 표를 입력해 나타내요.","correct":true},{"t":"0부터 한 칸을 1로 손으로 그려요.","mis":"M4-2-u5-X08"},{"t":"값이 커서 그래프로 나타낼 수 없어요.","mis":"M4-2-u5-X07"},{"t":"막대그래프로만 나타내야 해요.","mis":"M4-2-u5-X18"}],"explanation":["값이 아주 크면 손으로 그리기 어려워요.","공학 도구에 표를 입력하면 제목·축 이름·눈금·물결선을 정해 쉽고 빠르게 나타낼 수 있어요.","눈금의 간격을 작게 하면 변화가 더 잘 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#9','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',2,'mc','auto','1인당 하루 물 사용량은 289 L, 283 L, 284 L, 281 L, 293 L예요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":9,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"1인당 하루 물 사용량은 289 L, 283 L, 284 L, 281 L, 293 L예요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?","options":[{"t":"280 L","correct":true},{"t":"284 L","mis":"M4-2-u5-X09"},{"t":"293 L","mis":"M4-2-u5-X09"},{"t":"283 L","mis":"M4-2-u5-X09"}],"explanation":["물결선 위 세로 눈금은 가장 작은 값보다 크면 안 돼요.","가장 작은 값은 281 L예요.","그래서 280 L부터 시작하면 모든 값을 나타낼 수 있어요."],"variant_rule":{"alt":[{"stem":"정원 해바라기의 키는 174 cm, 182 cm, 187 cm, 194 cm, 196 cm예요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?","options":[{"t":"173 cm","correct":true},{"t":"187 cm","mis":"M4-2-u5-X09"},{"t":"196 cm","mis":"M4-2-u5-X09"},{"t":"182 cm","mis":"M4-2-u5-X09"}],"explanation":["물결선 위 세로 눈금은 가장 작은 값보다 크면 안 돼요.","가장 작은 값은 174 cm예요.","그래서 173 cm부터 시작하면 모든 값을 나타낼 수 있어요."],"asset":null},{"stem":"수영장 물의 온도는 29 °C, 27 °C, 31 °C, 26 °C, 27 °C예요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?","options":[{"t":"25 °C","correct":true},{"t":"27 °C","mis":"M4-2-u5-X09"},{"t":"31 °C","mis":"M4-2-u5-X09"},{"t":"29 °C","mis":"M4-2-u5-X09"}],"explanation":["물결선 위 세로 눈금은 가장 작은 값보다 크면 안 돼요.","가장 작은 값은 26 °C예요.","그래서 25 °C부터 시작하면 모든 값을 나타낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_basic#10','math',4,2,'u5','L04','g4_2_math_u5_L04_basic','lesson_basic','M4-2-u5-C6',3,'sa','auto','물결선을 넣고 세로 눈금을 280 L부터 299 L까지, 한 칸을 1 L로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":3,"kind":"sa","stem":"물결선을 넣고 세로 눈금을 280 L부터 299 L까지, 한 칸을 1 L로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["세로 눈금은 280부터 299까지예요.","299 − 280 = 19만큼을 한 칸 1씩 나눠요.","19 ÷ 1 = 19칸이에요."],"variant_rule":{"alt":[{"stem":"물결선을 넣고 세로 눈금을 30 kg부터 40 kg까지, 한 칸을 1 kg로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금은 30부터 40까지예요.","40 − 30 = 10만큼을 한 칸 1씩 나눠요.","10 ÷ 1 = 10칸이에요."],"asset":null},{"stem":"물결선을 넣고 세로 눈금을 30 kg부터 43 kg까지, 한 칸을 1 kg로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["세로 눈금은 30부터 43까지예요.","43 − 30 = 13만큼을 한 칸 1씩 나눠요.","13 ÷ 1 = 13칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#1','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 2021년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 2021년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.","answer":["620"],"explanation":["물결선 바로 위 세로 눈금은 400이고, 한 칸은 10가구예요.","2021년의 점은 400에서 22칸 위에 있어요.","400 + 220 = 620 — 620가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[420,500,560,610,620,640]}],"step":10,"ymax":650,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 2018년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.","answer":["204"],"explanation":["물결선 바로 위 세로 눈금은 190이고, 한 칸은 1만 톤이에요.","2018년의 점은 190에서 14칸 위에 있어요.","190 + 14 = 204 — 204만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[203,204,200,195,192]}],"step":1,"ymax":205,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":190,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 2021년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.","answer":["203"],"explanation":["물결선 바로 위 세로 눈금은 185이고, 한 칸은 1만 톤이에요.","2021년의 점은 185에서 18칸 위에 있어요.","185 + 18 = 203 — 203만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[190,193,195,196,203,211]}],"step":1,"ymax":212,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":185,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#2','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',2,'mc','auto','어느 마을의 가구 수는 410가구, 420가구, 480가구, 520가구, 550가구예요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":2,"concept":"M4-2-u5-C6","difficulty":2,"kind":"mc","stem":"어느 마을의 가구 수는 410가구, 420가구, 480가구, 520가구, 550가구예요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?","options":[{"t":"400가구","correct":true},{"t":"480가구","mis":"M4-2-u5-X09"},{"t":"550가구","mis":"M4-2-u5-X09"},{"t":"420가구","mis":"M4-2-u5-X09"}],"explanation":["물결선 위 세로 눈금은 가장 작은 값보다 크면 안 돼요.","가장 작은 값은 410가구예요.","그래서 400가구부터 시작하면 모든 값을 나타낼 수 있어요."],"variant_rule":{"alt":[{"stem":"어느 도시의 인구수는 42만 명, 32만 명, 41만 명, 38만 명, 45만 명이에요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?","options":[{"t":"31만 명","correct":true},{"t":"41만 명","mis":"M4-2-u5-X09"},{"t":"45만 명","mis":"M4-2-u5-X09"},{"t":"38만 명","mis":"M4-2-u5-X09"}],"explanation":["물결선 위 세로 눈금은 가장 작은 값보다 크면 안 돼요.","가장 작은 값은 32만 명이에요.","그래서 31만 명부터 시작하면 모든 값을 나타낼 수 있어요."],"asset":null},{"stem":"우유 생산량은 194만 톤, 203만 톤, 204만 톤, 207만 톤, 209만 톤이에요. 물결선을 넣고 그 바로 위 세로 눈금을 어느 수부터 시작하면 좋을까요?","options":[{"t":"193만 톤","correct":true},{"t":"204만 톤","mis":"M4-2-u5-X09"},{"t":"209만 톤","mis":"M4-2-u5-X09"},{"t":"203만 톤","mis":"M4-2-u5-X09"}],"explanation":["물결선 위 세로 눈금은 가장 작은 값보다 크면 안 돼요.","가장 작은 값은 194만 톤이에요.","그래서 193만 톤부터 시작하면 모든 값을 나타낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#3','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',3,'sa','auto','물결선이 있는 꺾은선그래프예요. 어느 도시의 인구수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 어느 도시의 인구수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이웃한 두 때의 변화: −6, −5, +4, −8, +3.","오른쪽 위로 가장 가파르게 올라간 곳은 2019년과 2020년 사이예요.","가장 많이 늘어난 정도는 4만 명이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[49,43,38,42,34,37]}],"step":1,"ymax":50,"ylab":"(만 명)","xlab":"(년)","title":"연도별 어느 도시의 인구수","y0":30,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 우유 생산량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 톤인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이웃한 두 때의 변화: +5, +1, +2, +3.","오른쪽 위로 가장 가파르게 올라간 곳은 2017년과 2018년 사이예요.","가장 많이 늘어난 정도는 5만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[198,203,204,206,209]}],"step":1,"ymax":210,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":195,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 1인당 하루 물 사용량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 L인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["이웃한 두 때의 변화: +4, +2, +12, −1, −5.","오른쪽 위로 가장 가파르게 올라간 곳은 2018년과 2019년 사이예요.","가장 많이 늘어난 정도는 12 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[282,286,288,300,299,294]}],"step":1,"ymax":301,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":280,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#4','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',3,'error','auto','물결선에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X09','M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C6","difficulty":3,"kind":"error","stem":"물결선에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「물결선을 가장 작은 값과 가장 큰 값 사이에 넣었어.」","correct":true,"mis_target":"M4-2-u5-X09"},{"t":"준서 — 「물결선은 0과 가장 작은 값 사이에 넣어.」","mis":"M4-2-u5-X21"},{"t":"민서 — 「물결선을 쓰면 변화가 뚜렷하게 보여.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「가장 작은 값을 먼저 찾아.」","mis":"M4-2-u5-X21"}],"explanation":["물결선은 0과 가장 작은 값 사이에 넣어요.","지아의 말은 물결선의 쓰임과 맞지 않아요.","물결선은 값을 바꾸지 않고, 자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"물결선에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「물결선을 넣으면 값이 줄어들어.」","correct":true,"mis_target":"M4-2-u5-X05"},{"t":"민서 — 「물결선을 쓰면 변화가 뚜렷하게 보여.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「가장 작은 값을 먼저 찾아.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「물결선은 필요 없는 부분을 줄인 거야.」","mis":"M4-2-u5-X21"}],"explanation":["물결선은 0과 가장 작은 값 사이에 넣어요.","준서의 말은 물결선의 쓰임과 맞지 않아요.","물결선은 값을 바꾸지 않고, 자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"물결선에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「값이 31만부터 38만까지라서 물결선을 35만 근처에 넣었어.」","correct":true,"mis_target":"M4-2-u5-X09"},{"t":"도윤 — 「가장 작은 값을 먼저 찾아.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「물결선은 필요 없는 부분을 줄인 거야.」","mis":"M4-2-u5-X21"},{"t":"시우 — 「물결선은 0과 가장 작은 값 사이에 넣어.」","mis":"M4-2-u5-X21"}],"explanation":["물결선은 0과 가장 작은 값 사이에 넣어요.","민서의 말은 물결선의 쓰임과 맞지 않아요.","물결선은 값을 바꾸지 않고, 자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#5','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',3,'mc','auto','어느 도시의 다문화 가구 수는 2018년에 593824가구, 2022년에 647641가구였어요. 2018년부터 2022년까지 몇 가구 늘어났나요?',ARRAY['M4-2-u5-X14']::text[],true,'{"seq":5,"concept":"M4-2-u5-C7","difficulty":3,"kind":"mc","stem":"어느 도시의 다문화 가구 수는 2018년에 593824가구, 2022년에 647641가구였어요. 2018년부터 2022년까지 몇 가구 늘어났나요?","options":[{"t":"53817가구","correct":true},{"t":"154223가구","mis":"M4-2-u5-X14"},{"t":"54817가구","mis":"M4-2-u5-X14"},{"t":"52817가구","mis":"M4-2-u5-X14"}],"explanation":["값이 아주 큰 자료는 공학 도구로 그리면 편리해요.","늘어난 정도는 647641 − 593824로 구해요(받아내림에 주의).","647641 − 593824 = 53817 — 53817가구 늘어났어요."],"variant_rule":{"alt":[{"stem":"어느 지역의 자동차 수는 2018년에 375358대, 2022년에 386236대였어요. 2018년부터 2022년까지 몇 대 늘어났나요?","options":[{"t":"10878대","correct":true},{"t":"11122대","mis":"M4-2-u5-X14"},{"t":"11878대","mis":"M4-2-u5-X14"},{"t":"9878대","mis":"M4-2-u5-X14"}],"explanation":["값이 아주 큰 자료는 공학 도구로 그리면 편리해요.","늘어난 정도는 386236 − 375358로 구해요(받아내림에 주의).","386236 − 375358 = 10878 — 10878대 늘어났어요."],"asset":null},{"stem":"어느 도시의 도서관 이용자 수는 2018년에 400408명, 2022년에 467101명이었어요. 2018년부터 2022년까지 몇 명 늘어났나요?","options":[{"t":"66693명","correct":true},{"t":"67307명","mis":"M4-2-u5-X14"},{"t":"67693명","mis":"M4-2-u5-X14"},{"t":"65693명","mis":"M4-2-u5-X14"}],"explanation":["값이 아주 큰 자료는 공학 도구로 그리면 편리해요.","늘어난 정도는 467101 − 400408로 구해요(받아내림에 주의).","467101 − 400408 = 66693 — 66693명 늘어났어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#6','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',3,'mc','auto','수영장 물의 온도는 22 °C, 28 °C, 33 °C, 31 °C, 27 °C예요. 하준이는 물결선을 27 °C와 31 °C 사이에 넣었어요. 무엇이 잘못되었나요?',ARRAY['M4-2-u5-X20','M4-2-u5-X09','M4-2-u5-X02']::text[],true,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":3,"kind":"mc","stem":"수영장 물의 온도는 22 °C, 28 °C, 33 °C, 31 °C, 27 °C예요. 하준이는 물결선을 27 °C와 31 °C 사이에 넣었어요. 무엇이 잘못되었나요?","options":[{"t":"물결선이 자료의 수 범위 안에 들어가 기울어진 정도가 사실과 달라져요.","correct":true},{"t":"물결선은 어떤 경우에도 쓰면 안 돼요.","mis":"M4-2-u5-X20"},{"t":"물결선이 너무 아래에 있어요.","mis":"M4-2-u5-X09"},{"t":"세로 눈금 한 칸이 1이어야 해요.","mis":"M4-2-u5-X02"}],"explanation":["가장 작은 값은 22 °C예요.","27 °C와 31 °C 사이는 자료의 수 범위 안이에요.","물결선은 0과 22 °C 사이에 넣어야 해요."],"variant_rule":{"alt":[{"stem":"어느 마을의 가구 수는 440가구, 490가구, 530가구, 620가구, 640가구예요. 하준이는 물결선을 490가구와 620가구 사이에 넣었어요. 무엇이 잘못되었나요?","options":[{"t":"물결선이 자료의 수 범위 안에 들어가 기울어진 정도가 사실과 달라져요.","correct":true},{"t":"물결선은 어떤 경우에도 쓰면 안 돼요.","mis":"M4-2-u5-X20"},{"t":"물결선이 너무 아래에 있어요.","mis":"M4-2-u5-X09"},{"t":"세로 눈금 한 칸이 1이어야 해요.","mis":"M4-2-u5-X02"}],"explanation":["가장 작은 값은 440가구예요.","490가구와 620가구 사이는 자료의 수 범위 안이에요.","물결선은 0과 440가구 사이에 넣어야 해요."],"asset":null},{"stem":"어느 도시의 인구수는 38만 명, 41만 명, 43만 명, 47만 명, 46만 명이에요. 하준이는 물결선을 41만 명과 46만 명 사이에 넣었어요. 무엇이 잘못되었나요?","options":[{"t":"물결선이 자료의 수 범위 안에 들어가 기울어진 정도가 사실과 달라져요.","correct":true},{"t":"물결선은 어떤 경우에도 쓰면 안 돼요.","mis":"M4-2-u5-X20"},{"t":"물결선이 너무 아래에 있어요.","mis":"M4-2-u5-X09"},{"t":"세로 눈금 한 칸이 1이어야 해요.","mis":"M4-2-u5-X02"}],"explanation":["가장 작은 값은 38만 명이에요.","41만 명과 46만 명 사이는 자료의 수 범위 안이에요.","물결선은 0과 38만 명 사이에 넣어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#7','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',3,'sa','auto','물결선을 넣고 세로 눈금을 400가구부터 580가구까지, 한 칸을 10가구로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u5-C6","difficulty":3,"kind":"sa","stem":"물결선을 넣고 세로 눈금을 400가구부터 580가구까지, 한 칸을 10가구로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["세로 눈금은 400부터 580까지예요.","580 − 400 = 180만큼을 한 칸 10씩 나눠요.","180 ÷ 10 = 18칸이에요."],"variant_rule":{"alt":[{"stem":"물결선을 넣고 세로 눈금을 30만 명부터 49만 명까지, 한 칸을 1만 명로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["세로 눈금은 30부터 49까지예요.","49 − 30 = 19만큼을 한 칸 1씩 나눠요.","19 ÷ 1 = 19칸이에요."],"asset":null},{"stem":"물결선을 넣고 세로 눈금을 185만 톤부터 211만 톤까지, 한 칸을 1만 톤로 그리려고 해요. 물결선 위 세로 눈금은 몇 칸인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["세로 눈금은 185부터 211까지예요.","211 − 185 = 26만큼을 한 칸 1씩 나눠요.","26 ÷ 1 = 26칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#8','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',4,'mc','auto','어느 공항의 한 달 이용객 수는 2018년에 210216명, 2022년에 240004명이었어요. 2018년부터 2022년까지 몇 명 늘어났나요?',ARRAY['M4-2-u5-X14']::text[],true,'{"seq":8,"concept":"M4-2-u5-C7","difficulty":4,"kind":"mc","stem":"어느 공항의 한 달 이용객 수는 2018년에 210216명, 2022년에 240004명이었어요. 2018년부터 2022년까지 몇 명 늘어났나요?","options":[{"t":"29788명","correct":true},{"t":"30212명","mis":"M4-2-u5-X14"},{"t":"30788명","mis":"M4-2-u5-X14"},{"t":"28788명","mis":"M4-2-u5-X14"}],"explanation":["값이 아주 큰 자료는 공학 도구로 그리면 편리해요.","늘어난 정도는 240004 − 210216으로 구해요(받아내림에 주의).","240004 − 210216 = 29788 — 29788명 늘어났어요."],"variant_rule":{"alt":[{"stem":"어느 시의 자전거 대여 횟수는 2018년에 309834회, 2022년에 386381회였어요. 2018년부터 2022년까지 몇 회 늘어났나요?","options":[{"t":"76547회","correct":true},{"t":"83553회","mis":"M4-2-u5-X14"},{"t":"77547회","mis":"M4-2-u5-X14"},{"t":"75547회","mis":"M4-2-u5-X14"}],"explanation":["값이 아주 큰 자료는 공학 도구로 그리면 편리해요.","늘어난 정도는 386381 − 309834로 구해요(받아내림에 주의).","386381 − 309834 = 76547 — 76547회 늘어났어요."],"asset":null},{"stem":"어느 군의 관광객 수는 2018년에 577918명, 2022년에 649405명이었어요. 2018년부터 2022년까지 몇 명 늘어났나요?","options":[{"t":"71487명","correct":true},{"t":"132513명","mis":"M4-2-u5-X14"},{"t":"72487명","mis":"M4-2-u5-X14"},{"t":"70487명","mis":"M4-2-u5-X14"}],"explanation":["값이 아주 큰 자료는 공학 도구로 그리면 편리해요.","늘어난 정도는 649405 − 577918로 구해요(받아내림에 주의).","649405 − 577918 = 71487 — 71487명 늘어났어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#9','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C7',4,'sa','auto','물결선이 있는 꺾은선그래프에서 세로 눈금 한 칸은 1 cm예요. 10월의 점은 6월의 점보다 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C7","difficulty":4,"kind":"sa","stem":"물결선이 있는 꺾은선그래프에서 세로 눈금 한 칸은 1 cm예요. 10월의 점은 6월의 점보다 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["23"],"explanation":["6월 175 cm, 10월 198 cm예요.","차는 198 − 175 = 23.","한 칸이 1이니 23 ÷ 1 = 23칸 위예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[175,181,182,186,198]}],"step":1,"ymax":199,"ylab":"(cm)","xlab":"(월)","title":"월별 정원 해바라기의 키","y0":170,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프에서 세로 눈금 한 칸은 1 kg이에요. 7월의 점은 3월의 점보다 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["10"],"explanation":["3월 30 kg, 7월 40 kg이에요.","차는 40 − 30 = 10.","한 칸이 1이니 10 ÷ 1 = 10칸 위예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[30,31,34,38,40]}],"step":1,"ymax":41,"ylab":"(kg)","xlab":"(월)","title":"월별 준우의 몸무게","y0":25,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프에서 세로 눈금 한 칸은 10가구예요. 2021년의 점은 2017년의 점보다 세로 눈금 몇 칸 위에 있나요? 숫자로 쓰세요.","answer":["17"],"explanation":["2017년 430가구, 2021년 600가구예요.","차는 600 − 430 = 170.","한 칸이 10이니 170 ÷ 10 = 17칸 위예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[430,500,540,590,600]}],"step":10,"ymax":610,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L04_challenge#10','math',4,2,'u5','L04','g4_2_math_u5_L04_challenge','lesson_challenge','M4-2-u5-C6',4,'essay','teacher','어느 도시의 인구수는 31만, 33만, 34만, 36만, 38만 명이에요. 이 자료를 꺾은선그래프로 나타낼 때 물결선을 어디에 넣어야 하는지 쓰고, 물결선을 34만 명 근처에 넣으면 안 되는 까닭도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C6","difficulty":4,"kind":"essay","stem":"어느 도시의 인구수는 31만, 33만, 34만, 36만, 38만 명이에요. 이 자료를 꺾은선그래프로 나타낼 때 물결선을 어디에 넣어야 하는지 쓰고, 물결선을 34만 명 근처에 넣으면 안 되는 까닭도 써 보세요.","answer_guide":{"answer":"예: 가장 작은 값이 31만 명이므로 물결선은 0과 31만 명 사이에 넣는다. 34만 명 근처는 자료의 수 범위 안이라서 물결선을 넣으면 31만, 33만 같은 값이 물결선 아래로 사라지고 꺾은선이 기울어진 정도가 사실과 다르게 보여 잘못 판단하게 된다.","scoring_points":["가장 작은 값 31만 명을 찾았는가","0과 31만 명 사이에 넣는다고 썼는가","범위 안에 넣으면 값이 사라지거나 기울어진 정도가 달라진다고 썼는가"]},"explanation":["가장 작은 값을 먼저 찾아요 — 31만 명.","물결선은 0과 31만 명 사이에 넣어요.","범위 안에 넣으면 기울어진 정도가 사실과 달라져요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[31,33,34,36,38]}],"step":1,"ymax":39,"ylab":"(만 명)","xlab":"(년)","title":"연도별 어느 도시의 인구수","y0":30,"wave":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#1','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'sa','auto','12시의 교실 온도는 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"12시의 교실 온도는 몇 °C인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["세로 눈금 한 칸은 1 °C예요.","12시의 점을 따라 세로 눈금을 읽어요.","12시의 교실 온도는 23 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[15,17,16,23,18]}],"step":1,"ymax":24,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"2017년의 폭염 일수는 며칠인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["세로 눈금 한 칸은 1일이에요.","2017년의 점을 따라 세로 눈금을 읽어요.","2017년의 폭염 일수는 4일이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[4,11,13,14,19,23]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}},{"stem":"2018년의 태풍 발생 횟수는 몇 회인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세로 눈금 한 칸은 1회예요.","2018년의 점을 따라 세로 눈금을 읽어요.","2018년의 태풍 발생 횟수는 10회예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[2,8,10,9,12]}],"step":1,"ymax":13,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#2','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'mc','auto','태풍 발생 횟수는 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":2,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"태풍 발생 횟수는 어떻게 변하고 있나요?","options":[{"t":"2018년까지 늘어났고 2018년부터는 줄어들었어요.","correct":true},{"t":"2016년부터 2020년까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"2016년부터 2020년까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"2018년까지 줄어들었고 2018년부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 2018년까지 올라가다가 그 뒤로 내려가요.","2018년까지 늘어났고 2018년부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[1,6,8,5,4]}],"step":1,"ymax":9,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"},"variant_rule":{"alt":[{"stem":"자외선 지수 매우 높음 일수는 어떻게 변하고 있나요?","options":[{"t":"4월부터 9월까지 계속 늘어났어요.","correct":true},{"t":"4월부터 9월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"7월까지 늘어났고 7월부터는 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"7월까지 줄어들었고 7월부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 오른쪽 위로만 올라가요.","4월부터 9월까지 계속 늘어났어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[9,13,16,18,19,24]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"줄넘기 기록은 어떻게 변하고 있나요?","options":[{"t":"6월까지 줄어들었고 6월부터는 늘어났어요.","correct":true},{"t":"3월부터 7월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"3월부터 7월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"6월까지 늘어났고 6월부터는 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 6월까지 내려가다가 그 뒤로 올라가요.","6월까지 줄어들었고 6월부터는 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[95,70,30,20,70]}],"step":5,"ymax":100,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#3','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'ox','auto','꺾은선이 오른쪽 위로 올라가면 값이 늘어난 것이에요.',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":3,"concept":"M4-2-u5-C8","difficulty":1,"kind":"ox","stem":"꺾은선이 오른쪽 위로 올라가면 값이 늘어난 것이에요.","answer":"O","reason_options":[{"t":"오른쪽으로 갈수록 점이 높아져서","correct":true},{"t":"오른쪽 위로 올라가면 줄어든 것이라서","mis":"M4-2-u5-X10"}],"mis":"M4-2-u5-X10","explanation":["오른쪽 위 = 늘어남, 오른쪽 아래 = 줄어듦, 평평 = 변화 없음.","선분이 가파를수록 많이 변한 것이에요.","가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾아요."],"variant_rule":{"alt":[{"stem":"꺾은선이 오른쪽 아래로 내려가면 값이 늘어난 것이에요.","answer":"X","reason_options":[{"t":"오른쪽 아래로 내려가면 줄어든 것이라서","correct":true},{"t":"아래로 내려가면 늘어난 것이라서","mis":"M4-2-u5-X10"}],"explanation":["오른쪽 위 = 늘어남, 오른쪽 아래 = 줄어듦, 평평 = 변화 없음.","선분이 가파를수록 많이 변한 것이에요.","가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾아요."],"asset":null},{"stem":"선분이 오른쪽으로 평평하게 가면 값이 변하지 않은 것이에요.","answer":"O","reason_options":[{"t":"이웃한 두 점의 높이가 같아서","correct":true},{"t":"평평해도 값이 늘어난 것이라서","mis":"M4-2-u5-X13"}],"explanation":["오른쪽 위 = 늘어남, 오른쪽 아래 = 줄어듦, 평평 = 변화 없음.","선분이 가파를수록 많이 변한 것이에요.","가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#4','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',1,'sa','auto','교실 온도는 10시부터 12시까지 몇 °C 줄어들었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u5-C8","difficulty":1,"kind":"sa","stem":"교실 온도는 10시부터 12시까지 몇 °C 줄어들었나요? 숫자로 쓰세요.","answer":["1"],"explanation":["10시 24 °C, 12시 23 °C예요.","두 때의 값만 써서 큰 값에서 작은 값을 빼요.","24 − 23 = 1 — 1 °C 줄어들었어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[18,24,20,23,21]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"도서관에서 빌려 간 책 수는 4월부터 8월까지 몇 권 늘어났나요? 숫자로 쓰세요.","answer":["30"],"explanation":["4월 250권, 8월 280권이에요.","두 때의 값만 써서 큰 값에서 작은 값을 빼요.","280 − 250 = 30 — 30권 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[130,250,190,120,230,280]}],"step":10,"ymax":290,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"태풍 발생 횟수는 2016년부터 2020년까지 몇 회 줄어들었나요? 숫자로 쓰세요.","answer":["5"],"explanation":["2016년 8회, 2020년 3회예요.","두 때의 값만 써서 큰 값에서 작은 값을 빼요.","8 − 3 = 5 — 5회 줄어들었어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[8,6,10,9,3]}],"step":1,"ymax":11,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#5','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',2,'mc','auto','전년도와 비교하여 미세 먼지 나쁨 일수가 가장 많이 늘어난 때는 언제인가요?',ARRAY['M4-2-u5-X12','M4-2-u5-X21']::text[],true,'{"seq":5,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"전년도와 비교하여 미세 먼지 나쁨 일수가 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"2017년","mis":"M4-2-u5-X12"},{"t":"2018년","mis":"M4-2-u5-X21"},{"t":"2019년","mis":"M4-2-u5-X21"}],"explanation":["이웃한 두 때의 변화: +1, −10, −3, +11.","오른쪽 위로 가장 가파르게 올라간 선분은 2019년과 2020년 사이예요.","가장 많이 늘어난 때는 2020년 — 점이 가장 높은 2017년과는 달라요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[25,26,16,13,24]}],"step":1,"ymax":27,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"전년도와 비교하여 태풍 발생 횟수가 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2019년","correct":true},{"t":"2016년","mis":"M4-2-u5-X12"},{"t":"2017년","mis":"M4-2-u5-X11"},{"t":"2018년","mis":"M4-2-u5-X21"}],"explanation":["이웃한 두 때의 변화: −6, −1, +5, −4.","오른쪽 위로 가장 가파르게 올라간 선분은 2018년과 2019년 사이예요.","가장 많이 늘어난 때는 2019년 — 점이 가장 높은 2016년과는 달라요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[12,6,5,10,6]}],"step":1,"ymax":13,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}},{"stem":"이번에는 다른 그림이에요. 전년도와 비교하여 미세 먼지 나쁨 일수가 가장 많이 늘어난 때는 언제인가요?","options":[{"t":"2019년","correct":true},{"t":"2020년","mis":"M4-2-u5-X12"},{"t":"2017년","mis":"M4-2-u5-X21"},{"t":"2018년","mis":"M4-2-u5-X21"}],"explanation":["이웃한 두 때의 변화: +2, −7, +10, +6.","오른쪽 위로 가장 가파르게 올라간 선분은 2018년과 2019년 사이예요.","가장 많이 늘어난 때는 2019년 — 점이 가장 높은 2020년과는 달라요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[15,17,10,20,26]}],"step":1,"ymax":27,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#6','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',2,'mc','auto','줄넘기 기록이 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],true,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"줄넘기 기록이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"3월부터 4월까지","correct":true},{"t":"4월부터 5월까지","mis":"M4-2-u5-X13"},{"t":"5월부터 6월까지","mis":"M4-2-u5-X13"},{"t":"6월부터 7월까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 3월과 4월 사이에 있어요.","3월과 4월 모두 140회예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[140,140,135,100,145]}],"step":5,"ymax":150,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"미세 먼지 나쁨 일수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2018년부터 2019년까지","correct":true},{"t":"2016년부터 2017년까지","mis":"M4-2-u5-X13"},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2019년부터 2020년까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 2018년과 2019년 사이에 있어요.","2018년과 2019년 모두 11일이에요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[8,17,11,11,18,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}},{"stem":"폭염 일수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2017년부터 2018년까지","correct":true},{"t":"2018년부터 2019년까지","mis":"M4-2-u5-X13"},{"t":"2019년부터 2020년까지","mis":"M4-2-u5-X13"},{"t":"2020년부터 2021년까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 2017년과 2018년 사이에 있어요.","2017년과 2018년 모두 11일이에요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[11,11,5,14,9,8]}],"step":1,"ymax":15,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}}]}}'::jsonb) ON CO