INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#7','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',2,'mc','auto','줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],true,'{"seq":7,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"3월과 4월 사이","correct":true},{"t":"4월과 5월 사이","mis":"M4-2-u5-X11"},{"t":"5월과 6월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −50, +20, +15, −10.","가장 많이 늘어난 것은 20회이지만, 3월과 4월에 50회 줄어들었어요.","그래서 가장 많이 변한 때는 3월과 4월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[145,95,115,130,120]}],"step":5,"ymax":150,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"3월과 4월 사이","correct":true},{"t":"5월과 6월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −65, −10, +25, −35, −15.","가장 많이 늘어난 것은 25회이지만, 3월과 4월에 65회 줄어들었어요.","그래서 가장 많이 변한 때는 3월과 4월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[140,75,65,90,55,40]}],"step":5,"ymax":145,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"4월과 5월 사이","correct":true},{"t":"3월과 4월 사이","mis":"M4-2-u5-X11"},{"t":"5월과 6월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +30, −35, +20, −5.","가장 많이 늘어난 것은 30회이지만, 4월과 5월에 35회 줄어들었어요.","그래서 가장 많이 변한 때는 4월과 5월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[115,145,110,130,125]}],"step":5,"ymax":15