INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#8','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',2,'sa','auto','교실 온도가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C9","difficulty":2,"kind":"sa","stem":"교실 온도가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −7, +4, −2, +1.","가장 가파른 선분은 9시와 10시 사이로, 7 °C 줄어들었어요.","가장 많이 변한 정도는 7 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[24,17,21,19,20]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"도서관에서 빌려 간 책 수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 권인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +20, +80, −40, −70, +30.","가장 가파른 선분은 4월과 5월 사이로, 80권 늘어났어요.","가장 많이 변한 정도는 80권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[50,70,150,110,40,70]}],"step":10,"ymax":160,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"태풍 발생 횟수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 회인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −5, +3, +1, +2.","가장 가파른 선분은 2016년과 2017년 사이로, 5회 줄어들었어요.","가장 많이 변한 정도는 5회예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[10,5,8,9,11]}],"step":1,"ymax":12,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#9','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C8',2,'mc','auto','자외선 지수 매우 높음 일수가 처음으로 줄어든 때는 언제인가요? (전월과 비교해요.)',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":9,"concept":"M4-2-u5-C8","difficulty":2,"kind":"mc","stem":"자외선 지수 매우 높음 일수가 처음으로 줄어든 때는 언제인가요? (전월과 비교해요.)","options":[{"t":"9월","correct":true},{"t":"5월","mis":"M4-2-u5-X21"},{"t":"6월","mis":"M4-2-u5-X21"},{"t":"7월","mis":"M4-2-u5-X21"}],"explanation":["왼쪽부터 선분을 차례로 봐요: +3, +5, +6, +2, −10.","처음으로 오른쪽 아래로 내려간 선분은 8월과 9월 사이예요.","처음으로 줄어든 때는 9월이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[3,6,11,17,19,9]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"운동장의 기온이 처음으로 줄어든 때는 언제인가요? (한 시간 전과 비교해요.)","options":[{"t":"11시","correct":true},{"t":"13시","mis":"M4-2-u5-X11"},{"t":"10시","mis":"M4-2-u5-X21"},{"t":"12시","mis":"M4-2-u5-X21"}],"explanation":["왼쪽부터 선분을 차례로 봐요: +4, −6, +12, −10, +2.","처음으로 오른쪽 아래로 내려간 선분은 10시와 11시 사이예요.","처음으로 줄어든 때는 11시예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[10,14,8,20,10,12]}],"step":2,"ymax":22,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}},{"stem":"운동장의 기온이 처음으로 줄어든 때는 언제인가요? (한 시간 전과 비교해요.)","options":[{"t":"13시","correct":true},{"t":"14시","mis":"M4-2-u5-X11"},{"t":"10시","mis":"M4-2-u5-X21"},{"t":"11시","mis":"M4-2-u5-X21"}],"explanation":["왼쪽부터 선분을 차례로 봐요: +2, +10, +6, −12, −14.","처음으로 오른쪽 아래로 내려간 선분은 12시와 13시 사이예요.","처음으로 줄어든 때는 13시예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[16,18,28,34,22,8]}],"step":2,"ymax":36,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_basic#10','math',4,2,'u5','L05','g4_2_math_u5_L05_basic','lesson_basic','M4-2-u5-C9',3,'mc','auto','「월별 해바라기의 키」를 나타낸 꺾은선그래프예요. 앞으로 어떻게 될지 알맞게 짐작한 것은 어느 것인가요?',ARRAY['M4-2-u5-X10','M4-2-u5-X13','M4-2-u5-X04']::text[],true,'{"seq":10,"concept":"M4-2-u5-C9","difficulty":3,"kind":"mc","stem":"「월별 해바라기의 키」를 나타낸 꺾은선그래프예요. 앞으로 어떻게 될지 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"앞으로도 늘어날 것이라고 짐작할 수 있어요.","correct":true},{"t":"앞으로는 줄어들 것이라고 짐작할 수 있어요.","mis":"M4-2-u5-X10"},{"t":"앞으로는 변하지 않을 것이라고 짐작할 수 있어요.","mis":"M4-2-u5-X13"},{"t":"그래프로는 아무것도 짐작할 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["그래프 전체의 흐름을 봐요.","꺾은선이 처음부터 끝까지 계속 오른쪽 위로 올라가요.","앞으로도 늘어날 것이라고 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[45,55,80,95,100,140]}],"step":5,"ymax":145,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키"},"variant_rule":{"alt":[{"stem":"「월별 도서관에서 빌려 간 책 수」를 나타낸 꺾은선그래프예요. 앞으로 어떻게 될지 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"앞으로는 줄어들 것이라고 짐작할 수 있어요.","correct":true},{"t":"앞으로도 늘어날 것이라고 짐작할 수 있어요.","mis":"M4-2-u5-X10"},{"t":"앞으로는 변하지 않을 것이라고 짐작할 수 있어요.","mis":"M4-2-u5-X13"},{"t":"그래프로는 아무것도 짐작할 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["그래프 전체의 흐름을 봐요.","꺾은선이 처음부터 끝까지 계속 오른쪽 아래로 내려가요.","앞으로는 줄어들 것이라고 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[290,240,140,130,90,60]}],"step":10,"ymax":300,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"「연도별 폭염 일수」를 나타낸 꺾은선그래프예요. 앞으로 어떻게 될지 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"앞으로도 늘어날 것이라고 짐작할 수 있어요.","correct":true},{"t":"앞으로는 줄어들 것이라고 짐작할 수 있어요.","mis":"M4-2-u5-X10"},{"t":"앞으로는 변하지 않을 것이라고 짐작할 수 있어요.","mis":"M4-2-u5-X13"},{"t":"그래프로는 아무것도 짐작할 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["그래프 전체의 흐름을 봐요.","꺾은선이 처음부터 끝까지 계속 오른쪽 위로 올라가요.","앞으로도 