INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#2','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',2,'sa','auto','12시의 운동장의 기온은 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u5-C8","difficulty":2,"kind":"sa","stem":"12시의 운동장의 기온은 몇 °C인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["세로 눈금 한 칸은 2 °C예요.","12시의 점은 0에서 12칸 위에 있어요.","12 × 2 = 24 — 12시의 운동장의 기온은 24 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[8,16,18,24,28,16]}],"step":2,"ymax":30,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"4월의 줄넘기 기록은 몇 회인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["세로 눈금 한 칸은 5회예요.","4월의 점은 0에서 18칸 위에 있어요.","18 × 5 = 90 — 4월의 줄넘기 기록은 90회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[75,90,40,70,25]}],"step":5,"ymax":95,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"10월의 선인장 줄기의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["세로 눈금 한 칸은 2 cm예요.","10월의 점은 0에서 18칸 위에 있어요.","18 × 2 = 36 — 10월의 선인장 줄기의 길이는 36 cm예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월","11월"],"series":[{"vals":[8,24,30,34,36,46]}],"step":2,"ymax":48,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#3','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',3,'sa','auto','자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 줄어든 정도는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 줄어든 정도는 며칠인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["오른쪽 아래로 내려간 선분만 견주어요: +2, −8, −3, +9.","가장 가파르게 내려간 선분은 5월과 6월 사이예요.","24 − 16 = 8 — 가장 많이 줄어든 정도는 8일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[22,24,16,13,22]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"교실 온도가 이웃한 두 때 사이에서 가장 많이 줄어든 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["오른쪽 아래로 내려간 선분만 견주어요: −2, −7, +5, −3, +1.","가장 가파르게 내려간 선분은 10시와 11시 사이예요.","22 − 15 = 7 — 가장 많이 줄어든 정도는 7 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[24,22,15,20,17,18]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}},{"stem":"도서관에서 빌려 간 책 수가 이웃한 두 때 사이에서 가장 많이 줄어든 정도는 몇 권인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["오른쪽 아래로 내려간 선분만 견주어요: −40, −10, +120, −60.","가장 가파르게 내려간 선분은 6월과 7월 사이예요.","260 − 200 = 60 — 가장 많이 줄어든 정도는 60권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[190,150,140,260,200]}],"step":10,"ymax":270,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#4','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',3,'error','auto','꺾은선그래프를 해석하는 방법을 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C9","difficulty":3,"kind":"error","stem":"꺾은선그래프를 해석하는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「가장 많이 변한 때를 찾을 때는 늘어난 곳만 보면 돼.」","correct":true,"mis_target":"M4-2-u5-X11"},{"t":"은우 — 「선분이 가파를수록 많이 변한 거야.」","mis":"M4-2-u5-X21"},{"t":"하랑 — 「평평한 곳은 변하지 않은 때야.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「줄어든 것도 변한 거야.」","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 위 = 늘어남, 아래 = 줄어듦, 평평 = 변화 없음.","시우의 말은 해석하는 방법과 맞지 않아요.","가장 많이 변한 때는 높이가 아니라 기울기로, 줄어든 것까지 견주어 찾아요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프를 해석하는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「점이 가장 높은 때가 가장 많이 늘어난 때야.」","correct":true,"mis_target":"M4-2-u5-X12"},{"t":"하랑 — 「평평한 곳은 변하지 않은 때야.」","mis":"M4-2-u5-X21"},{"t":"지아 — 「줄어든 것도 변한 거야.」","mis":"M4-2-u5-X21"},{"t":"준서 — 「먼저 세로 눈금 한 칸을 확인해.」","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 위 = 늘어남, 아래 = 줄어듦, 평평 = 변화 없음.","은우의 말은 해석하는 방법과 맞지 않아요.","가장 많이 변한 때는 높이가 아니라 기울기로, 줄어든 것까지 견주어 찾아요."],"asset":null},{"stem":"꺾은선그래프를 해석하는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「꺾은선이 오른쪽 아래로 내려가면 늘어난 거야.」","correct":true,"mis_target":"M4-2-u5-X10"},{"t":"지아 — 「줄어든 것도 변한 거야.」","mis":"M4-2-u5-X21"},{"t":"준서 — 「먼저 세로 눈금 한 칸을 확인해.」","mis":"M4-2-u5-X21"},{"t":"민서 — 「선분이 가파를수록 많이 변한 거야.」","mis":"M4-2-u5-X21"}],"explanation":["오른쪽 위 = 늘어남, 아래 = 줄어듦, 평평 = 변화 없음.","하랑의 말은 해석하는 방법과 맞지 않아요.","가장 많이 변한 때는 높이가 아니라 기울기로, 줄어든 것까지 견주어 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#5','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',3,'mc','auto','줄넘기 기록은 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":5,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"줄넘기 기록은 어떻게 변하고 있나요?","options":[{"t":"3월부터 8월까지 계속 줄어들었어요.","correct":true},{"t":"3월부터 8월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"6월까지 늘어났고 6월부터는 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"6월까지 줄어들었고 6월부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 오른쪽 아래로만 내려가요.","3월부터 8월까지 계속 줄어들었어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[135,120,110,75,25,20]}],"step":5,"ymax":140,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"폭염 일수는 어떻게 변하고 있나요?","options":[{"t":"2019년까지 늘어났고 2019년부터는 줄어들었어요.","correct":true},{"t":"2017년부터 2021년까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"2017년부터 2021년까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"2019년까지 줄어들었고 2019년부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 2019년까지 올라가다가 그 뒤로 내려가요.","2019년까지 늘어났고 2019년부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[4,8,15,12,7]}],"step":1,"ymax":16,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}},{"stem":"자외선 지수 매우 높음 일수는 어떻게 변하고 있나요?","options":[{"t":"8월까지 줄어들었고 8월부터는 늘어났어요.","correct":true},{"t":"4월부터 9월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"4월부터 9월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"8월까지 늘어났고 8월부터는 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 8월까지 내려가다가 그 뒤로 올라가요.","8월까지 줄어들었고 8월부터는 늘어났어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[18,11,8,3,2,10]}],"step":1,"ymax":19,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#6','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',3,'sa','auto','자외선 지수 매우 높음 일수가 가장 많은 때와 가장 적은 때의 차는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C8","difficulty":3,"kind":"sa","stem":"자외선 지수 매우 높음 일수가 가장 많은 때와 가장 적은 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["가장 높은 점은 7월의 11일이에요.","가장 낮은 점은 8월의 2일이에요.","11 − 2 = 9일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[9,8,5,11,2]}],"step":1,"ymax":12,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"교실 온도가 가장 높은 때와 가장 낮은 때의 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["가장 높은 점은 11시의 28 °C예요.","가장 낮은 점은 14시의 15 °C예요.","28 − 15 = 13 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[24,22,28,21,20,15]}],"step":1,"ymax":29,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}},{"stem":"도서관에서 빌려 간 책 수가 가장 많은 때와 가장 적은 때의 차는 몇 권인가요? 숫자로 쓰세요.","answer":["230"],"explanation":["가장 높은 점은 3월의 290권이에요.","가장 낮은 점은 6월의 60권이에요.","290 − 60 = 230권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월","9월"],"series":[{"vals":[290,180,90,60,180,80,160]}],"step":10,"ymax":300,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#7','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',3,'ox','auto','선분이 가파를수록 값이 조금 변한 것이에요.',ARRAY['M4-2-u5-X12']::text[],true,'{"seq":7,"concept":"M4-2-u5-C9","difficulty":3,"kind":"ox","stem":"선분이 가파를수록 값이 조금 변한 것이에요.","answer":"X","reason_options":[{"t":"가파를수록 많이 변한 것이라서","correct":true},{"t":"가파르면 조금 변한 것이라서","mis":"M4-2-u5-X12"}],"mis":"M4-2-u5-X12","explanation":["오른쪽 위 = 늘어남, 오른쪽 아래 = 줄어듦, 평평 = 변화 없음.","선분이 가파를수록 많이 변한 것이에요.","가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾아요."],"variant_rule":{"alt":[{"stem":"점이 가장 높은 때가 언제나 가장 많이 늘어난 때예요.","answer":"X","reason_options":[{"t":"가장 많이 늘어난 때는 점의 높이가 아니라 선분이 가장 가파른 곳이라서","correct":true},{"t":"가장 높은 점이 가장 많이 늘어난 곳이라서","mis":"M4-2-u5-X12"}],"explanation":["오른쪽 위 = 늘어남, 오른쪽 아래 = 줄어듦, 평평 = 변화 없음.","선분이 가파를수록 많이 변한 것이에요.","가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾아요."],"asset":null},{"stem":"줄어든 것도 변한 것이에요.","answer":"O","reason_options":[{"t":"늘어난 것과 줄어든 것 모두 값이 달라진 것이라서","correct":true},{"t":"늘어난 것만 변한 것이라서","mis":"M4-2-u5-X11"}],"explanation":["오른쪽 위 = 늘어남, 오른쪽 아래 = 줄어듦, 평평 = 변화 없음.","선분이 가파를수록 많이 변한 것이에요.","가장 많이 변한 때는 늘어난 것과 줄어든 것을 모두 견주어 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#8','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C8',4,'sa','auto','전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +4, +11, −5, −6, +7, −10.","늘어난 때: 5월, 6월, 9월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[7,11,22,17,11,18,8]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: −6, +4, +10, +1, −3, −11.","늘어난 때: 6월, 7월, 8월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[13,7,11,21,22,19,8]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +11, −5, +4, −7, +3, +2.","늘어난 때: 5월, 7월, 9월, 10월.","모두 4번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[3,14,9,13,6,9,11]}],"step":1,"ymax":15,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#9','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',4,'sa','auto','운동장의 기온이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 가장 많이 줄어든 정도보다 몇 °C 더 큰가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C9","difficulty":4,"kind":"sa","stem":"운동장의 기온이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 가장 많이 줄어든 정도보다 몇 °C 더 큰가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변화: +12, −10, +8, −6, +2.","가장 많이 늘어난 정도는 12 °C, 가장 많이 줄어든 정도는 10 °C예요.","12 − 10 = 2 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[12,24,14,22,16,18]}],"step":2,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 운동장의 기온이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 가장 많이 줄어든 정도보다 몇 °C 더 큰가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변화: −12, −8, +2, +14, +6.","가장 많이 늘어난 정도는 14 °C, 가장 많이 줄어든 정도는 12 °C예요.","14 − 12 = 2 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[32,20,12,14,28,34]}],"step":2,"ymax":36,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}},{"stem":"이번에는 다른 그림이에요. 운동장의 기온이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 가장 많이 줄어든 정도보다 몇 °C 더 큰가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변화: −12, +8, +14, −6, +2.","가장 많이 늘어난 정도는 14 °C, 가장 많이 줄어든 정도는 12 °C예요.","14 − 12 = 2 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[24,12,20,34,28,30]}],"step":2,"ymax":36,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L05_challenge#10','math',4,2,'u5','L05','g4_2_math_u5_L05_challenge','lesson_challenge','M4-2-u5-C9',4,'essay','teacher','우유 생산량은 해마다 204, 203, 209, 201, 198만 톤으로 달라졌어요. 한 친구가 「가장 많이 늘어난 2019년과 2020년 사이가 가장 많이 변한 때야.」라고 말했어요. 친구의 말이 맞는지 쓰고, 가장 많이 변한 때를 찾는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C9","difficulty":4,"kind":"essay","stem":"우유 생산량은 해마다 204, 203, 209, 201, 198만 톤으로 달라졌어요. 한 친구가 「가장 많이 늘어난 2019년과 2020년 사이가 가장 많이 변한 때야.」라고 말했어요. 친구의 말이 맞는지 쓰고, 가장 많이 변한 때를 찾는 방법을 써 보세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 2019년과 2020년 사이에는 6만 톤 늘어났지만, 2020년과 2021년 사이에는 8만 톤 줄어들었다. 줄어든 것도 변한 것이므로 가장 많이 변한 때는 2020년과 2021년 사이이다. 가장 많이 변한 때를 찾으려면 늘어난 정도와 줄어든 정도를 모두 구해 견주거나, 가장 가파른 선분을 찾는다.","scoring_points":["친구의 말이 틀렸다고 썼는가","8만 톤 줄어든 2020년과 2021년 사이를 찾았는가","늘어난 것과 줄어든 것을 모두 견주어야 한다고 썼는가"]},"explanation":["늘어난 정도: 1만 톤 줄고, 6만 톤 늘고, 8만 톤 줄고, 3만 톤 줄었어요.","가장 크게 변한 것은 8만 톤 줄어든 2020년과 2021년 사이예요.","줄어든 것도 변한 것이라 둘 다 견주어야 해요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[204,203,209,201,198]}],"step":1,"ymax":210,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":195,"wave":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#1','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":1,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 폭염 일수","correct":true},{"t":"지역별 폭염 일수","mis":"M4-2-u5-X15"},{"t":"우리 반이 좋아하는 계절","mis":"M4-2-u5-X15"},{"t":"학교별 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 폭염 일수」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"월별 우리 집 전기 사용량","correct":true},{"t":"가전제품별 전기 사용량","mis":"M4-2-u5-X15"},{"t":"방별 전등 수","mis":"M4-2-u5-X15"},{"t":"반별 에너지 지킴이 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「월별 우리 집 전기 사용량」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null},{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"해마다 잰 우리 동네 평균 기온","correct":true},{"t":"나라별 평균 기온","mis":"M4-2-u5-X15"},{"t":"도시별 비 온 날수","mis":"M4-2-u5-X15"},{"t":"계절별 좋아하는 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「해마다 잰 우리 동네 평균 기온」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#2','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','인터넷으로 자료를 모을 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X16']::text[],true,'{"seq":2,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"인터넷으로 자료를 모을 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"믿을 수 있는 누리집에서 최근 자료를 모아요.","correct":true},{"t":"아무 누리집에서나 빨리 모아요.","mis":"M4-2-u5-X16"},{"t":"가장 오래된 자료를 모아요.","mis":"M4-2-u5-X16"},{"t":"출처는 적지 않아도 돼요.","mis":"M4-2-u5-X16"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","자료는 믿을 수 있는 누리집에서 최근 것을 모으고 출처를 함께 적어요.","모은 자료는 표로 정리한 뒤 꺾은선그래프로 나타내요."],"variant_rule":{"alt":[{"stem":"모은 자료를 꺾은선그래프로 옮기기 전에 먼저 하면 좋은 일은 무엇인가요?","options":[{"t":"표로 정리해요.","correct":true},{"t":"점부터 찍어요.","mis":"M4-2-u5-X06"},{"t":"물결선부터 그려요.","mis":"M4-2-u5-X09"},{"t":"곡선부터 그려요.","mis":"M4-2-u5-X06"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","자료는 믿을 수 있는 누리집에서 최근 것을 모으고 출처를 함께 적어요.","모은 자료는 표로 정리한 뒤 꺾은선그래프로 나타내요."],"asset":null},{"stem":"자료를 모을 때 출처를 함께 적는 까닭은 무엇인가요?","options":[{"t":"어디에서 가져온 자료인지 알 수 있게 하려고","correct":true},{"t":"그래프를 예쁘게 꾸미려고","mis":"M4-2-u5-X16"},{"t":"자료의 값을 바꾸려고","mis":"M4-2-u5-X16"},{"t":"물결선 자리를 정하려고","mis":"M4-2-u5-X16"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","자료는 믿을 수 있는 누리집에서 최근 것을 모으고 출처를 함께 적어요.","모은 자료는 표로 정리한 뒤 꺾은선그래프로 나타내요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#3','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'sa','auto','직접 모은 자료를 표로 정리했어요. 미세 먼지 나쁨 일수가 가장 많았던 때의 값은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C10","difficulty":1,"kind":"sa","stem":"직접 모은 자료를 표로 정리했어요. 미세 먼지 나쁨 일수가 가장 많았던 때의 값은 며칠인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["표의 값을 하나씩 견주어요.","가장 큰 값은 2016년의 16일이에요.","답은 16일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020"],"counts":[16,8,14,12,13],"vh":"미세 먼지 나쁨 일수","unit":"일","title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"직접 모은 자료를 표로 정리했어요. 폭염 일수가 가장 많았던 때의 값은 며칠인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["표의 값을 하나씩 견주어요.","가장 큰 값은 2021년의 19일이에요.","답은 19일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021","2022"],"counts":[9,4,7,11,19,12],"vh":"폭염 일수","unit":"일","title":"연도별 폭염 일수"}},{"stem":"직접 모은 자료를 표로 정리했어요. 자외선 지수 매우 높음 일수가 가장 많았던 때의 값은 며칠인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["표의 값을 하나씩 견주어요.","가장 큰 값은 4월의 21일이에요.","답은 21일이에요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월"],"counts":[21,15,5,9,12],"vh":"자외선 지수 매우 높음 일수","unit":"일","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#4','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',1,'mc','auto','「월별 줄넘기 기록」을 표로 정리해 꺾은선그래프로 나타내려고 해요. 가로에는 무엇을 나타내야 하나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":4,"concept":"M4-2-u5-C10","difficulty":1,"kind":"mc","stem":"「월별 줄넘기 기록」을 표로 정리해 꺾은선그래프로 나타내려고 해요. 가로에는 무엇을 나타내야 하나요?","options":[{"t":"월","correct":true},{"t":"줄넘기 기록","mis":"M4-2-u5-X01"},{"t":"조사한 사람","mis":"M4-2-u5-X01"},{"t":"합계","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","가로에는 때(월), 세로에는 양(줄넘기 기록)을 나타내요.","가로에는 월을 나타내요."],"variant_rule":{"alt":[{"stem":"「월별 선인장 줄기의 길이」를 표로 정리해 꺾은선그래프로 나타내려고 해요. 세로에는 무엇을 나타내야 하나요?","options":[{"t":"선인장 줄기의 길이","correct":true},{"t":"월","mis":"M4-2-u5-X01"},{"t":"조사한 사람","mis":"M4-2-u5-X01"},{"t":"합계","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","가로에는 때(월), 세로에는 양(선인장 줄기의 길이)을 나타내요.","세로에는 선인장 줄기의 길이를 나타내요."],"asset":null},{"stem":"「월별 나무의 키」를 표로 정리해 꺾은선그래프로 나타내려고 해요. 가로에는 무엇을 나타내야 하나요?","options":[{"t":"월","correct":true},{"t":"나무의 키","mis":"M4-2-u5-X01"},{"t":"조사한 사람","mis":"M4-2-u5-X01"},{"t":"합계","mis":"M4-2-u5-X01"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 나타내요.","가로에는 때(월), 세로에는 양(나무의 키)을 나타내요.","가로에는 월을 나타내요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#5','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'sa','auto','표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C10","difficulty":2,"kind":"sa","stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 12회예요.","그래서 세로 눈금은 적어도 12회까지 나타내요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020"],"counts":[4,3,8,12,6],"vh":"태풍 발생 횟수","unit":"회","title":"연도별 태풍 발생 횟수"},"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 며칠까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["20"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 20일이에요.","그래서 세로 눈금은 적어도 20일까지 나타내요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[4,7,9,10,20],"vh":"폭염 일수","unit":"일","title":"연도별 폭염 일수"}},{"stem":"이번에는 다른 그림이에요. 표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["145"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 145회예요.","그래서 세로 눈금은 적어도 145회까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월","8월"],"counts":[135,115,50,100,145,115],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#6','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'sa','auto','표를 보고 답하세요. 자외선 지수 매우 높음 일수가 전월과 비교하여 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C10","difficulty":2,"kind":"sa","stem":"표를 보고 답하세요. 자외선 지수 매우 높음 일수가 전월과 비교하여 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["이웃한 두 때의 변화: −3, +1, +6, −10.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 정도는 10일(7월과 8월 사이)."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월"],"counts":[14,11,12,18,8],"vh":"자외선 지수 매우 높음 일수","unit":"일","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 교실 온도가 한 시간 전과 비교하여 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["이웃한 두 때의 변화: −5, +7, +1, +2.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 정도는 7 °C(10시와 11시 사이)."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[19,14,21,22,24],"vh":"교실 온도","unit":"°C","title":"시각별 교실 온도"}},{"stem":"표를 보고 답하세요. 도서관에서 빌려 간 책 수가 전월과 비교하여 가장 많이 변한 정도는 몇 권인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["이웃한 두 때의 변화: −40, −110, +10, +100.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 정도는 110권(4월과 5월 사이)."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[250,210,100,110,210],"vh":"도서관에서 빌려 간 책 수","unit":"권","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
