INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#9','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',2,'ox','auto','「지역별 폭염 일수」는 꺾은선그래프로 나타내기에 알맞아요.',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":9,"concept":"M4-2-u5-C10","difficulty":2,"kind":"ox","stem":"「지역별 폭염 일수」는 꺾은선그래프로 나타내기에 알맞아요.","answer":"X","reason_options":[{"t":"시간에 따라 달라지는 자료가 아니라서","correct":true},{"t":"지역에도 차례가 있어서","mis":"M4-2-u5-X15"}],"mis":"M4-2-u5-X15","explanation":["꺾은선그래프의 주제는 시간에 따라 달라지는 것이에요.","자료는 믿을 수 있는 누리집에서 최근 것을 모아요.","어디서 가져왔는지 출처를 함께 적어요."],"variant_rule":{"alt":[{"stem":"자료를 모을 때는 출처를 함께 적어요.","answer":"O","reason_options":[{"t":"어디에서 가져온 자료인지 알 수 있게 하려고","correct":true},{"t":"출처는 적지 않아도 되어서","mis":"M4-2-u5-X16"}],"explanation":["꺾은선그래프의 주제는 시간에 따라 달라지는 것이에요.","자료는 믿을 수 있는 누리집에서 최근 것을 모아요.","어디서 가져왔는지 출처를 함께 적어요."],"asset":null},{"stem":"「월별 강수량」은 꺾은선그래프로 나타내기에 알맞아요.","answer":"O","reason_options":[{"t":"시간에 따라 달라지는 자료라서","correct":true},{"t":"달 이름은 글자라서 그릴 수 없어서","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프의 주제는 시간에 따라 달라지는 것이에요.","자료는 믿을 수 있는 누리집에서 최근 것을 모아요.","어디서 가져왔는지 출처를 함께 적어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_basic#10','math',4,2,'u5','L06','g4_2_math_u5_L06_basic','lesson_basic','M4-2-u5-C10',3,'sa','auto','모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 9시 22 °C, 10시 □, 11시 27 °C, 12시 22 °C, 13시 15 °C. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 9시 22 °C, 10시 □, 11시 27 °C, 12시 22 °C, 13시 15 °C. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["23"],"explanation":["□는 10시의 값이에요.","그래프에서 10시의 점을 찾아 세로 눈금을 읽어요(한 칸 1 °C).","□ = 23."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[22,23,27,22,15]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 3월 60권, 4월 100권, 5월 □, 6월 200권, 7월 70권. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["80"],"explanation":["□는 5월의 값이에요.","그래프에서 5월의 점을 찾아 세로 눈금을 읽어요(한 칸 10권).","□ = 80."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[60,100,80,200,70]}],"step":10,"ymax":210,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 2016년 12회, 2017년 7회, 2018년 6회, 2019년 4회, 2020년 □. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["10"],"explanation":["□는 2020년의 값이에요.","그래프에서 2020년의 점을 찾아 세로 눈금을 읽어요(한 칸 1회).","□ = 10."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[12,7,6,4,10]}],"step":1,"ymax":13,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#1','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',2,'sa','auto','표를 보고 답하세요. 태풍 발생 횟수가 전년도와 비교하여 가장 많이 변한 정도는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u5-C10","difficulty":2,"kind":"sa","stem":"표를 보고 답하세요. 태풍 발생 횟수가 전년도와 비교하여 가장 많이 변한 정도는 몇 회인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["이웃한 두 때의 변화: +4, +1, −2, +3.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 정도는 4회(2016년과 2017년 사이)."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020"],"counts":[5,9,10,8,11],"vh":"태풍 발생 횟수","unit":"회","title":"연도별 태풍 발생 횟수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 운동장의 기온이 한 시간 전과 비교하여 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["이웃한 두 때의 변화: +2, −12, +4, +6.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 정도는 12 °C(10시와 11시 사이)."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[26,28,16,20,26],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"}},{"stem":"표를 보고 답하세요. 줄넘기 기록이 전월과 비교하여 가장 많이 변한 정도는 몇 회인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["이웃한 두 때의 변화: −30, +65, +20, −5.","늘어난 것과 줄어든 것을 모두 견주어요.","가장 많이 변한 정도는 65회(4월과 5월 사이)."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[80,50,115,135,130],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#2','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',2,'mc','auto','기후변화 자료를 모으기에 알맞은 곳은 어느 것인가요?',ARRAY['M4-2-u5-X16']::text[],true,'{"seq":2,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"기후변화 자료를 모으기에 알맞은 곳은 어느 것인가요?","options":[{"t":"기상자료개방포털 같은 믿을 수 있는 누리집","correct":true},{"t":"누가 썼는지 모르는 게시글","mis":"M4-2-u5-X16"},{"t":"10년도 더 지난 신문 한 장","mis":"M4-2-u5-X16"},{"t":"친구가 대충 기억하는 수","mis":"M4-2-u5-X16"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","자료는 믿을 수 있는 누리집에서 최근 것을 모으고 출처를 함께 적어요.","모은 자료는 표로 정리한 뒤 꺾은선그래프로 나타내요."],"variant_rule":{"alt":[{"stem":"오래된 자료 대신 최근 자료를 모으는 까닭은 무엇인가요?","options":[{"t":"지금의 모습을 알 수 있어서","correct":true},{"t":"값이 더 커서","mis":"M4-2-u5-X16"},{"t":"그래프가 짧아져서","mis":"M4-2-u5-X16"},{"t":"출처를 적지 않아도 돼서","mis":"M4-2-u5-X16"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","자료는 믿을 수 있는 누리집에서 최근 것을 모으고 출처를 함께 적어요.","모은 자료는 표로 정리한 뒤 꺾은선그래프로 나타내요."],"asset":null},{"stem":"자료를 직접 모아 꺾은선그래프로 나타내는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 자료 모으기 → 표로 정리 → 그래프로 나타내기","correct":true},{"t":"자료 모으기 → 그래프로 나타내기 → 주제 정하기 → 표로 정리","mis":"M4-2-u5-X21"},{"t":"표로 정리 → 주제 정하기 → 그래프로 나타내기 → 자료 모으기","mis":"M4-2-u5-X21"},{"t":"그래프로 나타내기 → 자료 모으기 → 표로 정리 → 주제 정하기","mis":"M4-2-u5-X21"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","자료는 믿을 수 있는 누리집에서 최근 것을 모으고 출처를 함께 적어요.","모은 자료는 표로 정리한 뒤 꺾은선그래프로 나타내요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#3','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'sa','auto','표를 보고 답하세요. 자외선 지수 매우 높음 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"표를 보고 답하세요. 자외선 지수 매우 높음 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["가장 큰 값은 9월의 22일이에요.","가장 작은 값은 7월의 10일이에요.","22 − 10 = 12일이에요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월","9월"],"counts":[11,19,17,10,13,22],"vh":"자외선 지수 매우 높음 일수","unit":"일","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 교실 온도가 가장 높았던 때와 가장 낮았던 때의 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["가장 큰 값은 9시의 26 °C예요.","가장 작은 값은 13시의 17 °C예요.","26 − 17 = 9 °C예요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[26,21,19,20,17],"vh":"교실 온도","unit":"°C","title":"시각별 교실 온도"}},{"stem":"표를 보고 답하세요. 도서관에서 빌려 간 책 수가 가장 많았던 때와 가장 적었던 때의 차는 몇 권인가요? 숫자로 쓰세요.","answer":["190"],"explanation":["가장 큰 값은 3월의 240권이에요.","가장 작은 값은 5월의 50권이에요.","240 − 50 = 190권이에요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월","8월"],"counts":[240,130,50,100,110,180],"vh":"도서관에서 빌려 간 책 수","unit":"권","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#4','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'error','auto','자료를 모아 꺾은선그래프로 나타내는 방법을 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X15','M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C10","difficulty":3,"kind":"error","stem":"자료를 모아 꺾은선그래프로 나타내는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「지역별 폭염 일수를 꺾은선그래프로 나타낼 거야.」","correct":true,"mis_target":"M4-2-u5-X15"},{"t":"지아 — 「믿을 수 있는 누리집에서 모았어.」","mis":"M4-2-u5-X21"},{"t":"준서 — 「표로 먼저 정리했어.」","mis":"M4-2-u5-X21"},{"t":"민서 — 「연도별 폭염 일수를 조사했어.」","mis":"M4-2-u5-X21"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","하랑의 말은 자료를 모으는 방법과 맞지 않아요.","믿을 수 있는 곳에서 최근 자료를 모으고 출처를 적어요."],"variant_rule":{"alt":[{"stem":"자료를 모아 꺾은선그래프로 나타내는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「출처는 안 적어도 돼.」","correct":true,"mis_target":"M4-2-u5-X16"},{"t":"준서 — 「표로 먼저 정리했어.」","mis":"M4-2-u5-X21"},{"t":"민서 — 「연도별 폭염 일수를 조사했어.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「출처를 함께 적었어.」","mis":"M4-2-u5-X21"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","지아의 말은 자료를 모으는 방법과 맞지 않아요.","믿을 수 있는 곳에서 최근 자료를 모으고 출처를 적어요."],"asset":null},{"stem":"자료를 모아 꺾은선그래프로 나타내는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「가장 오래된 자료를 골라 모았어.」","correct":true,"mis_target":"M4-2-u5-X16"},{"t":"민서 — 「연도별 폭염 일수를 조사했어.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「출처를 함께 적었어.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「믿을 수 있는 누리집에서 모았어.」","mis":"M4-2-u5-X21"}],"explanation":["주제는 시간에 따라 달라지는 것으로 정해요.","준서의 말은 자료를 모으는 방법과 맞지 않아요.","믿을 수 있는 곳에서 최근 자료를 모으고 출처를 적어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#5','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'sa','auto','모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 9시 16 °C, 10시 10 °C, 11시 20 °C, 12시 18 °C, 13시 □. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 9시 16 °C, 10시 10 °C, 11시 20 °C, 12시 18 °C, 13시 □. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["22"],"explanation":["□는 13시의 값이에요.","그래프에서 13시의 점을 찾아 세로 눈금을 읽어요(한 칸 2 °C).","□ = 22."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[16,10,20,18,22]}],"step":2,"ymax":24,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 3월 30회, 4월 □, 5월 75회, 6월 20회, 7월 70회. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["90"],"explanation":["□는 4월의 값이에요.","그래프에서 4월의 점을 찾아 세로 눈금을 읽어요(한 칸 5회).","□ = 90."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[30,90,75,20,70]}],"step":5,"ymax":95,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"모은 자료를 표와 꺾은선그래프로 나타냈어요. 표 — 2016년 21일, 2017년 19일, 2018년 20일, 2019년 17일, 2020년 □. 그래프를 보고 □에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["22"],"explanation":["□는 2020년의 값이에요.","그래프에서 2020년의 점을 찾아 세로 눈금을 읽어요(한 칸 1일).","□ = 22."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[21,19,20,17,22]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#6','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'mc','auto','한 시간 전과 비교하여 운동장의 기온이 가장 많이 줄어든 때는 언제인가요?',ARRAY['M4-2-u5-X21','M4-2-u5-X12']::text[],true,'{"seq":6,"concept":"M4-2-u5-C10","difficulty":3,"kind":"mc","stem":"한 시간 전과 비교하여 운동장의 기온이 가장 많이 줄어든 때는 언제인가요?","options":[{"t":"10시","correct":true},{"t":"11시","mis":"M4-2-u5-X21"},{"t":"12시","mis":"M4-2-u5-X12"},{"t":"13시","mis":"M4-2-u5-X21"}],"explanation":["변화: −14, +10, −12, +6, +8.","가장 가파르게 내려간 선분은 9시와 10시 사이예요.","가장 많이 줄어든 때는 10시예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[34,20,30,18,24,32]}],"step":2,"ymax":36,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 한 시간 전과 비교하여 운동장의 기온이 가장 많이 줄어든 때는 언제인가요?","options":[{"t":"11시","correct":true},{"t":"10시","mis":"M4-2-u5-X21"},{"t":"12시","mis":"M4-2-u5-X12"},{"t":"13시","mis":"M4-2-u5-X21"}],"explanation":["변화: +10, −8, −4, +2.","가장 가파르게 내려간 선분은 10시와 11시 사이예요.","가장 많이 줄어든 때는 11시예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[18,28,20,16,18]}],"step":2,"ymax":30,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}},{"stem":"이번에는 다른 그림이에요. 한 시간 전과 비교하여 운동장의 기온이 가장 많이 줄어든 때는 언제인가요?","options":[{"t":"10시","correct":true},{"t":"14시","mis":"M4-2-u5-X21"},{"t":"13시","mis":"M4-2-u5-X12"},{"t":"11시","mis":"M4-2-u5-X21"}],"explanation":["변화: −14, +10, −8, −4, +12.","가장 가파르게 내려간 선분은 9시와 10시 사이예요.","가장 많이 줄어든 때는 10시예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[24,10,20,12,8,20]}],"step":2,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#7','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',3,'mc','auto','폭염 일수가 최근 들어 많아지고 있어요. 우리가 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":7,"concept":"M4-2-u5-C10","difficulty":3,"kind":"mc","stem":"폭염 일수가 최근 들어 많아지고 있어요. 우리가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"안 쓰는 전기 코드를 뽑아 놓아요.","correct":true},{"t":"가까운 거리도 자동차를 타요.","mis":"M4-2-u5-X21"},{"t":"에어컨을 하루 종일 켜 둬요.","mis":"M4-2-u5-X21"},{"t":"일회용품을 더 많이 써요.","mis":"M4-2-u5-X21"}],"explanation":["그래프에서 읽어 낸 흐름을 생활과 이어 생각해요.","늘어나는 것이 걱정된다면 그 까닭을 줄이는 일을 찾아요.","「안 쓰는 전기 코드를 뽑아 놓아요」 — 우리가 할 수 있는 일이에요."],"variant_rule":{"alt":[{"stem":"1인당 하루 물 사용량이 해마다 늘고 있어요. 우리가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"양치할 때 컵에 물을 받아 써요.","correct":true},{"t":"물을 틀어 놓고 이를 닦아요.","mis":"M4-2-u5-X21"},{"t":"샤워를 더 오래 해요.","mis":"M4-2-u5-X21"},{"t":"빈 그릇도 물을 틀어 놓고 헹궈요.","mis":"M4-2-u5-X21"}],"explanation":["그래프에서 읽어 낸 흐름을 생활과 이어 생각해요.","늘어나는 것이 걱정된다면 그 까닭을 줄이는 일을 찾아요.","「양치할 때 컵에 물을 받아 써요」 — 우리가 할 수 있는 일이에요."],"asset":null},{"stem":"미세 먼지 나쁨 일수가 늘고 있어요. 우리가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"가까운 거리는 걷거나 대중교통을 이용해요.","correct":true},{"t":"짧은 거리도 자동차로 다녀요.","mis":"M4-2-u5-X21"},{"t":"쓰레기를 태워 없애요.","mis":"M4-2-u5-X21"},{"t":"공회전을 오래 해요.","mis":"M4-2-u5-X21"}],"explanation":["그래프에서 읽어 낸 흐름을 생활과 이어 생각해요.","늘어나는 것이 걱정된다면 그 까닭을 줄이는 일을 찾아요.","「가까운 거리는 걷거나 대중교통을 이용해요」 — 우리가 할 수 있는 일이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#8','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',4,'sa','auto','교실 온도는 9시부터 14시까지 몇 °C 늘어났나요? (가운데에서 늘고 준 것과 상관없이 두 때만 견주어요.) 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C10","difficulty":4,"kind":"sa","stem":"교실 온도는 9시부터 14시까지 몇 °C 늘어났나요? (가운데에서 늘고 준 것과 상관없이 두 때만 견주어요.) 숫자로 쓰세요.","answer":["1"],"explanation":["9시 25 °C, 14시 26 °C예요.","가운데 때의 값은 쓰지 않고 두 때의 값만 빼요.","26 − 25 = 1 — 1 °C 늘어났어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[25,23,26,21,27,26]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"도서관에서 빌려 간 책 수는 5월부터 8월까지 몇 권 줄어들었나요? (가운데에서 늘고 준 것과 상관없이 두 때만 견주어요.) 숫자로 쓰세요.","answer":["60"],"explanation":["5월 190권, 8월 130권이에요.","가운데 때의 값은 쓰지 않고 두 때의 값만 빼요.","190 − 130 = 60 — 60권 줄어들었어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[170,150,190,280,210,130]}],"step":10,"ymax":290,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"태풍 발생 횟수는 2018년부터 2021년까지 몇 회 줄어들었나요? (가운데에서 늘고 준 것과 상관없이 두 때만 견주어요.) 숫자로 쓰세요.","answer":["6"],"explanation":["2018년 8회, 2021년 2회예요.","가운데 때의 값은 쓰지 않고 두 때의 값만 빼요.","8 − 2 = 6 — 6회 줄어들었어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[7,11,8,9,7,2]}],"step":1,"ymax":12,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#9','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',4,'sa','auto','전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C10","difficulty":4,"kind":"sa","stem":"전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +6, −8, −1, +2, +4, −9.","늘어난 때: 5월, 8월, 9월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[16,22,14,13,15,19,10]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: −1, +2, +8, +7, −4, +6.","늘어난 때: 6월, 7월, 8월, 10월.","모두 4번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[5,4,6,14,21,17,23]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +4, +3, −11, −2, +6, +8.","늘어난 때: 5월, 6월, 9월, 10월.","모두 4번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[11,15,18,7,5,11,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L06_challenge#10','math',4,2,'u5','L06','g4_2_math_u5_L06_challenge','lesson_challenge','M4-2-u5-C10',4,'essay','teacher','서아는 「지역별 폭염 일수」를, 도윤이는 「연도별 폭염 일수」를 조사해 꺾은선그래프로 나타내려고 해요. 누구의 주제가 알맞은지 까닭과 함께 쓰고, 인터넷으로 자료를 모을 때 지킬 점을 두 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C10","difficulty":4,"kind":"essay","stem":"서아는 「지역별 폭염 일수」를, 도윤이는 「연도별 폭염 일수」를 조사해 꺾은선그래프로 나타내려고 해요. 누구의 주제가 알맞은지 까닭과 함께 쓰고, 인터넷으로 자료를 모을 때 지킬 점을 두 가지 써 보세요.","answer_guide":{"answer":"예: 도윤이의 주제가 알맞다. 연도별 폭염 일수는 시간에 따라 달라지는 자료라서 꺾은선그래프로 변화를 알아보기 좋지만, 지역별 폭염 일수는 지역끼리 견주는 자료라서 막대그래프가 더 어울린다. 자료를 모을 때는 믿을 수 있는 누리집에서 최근 자료를 모으고, 어디에서 가져왔는지 출처를 함께 적는다.","scoring_points":["도윤이의 주제를 골랐는가","시간에 따라 달라지는 자료라는 까닭을 썼는가","믿을 수 있는 곳·최근 자료·출처 가운데 두 가지를 썼는가"]},"explanation":["연도별 = 시간에 따라 달라지는 자료.","지역별 = 항목끼리 견주는 자료.","믿을 수 있는 누리집·최근 자료·출처 적기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#1','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'mc','auto','자료의 크기를 한눈에 견주기에 알맞은 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X05','M4-2-u5-X03']::text[],true,'{"seq":1,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"자료의 크기를 한눈에 견주기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선","mis":"M4-2-u5-X05"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["그림그래프·막대그래프는 자료의 크기를 한눈에 견주기 좋아요.","꺾은선그래프는 시간에 따른 변화를 알아보기 좋아요.","항목끼리 견주는 자료이니 막대그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"반별 학생 수처럼 항목끼리 견주는 자료에 알맞은 그래프는 어느 것인가요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"수직선","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["그림그래프·막대그래프는 자료의 크기를 한눈에 견주기 좋아요.","꺾은선그래프는 시간에 따른 변화를 알아보기 좋아요.","항목끼리 견주는 자료이니 막대그래프가 알맞아요."],"asset":null},{"stem":"도시별 도서관 수를 한눈에 견주려고 해요. 알맞은 그래프는 어느 것인가요?","options":[{"t":"그림그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선","mis":"M4-2-u5-X05"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["그림그래프·막대그래프는 자료의 크기를 한눈에 견주기 좋아요.","꺾은선그래프는 시간에 따른 변화를 알아보기 좋아요.","항목끼리 견주는 자료이니 그림그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#2','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'mc','auto','시간에 따른 자료의 변화를 알아보기에 알맞은 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],true,'{"seq":2,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"시간에 따른 자료의 변화를 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"연도별 해수면 높이가 어떻게 달라졌는지 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null},{"stem":"월별 기온이 어떻게 변했는지 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#3','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'sa','auto','폭염 일수는 2018년부터 2020년까지 며칠 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C11","difficulty":1,"kind":"sa","stem":"폭염 일수는 2018년부터 2020년까지 며칠 늘어났나요? 숫자로 쓰세요.","answer":["1"],"explanation":["2018년 19일, 2020년 20일이에요.","두 때의 값만 써서 큰 값에서 작은 값을 빼요.","20 − 19 = 1 — 1일 늘어났어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[10,19,15,20,12]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"},"variant_rule":{"alt":[{"stem":"자외선 지수 매우 높음 일수는 6월부터 9월까지 며칠 줄어들었나요? 숫자로 쓰세요.","answer":["13"],"explanation":["6월 23일, 9월 10일이에요.","두 때의 값만 써서 큰 값에서 작은 값을 빼요.","23 − 10 = 13 — 13일 줄어들었어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[17,15,23,18,7,10]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"교실 온도는 11시부터 13시까지 몇 °C 늘어났나요? 숫자로 쓰세요.","answer":["1"],"explanation":["11시 16 °C, 13시 17 °C예요.","두 때의 값만 써서 큰 값에서 작은 값을 빼요.","17 − 16 = 1 — 1 °C 늘어났어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[14,20,16,19,17]}],"step":1,"ymax":21,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#4','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',1,'mc','auto','강별 수질 오염 발생 횟수를 한눈에 견주기에 가장 알맞지 않은 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"강별 수질 오염 발생 횟수를 한눈에 견주기에 가장 알맞지 않은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X21"},{"t":"막대그래프","mis":"M4-2-u5-X21"},{"t":"표","mis":"M4-2-u5-X21"}],"explanation":["강별 수질 오염 발생 횟수는 강끼리 견주는 자료예요.","그림그래프·막대그래프·표는 견주기에 쓸 수 있어요.","꺾은선그래프는 시간에 따라 모은 자료가 아니라서 알맞지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["한강","금강","낙동강","영산강","섬진강"],"series":[{"vals":[15,18,8,5,13]}],"step":1,"ymax":19,"title":"강별 수질 오염 발생 횟수","ylab":"(회)"},"variant_rule":{"alt":[{"stem":"도시별 도서관 수를 한눈에 견주기에 가장 알맞지 않은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X21"},{"t":"막대그래프","mis":"M4-2-u5-X21"},{"t":"표","mis":"M4-2-u5-X21"}],"explanation":["도시별 도서관 수는 도시끼리 견주는 자료예요.","그림그래프·막대그래프·표는 견주기에 쓸 수 있어요.","꺾은선그래프는 시간에 따라 모은 자료가 아니라서 알맞지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["서울","부산","대구","광주","대전"],"series":[{"vals":[220,240,80,40,100]}],"step":10,"ymax":250,"title":"도시별 도서관 수","ylab":"(관)"}},{"stem":"반별 재활용품 수를 한눈에 견주기에 가장 알맞지 않은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X21"},{"t":"막대그래프","mis":"M4-2-u5-X21"},{"t":"표","mis":"M4-2-u5-X21"}],"explanation":["반별 재활용품 수는 반끼리 견주는 자료예요.","그림그래프·막대그래프·표는 견주기에 쓸 수 있어요.","꺾은선그래프는 시간에 따라 모은 자료가 아니라서 알맞지 않아요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반"],"series":[{"vals":[60,45,65,30,95]}],"step":5,"ymax":100,"title":"반별 재활용품 수","ylab":"(개)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUD