INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#5','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','「6월부터 10월까지의 월별 최고 온도」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":5,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「6월부터 10월까지의 월별 최고 온도」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[33,31,28,23,24]}],"step":1,"ymax":34,"title":"6월부터 10월까지의 월별 최고 온도","ylab":"(°C)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"「연도별 해수면 높이」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[26,29,30,25,23]}],"step":1,"ymax":31,"title":"연도별 해수면 높이","ylab":"(cm)","xlab":"(년)"}},{"stem":"「월별 강수량」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["5월","6월","7월","8월","9월"],"series":[{"vals":[190,240,220,260,130]}],"step":10,"ymax":270,"title":"월별 강수량","ylab":"(mm)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#6','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'sa','auto','「강별 수질 오염 발생 횟수」를 나타낸 막대그래프예요. 가장 많은 강과 가장 적은 강의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C11","difficulty":2,"kind":"sa","stem":"「강별 수질 오염 발생 횟수」를 나타낸 막대그래프예요. 가장 많은 강과 가장 적은 강의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["세로 눈금 한 칸은 1회예요.","가장 많은 것은 섬진강 13회, 가장 적은 것은 낙동강 4회예요.","13 − 4 = 9회예요."],"asset":{"type":"lgraph","mode":"bar","xs":["한강","금강","낙동강","영산강","섬진강"],"series":[{"vals":[12,5,4,11,13]}],"step":1,"ymax":14,"title":"강별 수질 오염 발생 횟수","ylab":"(회)"},"variant_rule":{"alt":[{"stem":"「도시별 도서관 수」를 나타낸 막대그래프예요. 가장 많은 도시와 가장 적은 도시의 차는 몇 관인가요? 숫자로 쓰세요.","answer":["190"],"explanation":["세로 눈금 한 칸은 10관이에요.","가장 많은 것은 대전 220관, 가장 적은 것은 서울 30관이에요.","220 − 30 = 190관이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["서울","부산","대구","광주","대전"],"series":[{"vals":[30,70,40,210,220]}],"step":10,"ymax":230,"title":"도시별 도서관 수","ylab":"(관)"}},{"stem":"「반별 재활용품 수」를 나타낸 막대그래프예요. 가장 많은 반과 가장 적은 반의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["세로 눈금 한 칸은 5개예요.","가장 많은 것은 1반 120개, 가장 적은 것은 2반 20개예요.","120 − 20 = 100개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반"],"series":[{"vals":[120,20,25,85,50]}],"step":5,"ymax":125,"title":"반별 재활용품 수","ylab":"(개)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#7','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','자료에 알맞은 그래프를 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X17']::text[],true,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"자료에 알맞은 그래프를 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료를 모은 목적과 자료의 특성을 함께 생각해요.","correct":true},{"t":"언제나 꺾은선그래프를 골라요.","mis":"M4-2-u5-X17"},{"t":"가장 그리기 쉬운 그래프를 골라요.","mis":"M4-2-u5-X17"},{"t":"값이 큰 자료는 무조건 막대그래프로 그려요.","mis":"M4-2-u5-X17"}],"explanation":["그림그래프 — 한눈에 견주기, 막대그래프 — 크기를 한눈에, 꺾은선그래프 — 시간에 따른 변화.","자료를 모은 목적(견주기인지 변화인지)을 생각해요.","자료의 특성(항목끼리인지 시간에 따른 것인지)도 함께 생각해요."],"variant_rule":{"alt":[{"stem":"그림그래프의 편리한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료를 한눈에 견주기 쉬워요.","correct":true},{"t":"시간에 따른 변화를 알아보기 쉬워요.","mis":"M4-2-u5-X17"},{"t":"두 때 사이의 값을 짐작하기 쉬워요.","mis":"M4-2-u5-X17"},{"t":"물결선으로 필요 없는 부분을 줄일 수 있어요.","mis":"M4-2-u5-X05"}],"explanation":["그림그래프 — 한눈에 견주기, 막대그래프 — 크기를 한눈에, 꺾은선그래프 — 시간에 따른 변화.","자료를 모은 목적(견주기인지 변화인지)을 생각해요.","자료의 특성(항목끼리인지 시간에 따른 것인지)도 함께 생각해요."],"asset":null},{"stem":"꺾은선그래프의 편리한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"시간에 따른 변화를 알아보기 쉬워요.","correct":true},{"t":"항목끼리의 크기만 견주기 쉬워요.","mis":"M4-2-u5-X17"},{"t":"그림으로 나타내 재미있어요.","mis":"M4-2-u5-X03"},{"t":"자료를 모으지 않아도 돼요.","mis":"M4-2-u5-X16"}],"explanation":["그림그래프 — 한눈에 견주기, 막대그래프 — 크기를 한눈에, 꺾은선그래프 — 시간에 따른 변화.","자료를 모은 목적(견주기인지 변화인지)을 생각해요.","자료의 특성(항목끼리인지 시간에 따른 것인지)도 함께 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#8','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'mc','auto','꺾은선그래프보다 막대그래프로 나타내기에 더 알맞은 자료는 어느 것인가요?',ARRAY['M4-2-u5-X17']::text[],true,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"꺾은선그래프보다 막대그래프로 나타내기에 더 알맞은 자료는 어느 것인가요?","options":[{"t":"도시별 도서관 수","correct":true},{"t":"월별 재활용품 수","mis":"M4-2-u5-X17"},{"t":"연도별 수질 오염 발생 횟수","mis":"M4-2-u5-X17"},{"t":"시각별 운동장 기온","mis":"M4-2-u5-X17"}],"explanation":["막대그래프는 항목끼리 크기를 견주기 좋아요.","「도시별 도서관 수」는 항목끼리 견주는 자료예요.","나머지는 시간에 따라 달라지는 자료라 꺾은선그래프가 더 알맞아요."],"variant_rule":{"alt":[{"stem":"막대그래프보다 꺾은선그래프로 나타내기에 더 알맞은 자료는 어느 것인가요?","options":[{"t":"월별 재활용품 수","correct":true},{"t":"강별 수질 오염 발생 횟수","mis":"M4-2-u5-X17"},{"t":"과일별 좋아하는 학생 수","mis":"M4-2-u5-X17"},{"t":"나라별 평균 기온","mis":"M4-2-u5-X17"}],"explanation":["꺾은선그래프는 시간에 따른 변화를 알아보기 좋아요.","「월별 재활용품 수」는 시간에 따라 달라지는 자료예요.","나머지는 항목끼리 견주는 자료라 막대그래프가 더 알맞아요."],"asset":null},{"stem":"꺾은선그래프보다 막대그래프로 나타내기에 더 알맞은 자료는 어느 것인가요?","options":[{"t":"강별 수질 오염 발생 횟수","correct":true},{"t":"시각별 운동장 기온","mis":"M4-2-u5-X17"},{"t":"해마다 잰 우리 동네 평균 기온","mis":"M4-2-u5-X17"},{"t":"월별 우리 집 전기 사용량","mis":"M4-2-u5-X17"}],"explanation":["막대그래프는 항목끼리 크기를 견주기 좋아요.","「강별 수질 오염 발생 횟수」는 항목끼리 견주는 자료예요.","나머지는 시간에 따라 달라지는 자료라 꺾은선그래프가 더 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#9','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',2,'ox','auto','강별 수질 오염 발생 횟수는 꺾은선그래프로 나타내기에 알맞아요.',ARRAY['M4-2-u5-X17']::text[],true,'{"seq":9,"concept":"M4-2-u5-C11","difficulty":2,"kind":"ox","stem":"강별 수질 오염 발생 횟수는 꺾은선그래프로 나타내기에 알맞아요.","answer":"X","reason_options":[{"t":"시간에 따라 모은 자료가 아니라 강끼리 견주는 자료라서","correct":true},{"t":"모든 자료는 꺾은선그래프가 알맞아서","mis":"M4-2-u5-X17"}],"mis":"M4-2-u5-X17","explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞아요.","이어진 자료를 막대그래프로 그려도 틀린 것은 아니에요 — 쓰임이 달라요.","목적과 자료의 특성을 함께 생각해 골라요."],"variant_rule":{"alt":[{"stem":"월별 최고 온도를 막대그래프로 나타내도 틀린 것은 아니에요.","answer":"O","reason_options":[{"t":"달마다의 크기를 견주기 좋은 그래프라서","correct":true},{"t":"이어진 자료는 꼭 꺾은선그래프로 그려야 해서","mis":"M4-2-u5-X18"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞아요.","이어진 자료를 막대그래프로 그려도 틀린 것은 아니에요 — 쓰임이 달라요.","목적과 자료의 특성을 함께 생각해 골라요."],"asset":null},{"stem":"같은 자료라도 알고 싶은 것이 다르면 알맞은 그래프가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"견주려는지 변화를 보려는지에 따라 달라서","correct":true},{"t":"자료마다 맞는 그래프는 하나뿐이라서","mis":"M4-2-u5-X17"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞아요.","이어진 자료를 막대그래프로 그려도 틀린 것은 아니에요 — 쓰임이 달라요.","목적과 자료의 특성을 함께 생각해 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_basic#10','math',4,2,'u5','L07','g4_2_math_u5_L07_basic','lesson_basic','M4-2-u5-C11',3,'sa','auto','「강별 수질 오염 발생 횟수」를 나타낸 막대그래프예요. 섬진강은 영산강보다 몇 회 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u5-C11","difficulty":3,"kind":"sa","stem":"「강별 수질 오염 발생 횟수」를 나타낸 막대그래프예요. 섬진강은 영산강보다 몇 회 더 많은가요? 숫자로 쓰세요.","answer":["15"],"explanation":["세로 눈금 한 칸은 1회예요.","섬진강 18회, 영산강 3회예요.","18 − 3 = 15회예요."],"asset":{"type":"lgraph","mode":"bar","xs":["한강","금강","낙동강","영산강","섬진강"],"series":[{"vals":[13,2,11,3,18]}],"step":1,"ymax":19,"title":"강별 수질 오염 발생 횟수","ylab":"(회)"},"variant_rule":{"alt":[{"stem":"「도시별 도서관 수」를 나타낸 막대그래프예요. 서울은 대구보다 몇 관 더 많은가요? 숫자로 쓰세요.","answer":["90"],"explanation":["세로 눈금 한 칸은 10관이에요.","서울 220관, 대구 130관이에요.","220 − 130 = 90관이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["서울","부산","대구","광주","대전"],"series":[{"vals":[220,120,130,140,80]}],"step":10,"ymax":230,"title":"도시별 도서관 수","ylab":"(관)"}},{"stem":"「반별 재활용품 수」를 나타낸 막대그래프예요. 2반은 3반보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 한 칸은 5개예요.","2반 120개, 3반 115개예요.","120 − 115 = 5개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["1반","2반","3반","4반","5반"],"series":[{"vals":[45,120,115,105,65]}],"step":5,"ymax":125,"title":"반별 재활용품 수","ylab":"(개)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
