INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#2','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',2,'mc','auto','「연도별 폭염 일수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":2,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「연도별 폭염 일수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[5,9,10,17,14]}],"step":1,"ymax":18,"title":"연도별 폭염 일수","ylab":"(일)","xlab":"(년)"},"variant_rule":{"alt":[{"stem":"「시각별 운동장 기온」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[20,24,21,29,30]}],"step":1,"ymax":31,"title":"시각별 운동장 기온","ylab":"(°C)","xlab":"(시)"}},{"stem":"「월별 빌려 간 책 수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[110,90,150,140,60]}],"step":10,"ymax":160,"title":"월별 빌려 간 책 수","ylab":"(권)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#3','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'sa','auto','「좋아하는 과일별 학생 수」를 나타낸 막대그래프예요. 감은 배보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u5-C11","difficulty":3,"kind":"sa","stem":"「좋아하는 과일별 학생 수」를 나타낸 막대그래프예요. 감은 배보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["5"],"explanation":["세로 눈금 한 칸은 1명이에요.","감 15명, 배 10명이에요.","15 − 10 = 5명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","배","포도","귤","감"],"series":[{"vals":[13,10,8,4,15]}],"step":1,"ymax":16,"title":"좋아하는 과일별 학생 수","ylab":"(명)"},"variant_rule":{"alt":[{"stem":"「나라별 받은 메달 수」를 나타낸 막대그래프예요. 마는 나보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["18"],"explanation":["세로 눈금 한 칸은 2개예요.","마 26개, 나 8개예요.","26 − 8 = 18개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가","나","다","라","마"],"series":[{"vals":[34,8,32,16,26]}],"step":2,"ymax":36,"title":"나라별 받은 메달 수","ylab":"(개)"}},{"stem":"「마을별 나무 수」를 나타낸 막대그래프예요. 달빛은 별빛보다 몇 그루 더 많은가요? 숫자로 쓰세요.","answer":["50"],"explanation":["세로 눈금 한 칸은 5그루예요.","달빛 70그루, 별빛 20그루예요.","70 − 20 = 50그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["해솔","달빛","별빛","은하","꽃잎"],"series":[{"vals":[85,70,20,10,50]}],"step":5,"ymax":90,"title":"마을별 나무 수","ylab":"(그루)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#4','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'error','auto','알맞은 그래프 고르기에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C11","difficulty":3,"kind":"error","stem":"알맞은 그래프 고르기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「이어진 자료를 막대그래프로 그리면 틀린 거야.」","correct":true,"mis_target":"M4-2-u5-X18"},{"t":"민서 — 「변화를 보려면 꺾은선그래프가 좋아.」","mis":"M4-2-u5-X21"},{"t":"도윤 — 「한눈에 견주려면 막대그래프가 좋아.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「목적과 자료의 특성을 함께 생각해.」","mis":"M4-2-u5-X21"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 변화에 알맞아요.","준서의 말은 그래프를 고르는 방법과 맞지 않아요.","이어진 자료를 막대로 그려도 틀린 것은 아니고, 목적과 특성으로 골라요."],"variant_rule":{"alt":[{"stem":"알맞은 그래프 고르기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「강별 수질 오염 발생 횟수는 꺾은선그래프가 알맞아.」","correct":true,"mis_target":"M4-2-u5-X17"},{"t":"도윤 — 「한눈에 견주려면 막대그래프가 좋아.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「목적과 자료의 특성을 함께 생각해.」","mis":"M4-2-u5-X21"},{"t":"시우 — 「그림그래프도 견주기 쉬워.」","mis":"M4-2-u5-X21"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 변화에 알맞아요.","민서의 말은 그래프를 고르는 방법과 맞지 않아요.","이어진 자료를 막대로 그려도 틀린 것은 아니고, 목적과 특성으로 골라요."],"asset":null},{"stem":"알맞은 그래프 고르기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「어떤 자료든 꺾은선그래프가 가장 좋아.」","correct":true,"mis_target":"M4-2-u5-X17"},{"t":"서윤 — 「목적과 자료의 특성을 함께 생각해.」","mis":"M4-2-u5-X21"},{"t":"시우 — 「그림그래프도 견주기 쉬워.」","mis":"M4-2-u5-X21"},{"t":"은우 — 「변화를 보려면 꺾은선그래프가 좋아.」","mis":"M4-2-u5-X21"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 변화에 알맞아요.","도윤의 말은 그래프를 고르는 방법과 맞지 않아요.","이어진 자료를 막대로 그려도 틀린 것은 아니고, 목적과 특성으로 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#5','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'ox','auto','막대그래프로는 두 달 사이의 값을 짐작하기 쉬워요.',ARRAY['M4-2-u5-X18']::text[],true,'{"seq":5,"concept":"M4-2-u5-C11","difficulty":3,"kind":"ox","stem":"막대그래프로는 두 달 사이의 값을 짐작하기 쉬워요.","answer":"X","reason_options":[{"t":"막대가 이어져 있지 않아 사이 값을 짐작하기 어려워서","correct":true},{"t":"막대 끝을 이어 보면 되니까","mis":"M4-2-u5-X18"}],"mis":"M4-2-u5-X18","explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞아요.","이어진 자료를 막대그래프로 그려도 틀린 것은 아니에요 — 쓰임이 달라요.","목적과 자료의 특성을 함께 생각해 골라요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프는 시간에 따른 변화를 알아보기 쉬워요.","answer":"O","reason_options":[{"t":"선분이 기울어진 모양으로 늘어남과 줄어듦이 보여서","correct":true},{"t":"항목끼리 견주기만 좋아서","mis":"M4-2-u5-X17"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞아요.","이어진 자료를 막대그래프로 그려도 틀린 것은 아니에요 — 쓰임이 달라요.","목적과 자료의 특성을 함께 생각해 골라요."],"asset":null},{"stem":"도시별 도서관 수를 한눈에 견주려면 막대그래프가 알맞아요.","answer":"O","reason_options":[{"t":"항목끼리 크기를 견주는 자료라서","correct":true},{"t":"도시는 시간 순서라서 꺾은선그래프가 알맞아서","mis":"M4-2-u5-X17"}],"explanation":["그림·막대그래프는 견주기, 꺾은선그래프는 시간에 따른 변화에 알맞아요.","이어진 자료를 막대그래프로 그려도 틀린 것은 아니에요 — 쓰임이 달라요.","목적과 자료의 특성을 함께 생각해 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#6','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'mc','auto','채원이는 해마다의 해수면 높이를 한눈에 견주려고 해요. 어떤 그래프로 나타내는 것이 알맞을까요?',ARRAY['M4-2-u5-X17','M4-2-u5-X05','M4-2-u5-X03']::text[],true,'{"seq":6,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"채원이는 해마다의 해수면 높이를 한눈에 견주려고 해요. 어떤 그래프로 나타내는 것이 알맞을까요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선","mis":"M4-2-u5-X05"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["먼저 알고 싶은 것(목적)을 봐요.","한눈에 견주려면 막대그래프가 좋아요.","그래서 막대그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"도윤이는 해수면 높이가 어떻게 달라졌는지 알아보려고 해요. 어떤 그래프로 나타내는 것이 알맞을까요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"물결선","mis":"M4-2-u5-X05"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["먼저 알고 싶은 것(목적)을 봐요.","변화나 사이 값을 알아보려면 꺾은선그래프가 좋아요.","그래서 꺾은선그래프가 알맞아요."],"asset":null},{"stem":"지아는 강마다 수질 오염 발생 횟수가 얼마나 다른지 한눈에 견주려고 해요. 어떤 그래프로 나타내는 것이 알맞을까요?","options":[{"t":"막대그래프","correct":true},{"t":"꺾은선그래프","mis":"M4-2-u5-X17"},{"t":"물결선","mis":"M4-2-u5-X05"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["먼저 알고 싶은 것(목적)을 봐요.","한눈에 견주려면 막대그래프가 좋아요.","그래서 막대그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#7','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',3,'mc','auto','「시각별 교실 온도」를 막대그래프로 나타냈어요. 이 그래프로 알아보기 어려운 것은 어느 것인가요?',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":7,"concept":"M4-2-u5-C11","difficulty":3,"kind":"mc","stem":"「시각별 교실 온도」를 막대그래프로 나타냈어요. 이 그래프로 알아보기 어려운 것은 어느 것인가요?","options":[{"t":"조사하지 않은 두 때 사이의 값","correct":true},{"t":"시각마다의 값","mis":"M4-2-u5-X21"},{"t":"값이 가장 큰 때","mis":"M4-2-u5-X21"},{"t":"값이 가장 작은 때","mis":"M4-2-u5-X21"}],"explanation":["막대그래프로도 때마다의 값과 가장 큰·작은 때를 알 수 있어요.","하지만 막대 사이가 이어져 있지 않아 두 때 사이의 값은 짐작하기 어려워요.","두 때 사이를 짐작하려면 꺾은선그래프가 좋아요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[14,16,20,25,22]}],"step":1,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도","mode":"bar"},"variant_rule":{"alt":[{"stem":"「월별 도서관에서 빌려 간 책 수」를 막대그래프로 나타냈어요. 이 그래프로 알아보기 어려운 것은 어느 것인가요?","options":[{"t":"조사하지 않은 두 때 사이의 값","correct":true},{"t":"월마다의 값","mis":"M4-2-u5-X21"},{"t":"값이 가장 큰 때","mis":"M4-2-u5-X21"},{"t":"값이 가장 작은 때","mis":"M4-2-u5-X21"}],"explanation":["막대그래프로도 때마다의 값과 가장 큰·작은 때를 알 수 있어요.","하지만 막대 사이가 이어져 있지 않아 두 때 사이의 값은 짐작하기 어려워요.","두 때 사이를 짐작하려면 꺾은선그래프가 좋아요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[260,250,280,150,260]}],"step":10,"ymax":290,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수","mode":"bar"}},{"stem":"「연도별 태풍 발생 횟수」를 막대그래프로 나타냈어요. 이 그래프로 알아보기 어려운 것은 어느 것인가요?","options":[{"t":"조사하지 않은 두 때 사이의 값","correct":true},{"t":"연도마다의 값","mis":"M4-2-u5-X21"},{"t":"값이 가장 큰 때","mis":"M4-2-u5-X21"},{"t":"값이 가장 작은 때","mis":"M4-2-u5-X21"}],"explanation":["막대그래프로도 때마다의 값과 가장 큰·작은 때를 알 수 있어요.","하지만 막대 사이가 이어져 있지 않아 두 때 사이의 값은 짐작하기 어려워요.","두 때 사이를 짐작하려면 꺾은선그래프가 좋아요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[8,11,5,3,2]}],"step":1,"ymax":12,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수","mode":"bar"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#8','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',4,'mc','auto','서윤은 「연도별 해수면 높이」를 막대그래프로, 시우는 꺾은선그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":4,"kind":"mc","stem":"서윤은 「연도별 해수면 높이」를 막대그래프로, 시우는 꺾은선그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요. 알고 싶은 것에 따라 고른 것이에요.","correct":true},{"t":"시우만 맞아요. 이어진 자료는 꺾은선그래프로만 나타내요.","mis":"M4-2-u5-X18"},{"t":"서윤만 맞아요. 막대그래프가 언제나 더 좋아요.","mis":"M4-2-u5-X17"},{"t":"둘 다 틀렸어요. 표로만 나타내야 해요.","mis":"M4-2-u5-X17"}],"explanation":["서윤는 때마다의 값을 한눈에 견주려고 막대그래프를 골랐어요.","시우는 어떻게 달라졌는지 보려고 꺾은선그래프를 골랐어요.","같은 자료라도 알고 싶은 것이 다르면 알맞은 그래프가 달라져요 — 둘 다 맞아요."],"variant_rule":{"alt":[{"stem":"시우는 「월별 최고 온도」를 막대그래프로, 은우는 꺾은선그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요. 알고 싶은 것에 따라 고른 것이에요.","correct":true},{"t":"은우만 맞아요. 이어진 자료는 꺾은선그래프로만 나타내요.","mis":"M4-2-u5-X18"},{"t":"시우만 맞아요. 막대그래프가 언제나 더 좋아요.","mis":"M4-2-u5-X17"},{"t":"둘 다 틀렸어요. 표로만 나타내야 해요.","mis":"M4-2-u5-X17"}],"explanation":["시우는 때마다의 값을 한눈에 견주려고 막대그래프를 골랐어요.","은우는 어떻게 달라졌는지 보려고 꺾은선그래프를 골랐어요.","같은 자료라도 알고 싶은 것이 다르면 알맞은 그래프가 달라져요 — 둘 다 맞아요."],"asset":null},{"stem":"은우는 「연도별 폭염 일수」를 막대그래프로, 하랑은 꺾은선그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요. 알고 싶은 것에 따라 고른 것이에요.","correct":true},{"t":"하랑만 맞아요. 이어진 자료는 꺾은선그래프로만 나타내요.","mis":"M4-2-u5-X18"},{"t":"은우만 맞아요. 막대그래프가 언제나 더 좋아요.","mis":"M4-2-u5-X17"},{"t":"둘 다 틀렸어요. 표로만 나타내야 해요.","mis":"M4-2-u5-X17"}],"explanation":["은우는 때마다의 값을 한눈에 견주려고 막대그래프를 골랐어요.","하랑는 어떻게 달라졌는지 보려고 꺾은선그래프를 골랐어요.","같은 자료라도 알고 싶은 것이 다르면 알맞은 그래프가 달라져요 — 둘 다 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#9','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',4,'sa','auto','「좋아하는 과일별 학생 수」를 나타낸 막대그래프예요. 가장 많은 과일과 가장 적은 과일의 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C11","difficulty":4,"kind":"sa","stem":"「좋아하는 과일별 학생 수」를 나타낸 막대그래프예요. 가장 많은 과일과 가장 적은 과일의 차는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["세로 눈금 한 칸은 1명이에요.","가장 많은 것은 사과 9명, 가장 적은 것은 포도 2명이에요.","9 − 2 = 7명이에요."],"asset":{"type":"lgraph","mode":"bar","xs":["사과","배","포도","귤","감"],"series":[{"vals":[9,4,2,3,8]}],"step":1,"ymax":10,"title":"좋아하는 과일별 학생 수","ylab":"(명)"},"variant_rule":{"alt":[{"stem":"「나라별 받은 메달 수」를 나타낸 막대그래프예요. 가장 많은 나라와 가장 적은 나라의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["세로 눈금 한 칸은 2개예요.","가장 많은 것은 라 36개, 가장 적은 것은 가 8개예요.","36 − 8 = 28개예요."],"asset":{"type":"lgraph","mode":"bar","xs":["가","나","다","라","마"],"series":[{"vals":[8,20,10,36,28]}],"step":2,"ymax":38,"title":"나라별 받은 메달 수","ylab":"(개)"}},{"stem":"「마을별 나무 수」를 나타낸 막대그래프예요. 가장 많은 마을과 가장 적은 마을의 차는 몇 그루인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["세로 눈금 한 칸은 5그루예요.","가장 많은 것은 별빛 65그루, 가장 적은 것은 해솔 30그루예요.","65 − 30 = 35그루예요."],"asset":{"type":"lgraph","mode":"bar","xs":["해솔","달빛","별빛","은하","꽃잎"],"series":[{"vals":[30,50,65,35,40]}],"step":5,"ymax":70,"title":"마을별 나무 수","ylab":"(그루)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L07_challenge#10','math',4,2,'u5','L07','g4_2_math_u5_L07_challenge','lesson_challenge','M4-2-u5-C11',4,'essay','teacher','6월부터 10월까지의 월별 최고 온도를 막대그래프로 나타낸 친구에게 「이어진 자료니까 막대그래프로 그리면 틀린 거야.」라고 말한 친구가 있어요. 이 말이 맞는지 쓰고, 막대그래프와 꺾은선그래프가 각각 무엇을 알아보기에 좋은지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C11","difficulty":4,"kind":"essay","stem":"6월부터 10월까지의 월별 최고 온도를 막대그래프로 나타낸 친구에게 「이어진 자료니까 막대그래프로 그리면 틀린 거야.」라고 말한 친구가 있어요. 이 말이 맞는지 쓰고, 막대그래프와 꺾은선그래프가 각각 무엇을 알아보기에 좋은지 써 보세요.","answer_guide":{"answer":"예: 이 말은 틀렸다. 이어진 자료를 막대그래프로 나타내도 틀린 것은 아니다. 막대그래프는 달마다의 최고 온도를 한눈에 견주기 좋고, 꺾은선그래프는 온도가 어떻게 달라져 왔는지와 두 달 사이의 온도를 짐작하기 좋다. 그래서 알고 싶은 것에 따라 골라야 한다.","scoring_points":["막대그래프로 그려도 틀리지 않았다고 썼는가","막대그래프는 크기를 견주기 좋다고 썼는가","꺾은선그래프는 변화·사이 값에 좋다고 썼는가"]},"explanation":["이어진 자료를 막대로 그려도 틀린 것은 아니에요.","막대그래프 — 달마다의 크기 견주기.","꺾은선그래프 — 변화의 흐름과 사이 값 짐작."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_basic#1','math',4,2,'u5','L08','g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'mc','auto','두 자료를 하나의 꺾은선그래프에 나타낼 때 꼭 해야 하는 것은 무엇인가요?',ARRAY['M4-2-u5-X19']::text[],true,'{"seq":1,"concept":"M4-2-u5-C12","difficulty":1,"kind":"mc","stem":"두 자료를 하나의 꺾은선그래프에 나타낼 때 꼭 해야 하는 것은 무엇인가요?","options":[{"t":"선의 색을 다르게 하고 어느 선이 무엇인지 이름표를 붙여요.","correct":true},{"t":"두 자료를 더해서 하나로 만들어요.","mis":"M4-2-u5-X19"},{"t":"가로 눈금을 두 줄로 그려요.","mis":"M4-2-u5-X19"},{"t":"세로 눈금을 두 개 그려요.","mis":"M4-2-u5-X19"}],"explanation":["두 자료를 한 그래프에 나타낼 때는 같은 가로 눈금 위에 두 값을 찍어요.","선의 색(모양)을 다르게 해 각각 잇고, 이름표를 붙여요.","그러면 두 자료의 변화를 한 판에서 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"두 자료를 하나의 그래프에 나타내면 좋은 점은 무엇인가요?","options":[{"t":"두 자료의 변화를 한 판에서 견줄 수 있어요.","correct":true},{"t":"자료의 값이 커져요.","mis":"M4-2-u5-X05"},{"t":"눈금을 읽지 않아도 돼요.","mis":"M4-2-u5-X02"},{"t":"물결선을 쓸 수 없게 돼요.","mis":"M4-2-u5-X20"}],"explanation":["두 자료를 한 그래프에 나타낼 때는 같은 가로 눈금 위에 두 값을 찍어요.","선의 색(모양)을 다르게 해 각각 잇고, 이름표를 붙여요.","그러면 두 자료의 변화를 한 판에서 견줄 수 있어요."],"asset":null},{"stem":"두 자료를 한 그래프에 나타낼 때 같은 연도의 두 값은 어디에 찍나요?","options":[{"t":"같은 가로 눈금 위에 찍어요.","correct":true},{"t":"서로 다른 그래프에 따로 찍어요.","mis":"M4-2-u5-X19"},{"t":"한 값은 가로에, 한 값은 세로에 찍어요.","mis":"M4-2-u5-X01"},{"t":"두 값을 더한 자리에 하나만 찍어요.","mis":"M4-2-u5-X19"}],"explanation":["두 자료를 한 그래프에 나타낼 때는 같은 가로 눈금 위에 두 값을 찍어요.","선의 색(모양)을 다르게 해 각각 잇고, 이름표를 붙여요.","그러면 두 자료의 변화를 한 판에서 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_basic#2','math',4,2,'u5','L08','g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'sa','auto','2021년의 유소년층과 노년층의 인구수 차는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u5-C12","difficulty":1,"kind":"sa","stem":"2021년의 유소년층과 노년층의 인구수 차는 몇만 명인가요? 숫자로 쓰세요.","answer":["280"],"explanation":["이름표로 두 선을 먼저 가려요.","2021년의 유소년층 600만 명, 노년층 880만 명이에요.","880 − 600 = 280만 명이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,670,650,600,570]},{"name":"노년층","vals":[730,790,840,880,910]}],"step":10,"ymax":920,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true},"variant_rule":{"alt":[{"stem":"3월의 서울과 부산의 낮 최고 기온 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["이름표로 두 선을 먼저 가려요.","3월의 서울 10 °C, 부산 9 °C예요.","10 − 9 = 1 °C예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"서울","vals":[10,12,16,26,27]},{"name":"부산","vals":[9,10,12,16,21]}],"step":1,"ymax":28,"title":"월별 낮 최고 기온","ylab":"(°C)","xlab":"(월)"}},{"stem":"6월의 남학생과 여학생의 도서관 이용자 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이름표로 두 선을 먼저 가려요.","6월의 남학생 130명, 여학생 230명이에요.","230 − 130 = 100명이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[90,50,70,130,210]},{"name":"여학생","vals":[260,170,180,230,250]}],"step":10,"ymax":270,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_basic#3','math',4,2,'u5','L08','g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',1,'mc','auto','가 식물의 키는 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10','M4-2-u5-X13','M4-2-u5-X19']::text[],true,'{"seq":3,"concept":"M4-2-u5-C12","difficulty":1,"kind":"mc","stem":"가 식물의 키는 어떻게 변하고 있나요?","options":[{"t":"점점 늘어나고 있어요.","correct":true},{"t":"점점 줄어들고 있어요.","mis":"M4-2-u5-X10"},{"t":"변하지 않고 있어요.","mis":"M4-2-u5-X13"},{"t":"늘었다 줄었다 하고 있어요.","mis":"M4-2-u5-X19"}],"explanation":["이름표로 가 식물의 선을 찾아요.","그 선은 처음부터 끝까지 오른쪽 위로 올라가요.","가 식물의 키는 점점 늘어나고 있어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[4,8,16,34,36]},{"name":"나 식물","vals":[12,24,34,36,40]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"서아의 줄넘기 기록은 어떻게 변하고 있나요?","options":[{"t":"점점 늘어나고 있어요.","correct":true},{"t":"점점 줄어들고 있어요.","mis":"M4-2-u5-X10"},{"t":"변하지 않고 있어요.","mis":"M4-2-u5-X13"},{"t":"늘었다 줄었다 하고 있어요.","mis":"M4-2-u5-X19"}],"explanation":["이름표로 서아의 선을 찾아요.","그 선은 처음부터 끝까지 오른쪽 위로 올라가요.","서아의 줄넘기 기록은 점점 늘어나고 있어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[30,35,45,80,120]},{"name":"서아","vals":[55,80,120,130,135]}],"step":5,"ymax":140,"title":"월별 줄넘기 기록","ylab":"(회)","xlab":"(월)"}},{"stem":"하준의 줄넘기 기록은 어떻게 변하고 있나요?","options":[{"t":"점점 늘어나고 있어요.","correct":true},{"t":"점점 줄어들고 있어요.","mis":"M4-2-u5-X10"},{"t":"변하지 않고 있어요.","mis":"M4-2-u5-X13"},{"t":"늘었다 줄었다 하고 있어요.","mis":"M4-2-u5-X19"}],"explanation":["이름표로 하준의 선을 찾아요.","그 선은 처음부터 끝까지 오른쪽 위로 올라가요.","하준의 줄넘기 기록은 점점 늘어나고 있어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[30,50,80,90,125]},{"name":"서아","vals":[60,70,120,135,140]}],"step":5,"ymax":145,"title":"월별 줄넘기 기록","ylab":"(회