explanation":["같은 때의 두 점 사이가 어떻게 변하는지 봐요.","두 선이 점점 멀어지고 있어요.","두 값의 차가 점점 커질 것이라고 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[670,660,610,590,560]},{"name":"노년층","vals":[810,840,890,900,920]}],"step":10,"ymax":930,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_basic#8','math',4,2,'u5','L08','g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'sa','auto','우유의 판매량은 3월부터 7월까지 몇 개 줄어들었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"우유의 판매량은 3월부터 7월까지 몇 개 줄어들었나요? 숫자로 쓰세요.","answer":["75"],"explanation":["이름표로 우유의 선을 찾아요.","3월 130개, 7월 55개예요.","130 − 55 = 75개 줄어들었어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[130,100,135,110,55]},{"name":"주스","vals":[85,80,35,50,20]}],"step":5,"ymax":140,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"서아의 줄넘기 기록은 3월부터 7월까지 몇 회 늘어났나요? 숫자로 쓰세요.","answer":["75"],"explanation":["이름표로 서아의 선을 찾아요.","3월 65회, 7월 140회예요.","140 − 65 = 75회 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[45,60,65,90,130]},{"name":"서아","vals":[65,85,95,135,140]}],"step":5,"ymax":145,"title":"월별 줄넘기 기록","ylab":"(회)","xlab":"(월)"}},{"stem":"유소년층의 인구수는 2018년부터 2022년까지 몇만 명 줄어들었나요? 숫자로 쓰세요.","answer":["120"],"explanation":["이름표로 유소년층의 선을 찾아요.","2018년 680만 명, 2022년 560만 명이에요.","680 − 560 = 120만 명 줄어들었어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,630,590,580,560]},{"name":"노년층","vals":[750,800,820,830,900]}],"step":10,"ymax":910,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_basic#9','math',4,2,'u5','L08','g4_2_math_u5_L08_basic','lesson_basic','M4-2-u5-C12',2,'ox','auto','두 자료를 나타낼 때 물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.',ARRAY['M4-2-u5-X20']::text[],true,'{"seq":9,"concept":"M4-2-u5-C12","difficulty":2,"kind":"ox","stem":"두 자료를 나타낼 때 물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","answer":"O","reason_options":[{"t":"물결선은 필요 없는 부분을 줄이는 방법일 뿐이라서","correct":true},{"t":"물결선을 쓴 그래프만 맞아서","mis":"M4-2-u5-X20"}],"mis":"M4-2-u5-X20","explanation":["물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","물결선을 쓰면 변화가 더 뚜렷하고, 쓰지 않으면 크기 자체를 견주기 좋아요.","두 자료는 선의 색과 이름표로 구별해요."],"variant_rule":{"alt":[{"stem":"물결선을 쓰지 않은 그래프는 틀린 그래프예요.","answer":"X","reason_options":[{"t":"0부터 그려도 값은 바르게 나타나서","correct":true},{"t":"물결선이 없으면 값을 찍을 수 없어서","mis":"M4-2-u5-X20"}],"explanation":["물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","물결선을 쓰면 변화가 더 뚜렷하고, 쓰지 않으면 크기 자체를 견주기 좋아요.","두 자료는 선의 색과 이름표로 구별해요."],"asset":null},{"stem":"물결선을 쓴 쪽이 달라지는 모습이 더 뚜렷하게 보여요.","answer":"O","reason_options":[{"t":"세로 눈금 한 칸을 작게 잡을 수 있어서","correct":true},{"t":"두 그래프는 언제나 똑같이 보여서","mis":"M4-2-u5-X08"}],"explanation":["물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","물결선을 쓰면 변화가 더 뚜렷하고, 쓰지 않으면 크기 자체를 견주기 좋아요.","두 자료는 선의 색과 이름표로 구별해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
