INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#4','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'error','auto','두 자료를 나타낸 꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u5-X20','M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C12","difficulty":3,"kind":"error","stem":"두 자료를 나타낸 꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「물결선을 쓰지 않은 그래프는 틀린 거야.」","correct":true,"mis_target":"M4-2-u5-X20"},{"t":"도윤 — 「같은 때 자리에 두 값을 찍어.」","mis":"M4-2-u5-X21"},{"t":"서윤 — 「선의 색을 다르게 해.」","mis":"M4-2-u5-X21"},{"t":"시우 — 「물결선을 쓰면 변화가 더 뚜렷해.」","mis":"M4-2-u5-X21"}],"explanation":["두 자료는 같은 가로 눈금 위에 찍고, 색과 이름표로 구별해요.","민서의 말은 맞지 않아요.","물결선은 있어도 없어도 맞고, 두 선이 멀어지면 차가 커지는 거예요."],"variant_rule":{"alt":[{"stem":"두 자료를 나타낸 꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「두 선의 이름표는 붙이지 않아도 돼.」","correct":true,"mis_target":"M4-2-u5-X19"},{"t":"서윤 — 「선의 색을 다르게 해.」","mis":"M4-2-u5-X21"},{"t":"시우 — 「물결선을 쓰면 변화가 더 뚜렷해.」","mis":"M4-2-u5-X21"},{"t":"은우 — 「두 선 사이가 벌어지면 차가 커지는 거야.」","mis":"M4-2-u5-X21"}],"explanation":["두 자료는 같은 가로 눈금 위에 찍고, 색과 이름표로 구별해요.","도윤의 말은 맞지 않아요.","물결선은 있어도 없어도 맞고, 두 선이 멀어지면 차가 커지는 거예요."],"asset":null},{"stem":"두 자료를 나타낸 꺾은선그래프에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「두 선이 멀어지면 두 값의 차가 작아지는 거야.」","correct":true,"mis_target":"M4-2-u5-X19"},{"t":"시우 — 「물결선을 쓰면 변화가 더 뚜렷해.」","mis":"M4-2-u5-X21"},{"t":"은우 — 「두 선 사이가 벌어지면 차가 커지는 거야.」","mis":"M4-2-u5-X21"},{"t":"하랑 — 「같은 때 자리에 두 값을 찍어.」","mis":"M4-2-u5-X21"}],"explanation":["두 자료는 같은 가로 눈금 위에 찍고, 색과 이름표로 구별해요.","서윤의 말은 맞지 않아요.","물결선은 있어도 없어도 맞고, 두 선이 멀어지면 차가 커지는 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#5','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'mc','auto','여학생의 도서관 이용자 수가 처음으로 남학생의 도서관 이용자 수보다 많아진 때는 언제인가요?',ARRAY['M4-2-u5-X19','M4-2-u5-X21']::text[],true,'{"seq":5,"concept":"M4-2-u5-C12","difficulty":3,"kind":"mc","stem":"여학생의 도서관 이용자 수가 처음으로 남학생의 도서관 이용자 수보다 많아진 때는 언제인가요?","options":[{"t":"7월","correct":true},{"t":"6월","mis":"M4-2-u5-X19"},{"t":"3월","mis":"M4-2-u5-X21"},{"t":"4월","mis":"M4-2-u5-X21"}],"explanation":["이름표로 두 선을 가려요.","6월까지는 남학생의 선이 위에 있다가 7월에 두 선의 위아래가 바뀌어요.","처음으로 많아진 때는 7월이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[160,190,130,170,70]},{"name":"여학생","vals":[150,130,90,140,230]}],"step":10,"ymax":240,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"가 식물의 키가 처음으로 나 식물의 키보다 많아진 때는 언제인가요?","options":[{"t":"8월","correct":true},{"t":"7월","mis":"M4-2-u5-X19"},{"t":"4월","mis":"M4-2-u5-X21"},{"t":"5월","mis":"M4-2-u5-X21"}],"explanation":["이름표로 두 선을 가려요.","7월까지는 나 식물의 선이 위에 있다가 8월에 두 선의 위아래가 바뀌어요.","처음으로 많아진 때는 8월이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[6,12,14,24,40]},{"name":"나 식물","vals":[12,22,30,32,38]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"}},{"stem":"우유의 판매량이 처음으로 주스의 판매량보다 많아진 때는 언제인가요?","options":[{"t":"7월","correct":true},{"t":"6월","mis":"M4-2-u5-X19"},{"t":"3월","mis":"M4-2-u5-X21"},{"t":"4월","mis":"M4-2-u5-X21"}],"explanation":["이름표로 두 선을 가려요.","6월까지는 주스의 선이 위에 있다가 7월에 두 선의 위아래가 바뀌어요.","처음으로 많아진 때는 7월이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[75,65,30,80,125]},{"name":"주스","vals":[145,125,95,100,50]}],"step":5,"ymax":150,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#6','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'sa','auto','노년층의 인구수가 전년도와 비교하여 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u5-C12","difficulty":3,"kind":"sa","stem":"노년층의 인구수가 전년도와 비교하여 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["이름표로 노년층의 선만 봐요.","변화: +40, +20, +30, +70.","가장 많이 늘어난 것은 2021년과 2022년 사이로 70만 명이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,650,590,570,560]},{"name":"노년층","vals":[730,770,790,820,890]}],"step":10,"ymax":900,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true},"variant_rule":{"alt":[{"stem":"우유의 판매량이 전월과 비교하여 가장 많이 늘어난 정도는 몇 개인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["이름표로 우유의 선만 봐요.","변화: −25, +65, −10, +15.","가장 많이 늘어난 것은 4월과 5월 사이로 65개예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[85,60,125,115,130]},{"name":"주스","vals":[60,50,70,35,85]}],"step":5,"ymax":135,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}},{"stem":"여학생의 도서관 이용자 수가 전월과 비교하여 가장 많이 늘어난 정도는 몇 명인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["이름표로 여학생의 선만 봐요.","변화: −20, −100, +80, −10.","가장 많이 늘어난 것은 5월과 6월 사이로 80명이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[200,120,50,70,80]},{"name":"여학생","vals":[240,220,120,200,190]}],"step":10,"ymax":250,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#7','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',3,'ox','auto','두 선이 서로 멀어지고 있으면 두 값의 차가 점점 커지고 있는 것이에요.',ARRAY['M4-2-u5-X19']::text[],true,'{"seq":7,"concept":"M4-2-u5-C12","difficulty":3,"kind":"ox","stem":"두 선이 서로 멀어지고 있으면 두 값의 차가 점점 커지고 있는 것이에요.","answer":"O","reason_options":[{"t":"같은 때의 두 점 사이가 벌어지고 있어서","correct":true},{"t":"두 선이 멀어지면 차가 작아져서","mis":"M4-2-u5-X19"}],"mis":"M4-2-u5-X19","explanation":["물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","물결선을 쓰면 변화가 더 뚜렷하고, 쓰지 않으면 크기 자체를 견주기 좋아요.","두 자료는 선의 색과 이름표로 구별해요."],"variant_rule":{"alt":[{"stem":"두 자료를 한 그래프에 그릴 때는 이름표를 붙이지 않아도 돼요.","answer":"X","reason_options":[{"t":"어느 선이 어떤 자료인지 알 수 없어서","correct":true},{"t":"선의 모양만 보면 알 수 있어서","mis":"M4-2-u5-X19"}],"explanation":["물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","물결선을 쓰면 변화가 더 뚜렷하고, 쓰지 않으면 크기 자체를 견주기 좋아요.","두 자료는 선의 색과 이름표로 구별해요."],"asset":null},{"stem":"물결선을 쓰지 않은 그래프는 두 자료의 크기 자체를 견주기 좋아요.","answer":"O","reason_options":[{"t":"0부터 그려 막대 길이처럼 크기가 그대로 보여서","correct":true},{"t":"물결선이 없으면 크기를 알 수 없어서","mis":"M4-2-u5-X20"}],"explanation":["물결선을 쓴 그래프와 쓰지 않은 그래프는 둘 다 맞아요.","물결선을 쓰면 변화가 더 뚜렷하고, 쓰지 않으면 크기 자체를 견주기 좋아요.","두 자료는 선의 색과 이름표로 구별해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#8','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',4,'sa','auto','유소년층과 노년층의 인구수 차는 2018년보다 2022년에 몇만 명 더 커졌나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u5-C12","difficulty":4,"kind":"sa","stem":"유소년층과 노년층의 인구수 차는 2018년보다 2022년에 몇만 명 더 커졌나요? 숫자로 쓰세요.","answer":["300"],"explanation":["2018년의 차: 730 − 680 = 50.","2022년의 차: 920 − 570 = 350.","350 − 50 = 300만 명 더 커졌어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,670,650,620,570]},{"name":"노년층","vals":[730,740,760,820,920]}],"step":10,"ymax":930,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true},"variant_rule":{"alt":[{"stem":"우유와 주스의 판매량 차는 3월보다 7월에 몇 개 더 커졌나요? 숫자로 쓰세요.","answer":["50"],"explanation":["3월의 차: 105 − 90 = 15.","7월의 차: 100 − 35 = 65.","65 − 15 = 50개 더 커졌어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[105,85,145,115,100]},{"name":"주스","vals":[90,60,110,75,35]}],"step":5,"ymax":150,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}},{"stem":"이번에는 다른 그림이에요. 유소년층과 노년층의 인구수 차는 2018년보다 2022년에 몇만 명 더 커졌나요? 숫자로 쓰세요.","answer":["260"],"explanation":["2018년의 차: 720 − 680 = 40.","2022년의 차: 870 − 570 = 300.","300 − 40 = 260만 명 더 커졌어요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,670,620,600,570]},{"name":"노년층","vals":[720,730,780,840,870]}],"step":10,"ymax":880,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#9','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',4,'sa','auto','전월과 비교하여 우유와 주스의 판매량이 모두 늘어난 때는 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C12","difficulty":4,"kind":"sa","stem":"전월과 비교하여 우유와 주스의 판매량이 모두 늘어난 때는 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["우유의 변화: −60, −25, +35, +55.","주스의 변화: −25, −65, +60, +45.","두 선이 모두 오른쪽 위로 올라간 때: 6월, 7월 — 2번이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[110,50,25,60,115]},{"name":"주스","vals":[135,110,45,105,150]}],"step":5,"ymax":155,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"전월과 비교하여 남학생과 여학생의 도서관 이용자 수가 모두 늘어난 때는 몇 번인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["남학생의 변화: −10, +20, −80, +50.","여학생의 변화: +10, −70, +20, +80.","두 선이 모두 오른쪽 위로 올라간 때: 7월 — 1번이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[210,200,220,140,190]},{"name":"여학생","vals":[130,140,70,90,170]}],"step":10,"ymax":230,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"}},{"stem":"전월과 비교하여 남학생과 여학생의 도서관 이용자 수가 모두 늘어난 때는 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["남학생의 변화: +10, −100, +40, +90.","여학생의 변화: +90, −30, −40, +50.","두 선이 모두 오른쪽 위로 올라간 때: 4월, 7월 — 2번이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[140,150,50,90,180]},{"name":"여학생","vals":[170,260,230,190,240]}],"step":10,"ymax":270,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_L08_challenge#10','math',4,2,'u5','L08','g4_2_math_u5_L08_challenge','lesson_challenge','M4-2-u5-C12',4,'essay','teacher','유소년층과 노년층 인구수를 하나의 꺾은선그래프에 나타내려고 해요. 해결 1은 물결선을 넣고 세로 눈금 한 칸을 50만 명으로, 해결 2는 물결선 없이 0부터 한 칸을 100만 명으로 그렸어요. 두 그래프가 모두 맞는지 쓰고, 각각 어떤 점이 좋은지 써 보세요. 그리고 두 선이 점점 멀어지고 있다면 앞으로 어떻게 될지 짐작해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u5-C12","difficulty":4,"kind":"essay","stem":"유소년층과 노년층 인구수를 하나의 꺾은선그래프에 나타내려고 해요. 해결 1은 물결선을 넣고 세로 눈금 한 칸을 50만 명으로, 해결 2는 물결선 없이 0부터 한 칸을 100만 명으로 그렸어요. 두 그래프가 모두 맞는지 쓰고, 각각 어떤 점이 좋은지 써 보세요. 그리고 두 선이 점점 멀어지고 있다면 앞으로 어떻게 될지 짐작해 보세요.","answer_guide":{"answer":"예: 두 그래프 모두 맞다. 해결 1은 물결선으로 필요 없는 부분을 줄여 달라지는 모습이 더 뚜렷하게 보이고, 해결 2는 0부터 그려서 두 자료의 크기 자체를 견주기 좋다. 두 선이 점점 멀어지고 있으므로 앞으로 두 인구수의 차가 점점 더 커질 것이라고 짐작할 수 있다.","scoring_points":["두 그래프 모두 맞다고 썼는가","물결선 쪽은 변화가 뚜렷하고, 0부터 그린 쪽은 크기를 견주기 좋다고 썼는가","두 선이 멀어지니 차가 커질 것이라고 짐작했는가"]},"explanation":["물결선이 있든 없든 값은 바르게 나타나요 — 둘 다 맞아요.","물결선 쪽은 변화가 뚜렷하고, 0부터 그린 쪽은 크기 자체를 견주기 좋아요.","두 선이 멀어지면 차가 커질 것이라고 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#1','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C1',1,'mc','auto','꺾은선그래프로 나타내기에 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"꺾은선그래프로 나타내기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"달마다 잰 나무의 키","correct":true},{"t":"우리 반 학생들이 좋아하는 과일","mis":"M4-2-u5-X15"},{"t":"도시별 도서관 수","mis":"M4-2-u5-X15"},{"t":"반별 안경 쓴 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프에서 찍은 점들은 무엇으로 잇나요?","options":[{"t":"선분","correct":true},{"t":"곡선","mis":"M4-2-u5-X06"},{"t":"막대","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null},{"stem":"꺾은선그래프가 막대그래프보다 알아보기 쉬운 것은 어느 것인가요?","options":[{"t":"시간에 따라 달라지는 모습","correct":true},{"t":"자료를 조사한 사람","mis":"M4-2-u5-X03"},{"t":"세로 눈금 한 칸의 크기","mis":"M4-2-u5-X02"},{"t":"자료를 모은 곳","mis":"M4-2-u5-X16"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#2','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C2',1,'mc','auto','아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 도서관에서 빌려 간 책 수","correct":true},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 도서관에서 빌려 간 책 수","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 도서관에서 빌려 간 책 수를 권 단위로 나타냈어요.","가로: 월, 세로: 도서관에서 빌려 간 책 수예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[80,180,190,220,240]}],"step":10,"ymax":250,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 자외선 지수 매우 높음 일수","correct":true},{"t":"가로: 자외선 지수 매우 높음 일수, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 자외선 지수 매우 높음 일수, 세로: 자외선 지수 매우 높음 일수","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 자외선 지수 매우 높음 일수를 일 단위로 나타냈어요.","가로: 월, 세로: 자외선 지수 매우 높음 일수예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[11,15,20,13,15]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 운동장의 기온","correct":true},{"t":"가로: 운동장의 기온, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 운동장의 기온, 세로: 운동장의 기온","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각, 세로에는 운동장의 기온을 °C 단위로 나타냈어요.","가로: 시각, 세로: 운동장의 기온이에요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,16,22,30,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#3','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C3',1,'mc','auto','물결선을 넣고 세로 눈금 한 칸을 작게 하면 그래프가 어떻게 달라지나요?',ARRAY['M4-2-u5-X05','M4-2-u5-X08']::text[],true,'{"seq":3,"concept":"M4-2-u5-C3","difficulty":1,"kind":"mc","stem":"물결선을 넣고 세로 눈금 한 칸을 작게 하면 그래프가 어떻게 달라지나요?","options":[{"t":"변화하는 모습이 더 뚜렷하게 보여요.","correct":true},{"t":"자료의 값이 달라져요.","mis":"M4-2-u5-X05"},{"t":"변화하는 모습이 덜 보여요.","mis":"M4-2-u5-X08"},{"t":"가로 눈금이 사라져요.","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"variant_rule":{"alt":[{"stem":"물결선을 쓴 꺾은선그래프에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"물결선은 필요 없는 아랫부분을 줄인 것이에요.","correct":true},{"t":"물결선 아래의 값은 모두 0이에요.","mis":"M4-2-u5-X05"},{"t":"물결선을 쓰면 값이 바뀌어요.","mis":"M4-2-u5-X05"},{"t":"물결선은 자료 사이 아무 곳에나 넣어요.","mis":"M4-2-u5-X09"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null},{"stem":"온실 안의 온도처럼 값들이 서로 가까운 자료를 그릴 때 알맞은 방법은 어느 것인가요?","options":[{"t":"물결선을 넣고 세로 눈금 한 칸을 작게 해요.","correct":true},{"t":"0부터 그리고 세로 눈금 한 칸을 크게 해요.","mis":"M4-2-u5-X08"},{"t":"점을 곡선으로 이어요.","mis":"M4-2-u5-X06"},{"t":"가로와 세로를 바꿔요.","mis":"M4-2-u5-X01"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#4','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C4',1,'mc','auto','꺾은선그래프로 나타내는 다섯 걸음 가운데 맨 처음에 하는 일은 무엇인가요?',ARRAY['M4-2-u5-X21']::text[],true,'{"seq":4,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"꺾은선그래프로 나타내는 다섯 걸음 가운데 맨 처음에 하는 일은 무엇인가요?","options":[{"t":"알맞은 제목을 써요.","correct":true},{"t":"점을 찍어요.","mis":"M4-2-u5-X21"},{"t":"점을 선분으로 이어요.","mis":"M4-2-u5-X21"},{"t":"세로 눈금 한 칸의 크기를 정해요.","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"가로 눈금과 세로 눈금이 만나는 곳에는 무엇을 하나요?","options":[{"t":"점을 찍어요.","correct":true},{"t":"막대를 그려요.","mis":"M4-2-u5-X03"},{"t":"물결선을 넣어요.","mis":"M4-2-u5-X05"},{"t":"그림을 붙여요.","mis":"M4-2-u5-X03"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null},{"stem":"점을 이을 때 지켜야 할 것은 무엇인가요?","options":[{"t":"가로 눈금의 순서대로 선분으로 이어요.","correct":true},{"t":"큰 값부터 차례로 이어요.","mis":"M4-2-u5-X06"},{"t":"곡선으로 부드럽게 이어요.","mis":"M4-2-u5-X06"},{"t":"이웃하지 않은 점끼리 이어요.","mis":"M4-2-u5-X06"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#5','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C5',1,'sa','auto','표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["26"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 26 °C예요.","그래서 세로 눈금은 적어도 26 °C까지 나타내요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시","14시"],"counts":[17,22,16,20,19,26],"vh":"교실 온도","unit":"°C","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["220"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 220권이에요.","그래서 세로 눈금은 적어도 220권까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[40,110,220,180,50],"vh":"도서관에서 빌려 간 책 수","unit":"권","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 cm까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["130"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 130 cm예요.","그래서 세로 눈금은 적어도 130 cm까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월","9월"],"counts":[20,35,55,90,100,130],"vh":"해바라기의 키","unit":"cm","title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#6','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C6',1,'mc','auto','어느 도시의 인구수는 34만 명부터 48만 명까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"어느 도시의 인구수는 34만 명부터 48만 명까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 34만 명 사이","correct":true},{"t":"34만 명과 39만 명 사이","mis":"M4-2-u5-X09"},{"t":"39만 명과 48만 명 사이","mis":"M4-2-u5-X09"},{"t":"48만 명 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 34만 명이에요.","그래서 물결선은 0과 34만 명 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"우유 생산량은 190만 톤부터 209만 톤까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 190만 톤 사이","correct":true},{"t":"190만 톤과 199만 톤 사이","mis":"M4-2-u5-X09"},{"t":"199만 톤과 209만 톤 사이","mis":"M4-2-u5-X09"},{"t":"209만 톤 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 190만 톤이에요.","그래서 물결선은 0과 190만 톤 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"1인당 하루 물 사용량은 278 L부터 297 L까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 278 L 사이","correct":true},{"t":"278 L와 292 L 사이","mis":"M4-2-u5-X09"},{"t":"292 L와 297 L 사이","mis":"M4-2-u5-X09"},{"t":"297 L 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 278 L예요.","그래서 물결선은 0과 278 L 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#7','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',1,'mc','auto','폭염 일수는 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":7,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"폭염 일수는 어떻게 변하고 있나요?","options":[{"t":"2018년까지 줄어들었고 2018년부터는 늘어났어요.","correct":true},{"t":"2017년부터 2021년까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"2017년부터 2021년까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"2018년까지 늘어났고 2018년부터는 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 2018년까지 내려가다가 그 뒤로 올라가요.","2018년까지 줄어들었고 2018년부터는 늘어났어요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[14,4,5,11,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"},"variant_rule":{"alt":[{"stem":"자외선 지수 매우 높음 일수는 어떻게 변하고 있나요?","options":[{"t":"4월부터 9월까지 계속 줄어들었어요.","correct":true},{"t":"4월부터 9월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"7월까지 늘어났고 7월부터는 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"7월까지 줄어들었고 7월부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 오른쪽 아래로만 내려가요.","4월부터 9월까지 계속 줄어들었어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[24,17,11,10,7,2]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"교실 온도는 어떻게 변하고 있나요?","options":[{"t":"10시까지 늘어났고 10시부터는 줄어들었어요.","correct":true},{"t":"9시부터 13시까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"9시부터 13시까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"10시까지 줄어들었고 10시부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 10시까지 올라가다가 그 뒤로 내려가요.","10시까지 늘어났고 10시부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[23,26,21,20,16]}],"step":1,"ymax":27,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#8','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C11',1,'mc','auto','월별 기온이 어떻게 변했는지 알아보기에 알맞은 그래프는 어느 것인가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],true,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"월별 기온이 어떻게 변했는지 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"연도별 유적지 관람객 수가 어떻게 달라졌는지 알아보기 쉽게 나타내려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null},{"stem":"하루 동안 시각별 교실 온도가 어떻게 변했는지 알아보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
