INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#10','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C3',2,'mc','auto','9월에는 조사하지 않았어요. 9월의 선인장 줄기의 길이는 약 몇 cm였을까요?',ARRAY['M4-2-u5-X04']::text[],true,'{"seq":10,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"9월에는 조사하지 않았어요. 9월의 선인장 줄기의 길이는 약 몇 cm였을까요?","options":[{"t":"약 36 cm","correct":true},{"t":"약 32 cm","mis":"M4-2-u5-X04"},{"t":"약 40 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["8월과 10월의 두 점을 이은 선분을 봐요.","9월 위의 선분은 32 cm와 40 cm의 한가운데쯤을 지나요.","그래서 약 36 cm였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[8,18,32,null,40]}],"step":2,"ymax":42,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"},"variant_rule":{"alt":[{"stem":"6월에는 조사하지 않았어요. 6월의 줄넘기 기록은 약 몇 회였을까요?","options":[{"t":"약 75회","correct":true},{"t":"약 70회","mis":"M4-2-u5-X04"},{"t":"약 80회","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["5월과 7월의 두 점을 이은 선분을 봐요.","6월 위의 선분은 70회와 80회의 한가운데쯤을 지나요.","그래서 약 75회였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[25,90,70,null,80]}],"step":5,"ymax":95,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"6월에는 조사하지 않았어요. 6월의 해바라기의 키는 약 몇 cm였을까요?","options":[{"t":"약 55 cm","correct":true},{"t":"약 30 cm","mis":"M4-2-u5-X04"},{"t":"약 80 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["5월과 7월의 두 점을 이은 선분을 봐요.","6월 위의 선분은 30 cm와 80 cm의 한가운데쯤을 지나요.","그래서 약 55 cm였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[20,30,null,80,85]}],"step":5,"ymax":90,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#11','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C4',2,'mc','auto','아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07']::text[],true,'{"seq":11,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점만 찍고 선분으로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[50,60,105,85,80]}],"step":5,"ymax":110,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록","dots":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 순서대로 잇지 않았어요.","correct":true},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 순서대로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[23,25,15,22,18]}],"step":1,"ymax":26,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수","order":[0,2,1,3,4]}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 선분이 아니라 곡선으로 이었어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[8,12,20,30,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온","curve":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#12','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C6',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 2019년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 2019년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.","answer":["530"],"explanation":["물결선 바로 위 세로 눈금은 400이고, 한 칸은 10가구예요.","2019년의 점은 400에서 13칸 위에 있어요.","400 + 130 = 530 — 530가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[500,480,530,560,450]}],"step":10,"ymax":570,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 2021년의 1인당 하루 물 사용량은 몇 L인가요? 숫자로 쓰세요.","answer":["301"],"explanation":["물결선 바로 위 세로 눈금은 275이고, 한 칸은 1 L예요.","2021년의 점은 275에서 26칸 위에 있어요.","275 + 26 = 301 — 301 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[280,285,289,298,299,301]}],"step":1,"ymax":302,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":275,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 2017년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.","answer":["198"],"explanation":["물결선 바로 위 세로 눈금은 185이고, 한 칸은 1만 톤이에요.","2017년의 점은 185에서 13칸 위에 있어요.","185 + 13 = 198 — 198만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[198,196,190,201,209]}],"step":1,"ymax":210,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":185,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#13','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C9',2,'mc','auto','줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],true,'{"seq":13,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"3월과 4월 사이","correct":true},{"t":"4월과 5월 사이","mis":"M4-2-u5-X11"},{"t":"5월과 6월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −65, +60, −50, −15.","가장 많이 늘어난 것은 60회이지만, 3월과 4월에 65회 줄어들었어요.","그래서 가장 많이 변한 때는 3월과 4월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[110,45,105,55,40]}],"step":5,"ymax":115,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"6월과 7월 사이","correct":true},{"t":"3월과 4월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X12"},{"t":"5월과 6월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +45, +10, −15, −60, +35.","가장 많이 늘어난 것은 45회이지만, 6월과 7월에 60회 줄어들었어요.","그래서 가장 많이 변한 때는 6월과 7월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[85,130,140,125,65,100]}],"step":5,"ymax":145,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"3월과 4월 사이","correct":true},{"t":"5월과 6월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −55, −10, +45, −40.","가장 많이 늘어난 것은 45회이지만, 3월과 4월에 55회 줄어들었어요.","그래서 가장 많이 변한 때는 3월과 4월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[105,50,40,85,45]}],"step":5,"ymax":110,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#14','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C10',2,'mc','auto','꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":14,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"해마다 잰 우리 동네 평균 기온","correct":true},{"t":"나라별 평균 기온","mis":"M4-2-u5-X15"},{"t":"도시별 비 온 날수","mis":"M4-2-u5-X15"},{"t":"계절별 좋아하는 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「해마다 잰 우리 동네 평균 기온」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 태풍 발생 횟수","correct":true},{"t":"나라별 태풍 피해 건수","mis":"M4-2-u5-X15"},{"t":"바다별 섬의 수","mis":"M4-2-u5-X15"},{"t":"반별 우산 가진 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 태풍 발생 횟수」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null},{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"시각별 교실 온도","correct":true},{"t":"층별 교실 수","mis":"M4-2-u5-X15"},{"t":"교실별 화분 수","mis":"M4-2-u5-X15"},{"t":"반별 선풍기 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「시각별 교실 온도」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#15','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C11',2,'mc','auto','「월별 강수량」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":15,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「월별 강수량」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["5월","6월","7월","8월","9월"],"series":[{"vals":[210,130,100,90,190]}],"step":10,"ymax":220,"title":"월별 강수량","ylab":"(mm)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"「연도별 폭염 일수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[11,19,20,11,4]}],"step":1,"ymax":21,"title":"연도별 폭염 일수","ylab":"(일)","xlab":"(년)"}},{"stem":"「시각별 운동장 기온」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,18,15,14,22]}],"step":1,"ymax":23,"title":"시각별 운동장 기온","ylab":"(°C)","xlab":"(시)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#16','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C12',2,'sa','auto','5월의 남학생과 여학생의 도서관 이용자 수 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"5월의 남학생과 여학생의 도서관 이용자 수 차는 몇 명인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이름표로 두 선을 먼저 가려요.","5월의 남학생 110명, 여학생 210명이에요.","210 − 110 = 100명이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[190,100,110,60,130]},{"name":"여학생","vals":[230,250,210,220,150]}],"step":10,"ymax":260,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"8월의 가 식물과 나 식물의 키 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["이름표로 두 선을 먼저 가려요.","8월의 가 식물 40 cm, 나 식물 24 cm예요.","40 − 24 = 16 cm예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[6,20,26,38,40]},{"name":"나 식물","vals":[4,10,12,16,24]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"}},{"stem":"6월의 우유와 주스의 판매량 차는 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["이름표로 두 선을 먼저 가려요.","6월의 우유 70개, 주스 100개예요.","100 − 70 = 30개예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[110,80,45,70,60]},{"name":"주스","vals":[115,90,85,100,130]}],"step":5,"ymax":135,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#17','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C5',3,'sa','auto','세로 눈금 한 칸이 10권인 꺾은선그래프예요. 60권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"세로 눈금 한 칸이 10권인 꺾은선그래프예요. 60권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 칸이 10권이니 한 칸 올라갈 때마다 10씩 커져요.","60 ÷ 10 = 6으로 구해요.","60권은 0에서 6째 눈금이에요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 2 °C인 꺾은선그래프예요. 18 °C는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 2 °C이니 한 칸 올라갈 때마다 2씩 커져요.","18 ÷ 2 = 9로 구해요.","18 °C는 0에서 9째 눈금이에요."],"asset":null},{"stem":"세로 눈금 한 칸이 20권인 꺾은선그래프예요. 80권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 칸이 20권이니 한 칸 올라갈 때마다 20씩 커져요.","80 ÷ 20 = 4로 구해요.","80권은 0에서 4째 눈금이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#18','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C7',3,'sa','auto','물결선이 있는 꺾은선그래프예요. 어느 마을의 가구 수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 가구인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 어느 마을의 가구 수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 가구인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이웃한 두 때의 변화: +40, +100, +10, +70.","오른쪽 위로 가장 가파르게 올라간 곳은 2018년과 2019년 사이예요.","가장 많이 늘어난 정도는 100가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[420,460,560,570,640]}],"step":10,"ymax":650,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 어느 도시의 인구수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이웃한 두 때의 변화: +2, −1, −10, +5, −4.","오른쪽 위로 가장 가파르게 올라간 곳은 2020년과 2021년 사이예요.","가장 많이 늘어난 정도는 5만 명이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[50,52,51,41,46,42]}],"step":1,"ymax":53,"ylab":"(만 명)","xlab":"(년)","title":"연도별 어느 도시의 인구수","y0":40,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 우유 생산량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 톤인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이웃한 두 때의 변화: +8, +1, +5, +2.","오른쪽 위로 가장 가파르게 올라간 곳은 2017년과 2018년 사이예요.","가장 많이 늘어난 정도는 8만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[194,202,203,208,210]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":190,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#19','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C9',3,'sa','auto','줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 회인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −55, +15, −60, +5.","가장 가파른 선분은 5월과 6월 사이로, 60회 줄어들었어요.","가장 많이 변한 정도는 60회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[150,95,110,50,55]}],"step":5,"ymax":155,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"미세 먼지 나쁨 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −9, +1, +11, −10, +5.","가장 가파른 선분은 2018년과 2019년 사이로, 11일 늘어났어요.","가장 많이 변한 정도는 11일이에요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[17,8,9,20,10,15]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}},{"stem":"폭염 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −5, +2, −10, +6, −7.","가장 가파른 선분은 2019년과 2020년 사이로, 10일 줄어들었어요.","가장 많이 변한 정도는 10일이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[23,18,20,10,16,9]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#20','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C10',3,'sa','auto','표를 보고 답하세요. 태풍 발생 횟수가 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"표를 보고 답하세요. 태풍 발생 횟수가 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["가장 큰 값은 2016년의 9회예요.","가장 작은 값은 2018년의 1회예요.","9 − 1 = 8회예요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020"],"counts":[9,7,1,6,5],"vh":"태풍 발생 횟수","unit":"회","title":"연도별 태풍 발생 횟수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 운동장의 기온이 가장 높았던 때와 가장 낮았던 때의 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가장 큰 값은 12시의 30 °C예요.","가장 작은 값은 14시의 10 °C예요.","30 − 10 = 20 °C예요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시","14시"],"counts":[26,22,24,30,22,10],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"}},{"stem":"표를 보고 답하세요. 줄넘기 기록이 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["가장 큰 값은 7월의 110회예요.","가장 작은 값은 6월의 65회예요.","110 − 65 = 45회예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[95,75,90,65,110],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#21','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C12',3,'sa','auto','유소년층과 노년층의 인구수 차가 가장 많은 때, 그 차는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-2-u5-C12","difficulty":3,"kind":"sa","stem":"유소년층과 노년층의 인구수 차가 가장 많은 때, 그 차는 몇만 명인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 2018년 40, 2019년 90, 2020년 170, 2021년 290, 2022년 360.","가장 많은 때는 2022년, 차는 360만 명이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,670,620,580,560]},{"name":"노년층","vals":[720,760,790,870,920]}],"step":10,"ymax":930,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true},"variant_rule":{"alt":[{"stem":"서울과 부산의 낮 최고 기온 차가 가장 많은 때, 그 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 2, 4월 6, 5월 11, 6월 7, 7월 5.","가장 많은 때는 5월, 차는 11 °C예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"서울","vals":[9,13,14,20,23]},{"name":"부산","vals":[11,19,25,27,28]}],"step":1,"ymax":29,"title":"월별 낮 최고 기온","ylab":"(°C)","xlab":"(월)"}},{"stem":"남학생과 여학생의 도서관 이용자 수 차가 가장 많은 때, 그 차는 몇 명인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 30, 4월 140, 5월 70, 6월 40, 7월 60.","가장 많은 때는 4월, 차는 140명이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[130,220,140,150,200]},{"name":"여학생","vals":[100,80,70,110,140]}],"step":10,"ymax":230,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#22','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',3,'mc','auto','교실 온도가 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],true,'{"seq":22,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"교실 온도가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"10시부터 11시까지","correct":true},{"t":"9시부터 10시까지","mis":"M4-2-u5-X13"},{"t":"11시부터 12시까지","mis":"M4-2-u5-X13"},{"t":"12시부터 13시까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 10시와 11시 사이에 있어요.","10시와 11시 모두 21 °C예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[28,21,21,23,24,20]}],"step":1,"ymax":29,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"도서관에서 빌려 간 책 수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"6월부터 7월까지","correct":true},{"t":"3월부터 4월까지","mis":"M4-2-u5-X13"},{"t":"4월부터 5월까지","mis":"M4-2-u5-X13"},{"t":"5월부터 6월까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 6월과 7월 사이에 있어요.","6월과 7월 모두 260권이에요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[80,200,270,260,260]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"태풍 발생 횟수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2019년부터 2020년까지","correct":true},{"t":"2016년부터 2017년까지","mis":"M4-2-u5-X13"},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2018년부터 2019년까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 2019년과 2020년 사이에 있어요.","2019년과 2020년 모두 4회예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[1,6,10,4,4,6]}],"step":1,"ymax":11,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SE