INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#23','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C5',4,'sa','auto','빌려 간 책 수는 50권, 100권, 130권, 150권, 180권이에요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u5-C5","difficulty":4,"kind":"sa","stem":"빌려 간 책 수는 50권, 100권, 130권, 150권, 180권이에요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 큰 값은 180권이에요 — 20칸 안에 들어가야 해요.","한 칸이 5이면 20칸으로 100까지밖에 못 나타내요.","한 칸이 10이면 200까지 나타낼 수 있고 값도 모두 10의 배수라 답은 10이에요."],"variant_rule":{"alt":[{"stem":"운동장의 기온은 12 °C, 18 °C, 24 °C, 36 °C, 38 °C예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["가장 큰 값은 38 °C예요 — 20칸 안에 들어가야 해요.","한 칸이 1이면 20칸으로 20까지밖에 못 나타내요.","한 칸이 2이면 40까지 나타낼 수 있고 값도 모두 2의 배수라 답은 2예요."],"asset":null},{"stem":"해바라기의 키는 55 cm, 85 cm, 90 cm, 95 cm, 100 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 큰 값은 100 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 2이면 20칸으로 40까지밖에 못 나타내요.","한 칸이 5이면 100까지 나타낼 수 있고 값도 모두 5의 배수라 답은 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#24','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C8',4,'sa','auto','전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +4, +11, −1, −5, −6, +7.","늘어난 때: 5월, 6월, 10월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[3,7,18,17,12,6,13]}],"step":1,"ymax":19,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +3, −11, −6, +5, +9, −10.","늘어난 때: 5월, 8월, 9월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[19,22,11,5,10,19,9]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +8, −5, +7, +2, −6, −4.","늘어난 때: 5월, 7월, 8월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[11,19,14,21,23,17,13]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_a#25','math',4,2,'u5','','g4_2_math_u5_review_a','unit_review','M4-2-u5-C2',4,'essay','teacher','월별 식물의 키 그래프에서 세로 눈금 한 칸은 2 cm예요. 6월의 점이 0에서 8칸 위에 있을 때 한 친구는 「6월의 키는 8 cm야.」라고 했어요. 친구가 무엇을 잘못했는지 쓰고, 바르게 읽은 값과 그래프를 읽을 때 먼저 확인할 것을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u5-C2","difficulty":4,"kind":"essay","stem":"월별 식물의 키 그래프에서 세로 눈금 한 칸은 2 cm예요. 6월의 점이 0에서 8칸 위에 있을 때 한 친구는 「6월의 키는 8 cm야.」라고 했어요. 친구가 무엇을 잘못했는지 쓰고, 바르게 읽은 값과 그래프를 읽을 때 먼저 확인할 것을 써 보세요.","answer_guide":{"answer":"예: 친구는 세로 눈금 한 칸의 크기를 확인하지 않고 칸 수를 그대로 값으로 읽었다. 한 칸이 2 cm이므로 8칸은 8 × 2 = 16 cm이다. 그래프를 읽을 때는 가로와 세로가 무엇을 나타내는지와 세로 눈금 한 칸의 크기를 먼저 확인해야 한다.","scoring_points":["칸 수를 그대로 읽은 잘못을 썼는가","16 cm로 바르게 구했는가","세로 눈금 한 칸의 크기를 먼저 확인한다고 썼는가"]},"explanation":["세로 눈금 한 칸은 2 cm예요.","8칸 × 2 cm = 16 cm.","가로·세로와 눈금 한 칸을 먼저 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#1','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C1',1,'mc','auto','꺾은선그래프에서 찍은 점들은 무엇으로 잇나요?',ARRAY['M4-2-u5-X06','M4-2-u5-X03','M4-2-u5-X05']::text[],true,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"꺾은선그래프에서 찍은 점들은 무엇으로 잇나요?","options":[{"t":"선분","correct":true},{"t":"곡선","mis":"M4-2-u5-X06"},{"t":"막대","mis":"M4-2-u5-X03"},{"t":"물결선","mis":"M4-2-u5-X05"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프가 막대그래프보다 알아보기 쉬운 것은 어느 것인가요?","options":[{"t":"시간에 따라 달라지는 모습","correct":true},{"t":"자료를 조사한 사람","mis":"M4-2-u5-X03"},{"t":"세로 눈금 한 칸의 크기","mis":"M4-2-u5-X02"},{"t":"자료를 모은 곳","mis":"M4-2-u5-X16"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null},{"stem":"지유는 나무의 키를 두 달마다 재어 점을 찍고 그 점들을 선분으로 이었어요. 이런 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#2','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C2',1,'mc','auto','아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 자외선 지수 매우 높음 일수","correct":true},{"t":"가로: 자외선 지수 매우 높음 일수, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 자외선 지수 매우 높음 일수, 세로: 자외선 지수 매우 높음 일수","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 자외선 지수 매우 높음 일수를 일 단위로 나타냈어요.","가로: 월, 세로: 자외선 지수 매우 높음 일수예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[11,15,20,13,15]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 운동장의 기온","correct":true},{"t":"가로: 운동장의 기온, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 운동장의 기온, 세로: 운동장의 기온","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각, 세로에는 운동장의 기온을 °C 단위로 나타냈어요.","가로: 시각, 세로: 운동장의 기온이에요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,16,22,30,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 도서관에서 빌려 간 책 수","correct":true},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 도서관에서 빌려 간 책 수","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 도서관에서 빌려 간 책 수를 권 단위로 나타냈어요.","가로: 월, 세로: 도서관에서 빌려 간 책 수예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[180,230,260,200,270]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#3','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C3',1,'mc','auto','물결선을 쓴 꺾은선그래프에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X05','M4-2-u5-X09']::text[],true,'{"seq":3,"concept":"M4-2-u5-C3","difficulty":1,"kind":"mc","stem":"물결선을 쓴 꺾은선그래프에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"물결선은 필요 없는 아랫부분을 줄인 것이에요.","correct":true},{"t":"물결선 아래의 값은 모두 0이에요.","mis":"M4-2-u5-X05"},{"t":"물결선을 쓰면 값이 바뀌어요.","mis":"M4-2-u5-X05"},{"t":"물결선은 자료 사이 아무 곳에나 넣어요.","mis":"M4-2-u5-X09"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"variant_rule":{"alt":[{"stem":"온실 안의 온도처럼 값들이 서로 가까운 자료를 그릴 때 알맞은 방법은 어느 것인가요?","options":[{"t":"물결선을 넣고 세로 눈금 한 칸을 작게 해요.","correct":true},{"t":"0부터 그리고 세로 눈금 한 칸을 크게 해요.","mis":"M4-2-u5-X08"},{"t":"점을 곡선으로 이어요.","mis":"M4-2-u5-X06"},{"t":"가로와 세로를 바꿔요.","mis":"M4-2-u5-X01"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null},{"stem":"물결선(≈)이 있는 그래프는 무엇을 줄인 것인가요?","options":[{"t":"세로 눈금에서 0부터의 필요 없는 부분","correct":true},{"t":"가장 큰 값","mis":"M4-2-u5-X05"},{"t":"조사한 자료의 수","mis":"M4-2-u5-X05"},{"t":"가로 눈금의 수","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#4','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C4',1,'mc','auto','가로 눈금과 세로 눈금이 만나는 곳에는 무엇을 하나요?',ARRAY['M4-2-u5-X03','M4-2-u5-X05']::text[],true,'{"seq":4,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"가로 눈금과 세로 눈금이 만나는 곳에는 무엇을 하나요?","options":[{"t":"점을 찍어요.","correct":true},{"t":"막대를 그려요.","mis":"M4-2-u5-X03"},{"t":"물결선을 넣어요.","mis":"M4-2-u5-X05"},{"t":"그림을 붙여요.","mis":"M4-2-u5-X03"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"점을 이을 때 지켜야 할 것은 무엇인가요?","options":[{"t":"가로 눈금의 순서대로 선분으로 이어요.","correct":true},{"t":"큰 값부터 차례로 이어요.","mis":"M4-2-u5-X06"},{"t":"곡선으로 부드럽게 이어요.","mis":"M4-2-u5-X06"},{"t":"이웃하지 않은 점끼리 이어요.","mis":"M4-2-u5-X06"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null},{"stem":"연도별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"가로: 년, 세로: 일","correct":true},{"t":"가로: 일, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 년, 세로: 년","mis":"M4-2-u5-X01"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#5','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C5',1,'sa','auto','표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 권까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["220"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 220권이에요.","그래서 세로 눈금은 적어도 220권까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[40,110,220,180,50],"vh":"도서관에서 빌려 간 책 수","unit":"권","title":"월별 도서관에서 빌려 간 책 수"},"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 cm까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["130"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 130 cm예요.","그래서 세로 눈금은 적어도 130 cm까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월","9월"],"counts":[20,35,55,90,100,130],"vh":"해바라기의 키","unit":"cm","title":"월별 해바라기의 키"}},{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 30 °C예요.","그래서 세로 눈금은 적어도 30 °C까지 나타내요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[24,30,20,28,24],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#6','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C6',1,'mc','auto','우유 생산량은 190만 톤부터 209만 톤까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"우유 생산량은 190만 톤부터 209만 톤까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 190만 톤 사이","correct":true},{"t":"190만 톤과 199만 톤 사이","mis":"M4-2-u5-X09"},{"t":"199만 톤과 209만 톤 사이","mis":"M4-2-u5-X09"},{"t":"209만 톤 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 190만 톤이에요.","그래서 물결선은 0과 190만 톤 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"1인당 하루 물 사용량은 278 L부터 297 L까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 278 L 사이","correct":true},{"t":"278 L와 292 L 사이","mis":"M4-2-u5-X09"},{"t":"292 L와 297 L 사이","mis":"M4-2-u5-X09"},{"t":"297 L 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 278 L예요.","그래서 물결선은 0과 278 L 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"준우의 몸무게는 35 kg부터 41 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 35 kg 사이","correct":true},{"t":"35 kg과 37 kg 사이","mis":"M4-2-u5-X09"},{"t":"37 kg과 41 kg 사이","mis":"M4-2-u5-X09"},{"t":"41 kg 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 35 kg이에요.","그래서 물결선은 0과 35 kg 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#7','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',1,'mc','auto','자외선 지수 매우 높음 일수는 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":7,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"자외선 지수 매우 높음 일수는 어떻게 변하고 있나요?","options":[{"t":"4월부터 9월까지 계속 줄어들었어요.","correct":true},{"t":"4월부터 9월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"7월까지 늘어났고 7월부터는 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"7월까지 줄어들었고 7월부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 오른쪽 아래로만 내려가요.","4월부터 9월까지 계속 줄어들었어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[24,17,11,10,7,2]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"교실 온도는 어떻게 변하고 있나요?","options":[{"t":"10시까지 늘어났고 10시부터는 줄어들었어요.","correct":true},{"t":"9시부터 13시까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"9시부터 13시까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"10시까지 줄어들었고 10시부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 10시까지 올라가다가 그 뒤로 내려가요.","10시까지 늘어났고 10시부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[23,26,21,20,16]}],"step":1,"ymax":27,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}},{"stem":"도서관에서 빌려 간 책 수는 어떻게 변하고 있나요?","options":[{"t":"5월까지 줄어들었고 5월부터는 늘어났어요.","correct":true},{"t":"3월부터 8월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"3월부터 8월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"5월까지 늘어났고 5월부터는 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 5월까지 내려가다가 그 뒤로 올라가요.","5월까지 줄어들었고 5월부터는 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[90,70,60,140,170,270]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#8','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C11',1,'mc','auto','연도별 유적지 관람객 수가 어떻게 달라졌는지 알아보기 쉽게 나타내려면 어떤 그래프가 알맞은가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],true,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"연도별 유적지 관람객 수가 어떻게 달라졌는지 알아보기 쉽게 나타내려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"하루 동안 시각별 교실 온도가 어떻게 변했는지 알아보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null},{"stem":"해마다 잰 키가 어떻게 자랐는지 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
