INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#10','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C3',2,'mc','auto','6월에는 조사하지 않았어요. 6월의 줄넘기 기록은 약 몇 회였을까요?',ARRAY['M4-2-u5-X04']::text[],true,'{"seq":10,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"6월에는 조사하지 않았어요. 6월의 줄넘기 기록은 약 몇 회였을까요?","options":[{"t":"약 75회","correct":true},{"t":"약 70회","mis":"M4-2-u5-X04"},{"t":"약 80회","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["5월과 7월의 두 점을 이은 선분을 봐요.","6월 위의 선분은 70회와 80회의 한가운데쯤을 지나요.","그래서 약 75회였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[25,90,70,null,80]}],"step":5,"ymax":95,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"6월에는 조사하지 않았어요. 6월의 해바라기의 키는 약 몇 cm였을까요?","options":[{"t":"약 55 cm","correct":true},{"t":"약 30 cm","mis":"M4-2-u5-X04"},{"t":"약 80 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["5월과 7월의 두 점을 이은 선분을 봐요.","6월 위의 선분은 30 cm와 80 cm의 한가운데쯤을 지나요.","그래서 약 55 cm였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[20,30,null,80,85]}],"step":5,"ymax":90,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키"}},{"stem":"11시에는 조사하지 않았어요. 11시의 교실 온도는 약 몇 °C였을까요?","options":[{"t":"약 21 °C","correct":true},{"t":"약 27 °C","mis":"M4-2-u5-X04"},{"t":"약 15 °C","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["10시와 12시의 두 점을 이은 선분을 봐요.","11시 위의 선분은 27 °C와 15 °C의 한가운데쯤을 지나요.","그래서 약 21 °C였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[21,27,null,15,19]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#11','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C4',2,'mc','auto','아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07']::text[],true,'{"seq":11,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 순서대로 잇지 않았어요.","correct":true},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 순서대로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[23,25,15,22,18]}],"step":1,"ymax":26,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수","order":[0,2,1,3,4]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 선분이 아니라 곡선으로 이었어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[8,12,20,30,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온","curve":true}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점만 찍고 선분으로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[13,24,18,14,4]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수","dots":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#12','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C6',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 2021년의 1인당 하루 물 사용량은 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 2021년의 1인당 하루 물 사용량은 몇 L인가요? 숫자로 쓰세요.","answer":["301"],"explanation":["물결선 바로 위 세로 눈금은 275이고, 한 칸은 1 L예요.","2021년의 점은 275에서 26칸 위에 있어요.","275 + 26 = 301 — 301 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[280,285,289,298,299,301]}],"step":1,"ymax":302,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":275,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 2017년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.","answer":["198"],"explanation":["물결선 바로 위 세로 눈금은 185이고, 한 칸은 1만 톤이에요.","2017년의 점은 185에서 13칸 위에 있어요.","185 + 13 = 198 — 198만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[198,196,190,201,209]}],"step":1,"ymax":210,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":185,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 2019년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.","answer":["560"],"explanation":["물결선 바로 위 세로 눈금은 400이고, 한 칸은 10가구예요.","2019년의 점은 400에서 16칸 위에 있어요.","400 + 160 = 560 — 560가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[430,510,560,570,610,640]}],"step":10,"ymax":650,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#13','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C9',2,'mc','auto','줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X12','M4-2-u5-X21']::text[],true,'{"seq":13,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"6월과 7월 사이","correct":true},{"t":"3월과 4월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X12"},{"t":"5월과 6월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +45, +10, −15, −60, +35.","가장 많이 늘어난 것은 45회이지만, 6월과 7월에 60회 줄어들었어요.","그래서 가장 많이 변한 때는 6월과 7월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[85,130,140,125,65,100]}],"step":5,"ymax":145,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"3월과 4월 사이","correct":true},{"t":"5월과 6월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −55, −10, +45, −40.","가장 많이 늘어난 것은 45회이지만, 3월과 4월에 55회 줄어들었어요.","그래서 가장 많이 변한 때는 3월과 4월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[105,50,40,85,45]}],"step":5,"ymax":110,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"5월과 6월 사이","correct":true},{"t":"3월과 4월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +35, −30, −60, +25, +15.","가장 많이 늘어난 것은 35회이지만, 5월과 6월에 60회 줄어들었어요.","그래서 가장 많이 변한 때는 5월과 6월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[90,125,95,35,60,75]}],"step":5,"ymax":130,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#14','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C10',2,'mc','auto','꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":14,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 태풍 발생 횟수","correct":true},{"t":"나라별 태풍 피해 건수","mis":"M4-2-u5-X15"},{"t":"바다별 섬의 수","mis":"M4-2-u5-X15"},{"t":"반별 우산 가진 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 태풍 발생 횟수」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"시각별 교실 온도","correct":true},{"t":"층별 교실 수","mis":"M4-2-u5-X15"},{"t":"교실별 화분 수","mis":"M4-2-u5-X15"},{"t":"반별 선풍기 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「시각별 교실 온도」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null},{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 우리나라 바다의 수온","correct":true},{"t":"바다별 물고기 종류 수","mis":"M4-2-u5-X15"},{"t":"항구별 배의 수","mis":"M4-2-u5-X15"},{"t":"나라별 해안선 길이","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 우리나라 바다의 수온」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#15','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C11',2,'mc','auto','「연도별 폭염 일수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":15,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「연도별 폭염 일수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[11,19,20,11,4]}],"step":1,"ymax":21,"title":"연도별 폭염 일수","ylab":"(일)","xlab":"(년)"},"variant_rule":{"alt":[{"stem":"「시각별 운동장 기온」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,18,15,14,22]}],"step":1,"ymax":23,"title":"시각별 운동장 기온","ylab":"(°C)","xlab":"(시)"}},{"stem":"「월별 빌려 간 책 수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[130,180,140,220,110]}],"step":10,"ymax":230,"title":"월별 빌려 간 책 수","ylab":"(권)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#16','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C12',2,'sa','auto','8월의 가 식물과 나 식물의 키 차는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"8월의 가 식물과 나 식물의 키 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["이름표로 두 선을 먼저 가려요.","8월의 가 식물 40 cm, 나 식물 24 cm예요.","40 − 24 = 16 cm예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[6,20,26,38,40]},{"name":"나 식물","vals":[4,10,12,16,24]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"6월의 우유와 주스의 판매량 차는 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["이름표로 두 선을 먼저 가려요.","6월의 우유 70개, 주스 100개예요.","100 − 70 = 30개예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[110,80,45,70,60]},{"name":"주스","vals":[115,90,85,100,130]}],"step":5,"ymax":135,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}},{"stem":"3월의 하준과 서아의 줄넘기 기록 차는 몇 회인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이름표로 두 선을 먼저 가려요.","3월의 하준 45회, 서아 50회예요.","50 − 45 = 5회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[45,55,75,115,130]},{"name":"서아","vals":[50,100,115,135,140]}],"step":5,"ymax":145,"title":"월별 줄넘기 기록","ylab":"(회)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#17','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C5',3,'sa','auto','세로 눈금 한 칸이 2 °C인 꺾은선그래프예요. 18 °C는 0에서 몇째 눈금인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"세로 눈금 한 칸이 2 °C인 꺾은선그래프예요. 18 °C는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 칸이 2 °C이니 한 칸 올라갈 때마다 2씩 커져요.","18 ÷ 2 = 9로 구해요.","18 °C는 0에서 9째 눈금이에요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 20권인 꺾은선그래프예요. 80권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 칸이 20권이니 한 칸 올라갈 때마다 20씩 커져요.","80 ÷ 20 = 4로 구해요.","80권은 0에서 4째 눈금이에요."],"asset":null},{"stem":"세로 눈금 한 칸이 5 cm인 꺾은선그래프예요. 40 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 칸이 5 cm이니 한 칸 올라갈 때마다 5씩 커져요.","40 ÷ 5 = 8로 구해요.","40 cm는 0에서 8째 눈금이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#18','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C7',3,'sa','auto','물결선이 있는 꺾은선그래프예요. 어느 도시의 인구수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 어느 도시의 인구수가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이웃한 두 때의 변화: +2, −1, −10, +5, −4.","오른쪽 위로 가장 가파르게 올라간 곳은 2020년과 2021년 사이예요.","가장 많이 늘어난 정도는 5만 명이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[50,52,51,41,46,42]}],"step":1,"ymax":53,"ylab":"(만 명)","xlab":"(년)","title":"연도별 어느 도시의 인구수","y0":40,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 우유 생산량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 톤인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이웃한 두 때의 변화: +8, +1, +5, +2.","오른쪽 위로 가장 가파르게 올라간 곳은 2017년과 2018년 사이예요.","가장 많이 늘어난 정도는 8만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[194,202,203,208,210]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":190,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 1인당 하루 물 사용량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 L인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이웃한 두 때의 변화: +5, −3, +8, −9, −2.","오른쪽 위로 가장 가파르게 올라간 곳은 2018년과 2019년 사이예요.","가장 많이 늘어난 정도는 8 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[291,296,293,301,292,290]}],"step":1,"ymax":302,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":285,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#19','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C9',3,'sa','auto','미세 먼지 나쁨 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"미세 먼지 나쁨 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −9, +1, +11, −10, +5.","가장 가파른 선분은 2018년과 2019년 사이로, 11일 늘어났어요.","가장 많이 변한 정도는 11일이에요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[17,8,9,20,10,15]}],"step":1,"ymax":21,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"폭염 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −5, +2, −10, +6, −7.","가장 가파른 선분은 2019년과 2020년 사이로, 10일 줄어들었어요.","가장 많이 변한 정도는 10일이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[23,18,20,10,16,9]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}},{"stem":"자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, −7, +8, −6.","가장 가파른 선분은 6월과 7월 사이로, 8일 늘어났어요.","가장 많이 변한 정도는 8일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[12,17,10,18,12]}],"step":1,"ymax":19,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#20','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C10',3,'sa','auto','표를 보고 답하세요. 운동장의 기온이 가장 높았던 때와 가장 낮았던 때의 차는 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"표를 보고 답하세요. 운동장의 기온이 가장 높았던 때와 가장 낮았던 때의 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가장 큰 값은 12시의 30 °C예요.","가장 작은 값은 14시의 10 °C예요.","30 − 10 = 20 °C예요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시","14시"],"counts":[26,22,24,30,22,10],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 줄넘기 기록이 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["가장 큰 값은 7월의 110회예요.","가장 작은 값은 6월의 65회예요.","110 − 65 = 45회예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[95,75,90,65,110],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"}},{"stem":"표를 보고 답하세요. 미세 먼지 나쁨 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["가장 큰 값은 2020년의 27일이에요.","가장 작은 값은 2016년의 16일이에요.","27 − 16 = 11일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020","2021"],"counts":[16,24,17,23,27,22],"vh":"미세 먼지 나쁨 일수","unit":"일","title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#21','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C12',3,'sa','auto','서울과 부산의 낮 최고 기온 차가 가장 많은 때, 그 차는 몇 °C인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-2-u5-C12","difficulty":3,"kind":"sa","stem":"서울과 부산의 낮 최고 기온 차가 가장 많은 때, 그 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 2, 4월 6, 5월 11, 6월 7, 7월 5.","가장 많은 때는 5월, 차는 11 °C예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"서울","vals":[9,13,14,20,23]},{"name":"부산","vals":[11,19,25,27,28]}],"step":1,"ymax":29,"title":"월별 낮 최고 기온","ylab":"(°C)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"남학생과 여학생의 도서관 이용자 수 차가 가장 많은 때, 그 차는 몇 명인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 30, 4월 140, 5월 70, 6월 40, 7월 60.","가장 많은 때는 4월, 차는 140명이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[130,220,140,150,200]},{"name":"여학생","vals":[100,80,70,110,140]}],"step":10,"ymax":230,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"}},{"stem":"가 식물과 나 식물의 키 차가 가장 많은 때, 그 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 4월 6, 5월 14, 6월 16, 7월 18, 8월 2.","가장 많은 때는 7월, 차는 18 cm예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[8,10,14,20,38]},{"name":"나 식물","vals":[14,24,30,38,40]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#22','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',3,'mc','auto','도서관에서 빌려 간 책 수가 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],true,'{"seq":22,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"도서관에서 빌려 간 책 수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"6월부터 7월까지","correct":true},{"t":"3월부터 4월까지","mis":"M4-2-u5-X13"},{"t":"4월부터 5월까지","mis":"M4-2-u5-X13"},{"t":"5월부터 6월까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 6월과 7월 사이에 있어요.","6월과 7월 모두 260권이에요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[80,200,270,260,260]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"},"variant_rule":{"alt":[{"stem":"태풍 발생 횟수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2019년부터 2020년까지","correct":true},{"t":"2016년부터 2017년까지","mis":"M4-2-u5-X13"},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2018년부터 2019년까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 2019년과 2020년 사이에 있어요.","2019년과 2020년 모두 4회예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[1,6,10,4,4,6]}],"step":1,"ymax":11,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}},{"stem":"운동장의 기온이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"11시부터 12시까지","correct":true},{"t":"9시부터 10시까지","mis":"M4-2-u5-X13"},{"t":"10시부터 11시까지","mis":"M4-2-u5-X13"},{"t":"12시부터 13시까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 11시와 12시 사이에 있어요.","11시와 12시 모두 16 °C예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[20,24,16,16,10]}],"step":2,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#23','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C5',4,'sa','auto','운동장의 기온은 12 °C, 18 °C, 24 °C, 36 °C, 38 °C예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u5-C5","difficulty":4,"kind":"sa","stem":"운동장의 기온은 12 °C, 18 °C, 24 °C, 36 °C, 38 °C예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["가장 큰 값은 38 °C예요 — 20칸 안에 들어가야 해요.","한 칸이 1이면 20칸으로 20까지밖에 못 나타내요.","한 칸이 2이면 40까지 나타낼 수 있고 값도 모두 2의 배수라 답은 2예요."],"variant_rule":{"alt":[{"stem":"해바라기의 키는 55 cm, 85 cm, 90 cm, 95 cm, 100 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 큰 값은 100 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 2이면 20칸으로 40까지밖에 못 나타내요.","한 칸이 5이면 100까지 나타낼 수 있고 값도 모두 5의 배수라 답은 5예요."],"asset":null},{"stem":"나무의 키는 30 cm, 50 cm, 130 cm, 180 cm, 200 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 큰 값은 200 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 5이면 20칸으로 100까지밖에 못 나타내요.","한 칸이 10이면 200까지 나타낼 수 있고 값도 모두 10의 배수라 답은 10이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#24','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C8',4,'sa','auto','전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +3, −11, −6, +5, +9, −10.","늘어난 때: 5월, 8월, 9월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[19,22,11,5,10,19,9]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +8, −5, +7, +2, −6, −4.","늘어난 때: 5월, 7월, 8월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[11,19,14,21,23,17,13]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +9, +3, −8, −2, −1, −6.","늘어난 때: 5월, 6월.","모두 2번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[9,18,21,13,11,10,4]}],"step":1,"ymax":22,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_b#25','math',4,2,'u5','','g4_2_math_u5_review_b','unit_review','M4-2-u5-C6',4,'essay','teacher','1인당 하루 물 사용량은 288, 291, 293, 296, 299 L예요. 이 자료를 꺾은선그래프로 나타낼 때 물결선을 넣으면 좋은 까닭과 넣을 자리를 쓰고, 물결선을 쓰면 값이 달라지는지도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u5-C6","difficulty":4,"kind":"essay","stem":"1인당 하루 물 사용량은 288, 291, 293, 296, 299 L예요. 이 자료를 꺾은선그래프로 나타낼 때 물결선을 넣으면 좋은 까닭과 넣을 자리를 쓰고, 물결선을 쓰면 값이 달라지는지도 써 보세요.","answer_guide":{"answer":"예: 값이 288 L부터 299 L까지로 크고 서로 가까워서 0부터 그리면 변화가 잘 보이지 않는다. 물결선을 넣어 필요 없는 아랫부분을 줄이면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보인다. 물결선은 0과 가장 작은 값 288 L 사이에 넣는다. 물결선을 써도 값은 달라지지 않는다.","scoring_points":["값이 크고 가까워 변화가 잘 안 보인다고 썼는가","0과 288 L 사이에 넣는다고 썼는가","물결선을 써도 값은 그대로라고 썼는가"]},"explanation":["0부터 그리면 꺾은선이 거의 평평해 보여요.","물결선은 0과 가장 작은 값 288 L 사이에 넣어요.","물결선은 부분을 줄일 뿐, 값은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#1','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C1',1,'mc','auto','꺾은선그래프가 막대그래프보다 알아보기 쉬운 것은 어느 것인가요?',ARRAY['M4-2-u5-X03','M4-2-u5-X02','M4-2-u5-X16']::text[],true,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"꺾은선그래프가 막대그래프보다 알아보기 쉬운 것은 어느 것인가요?","options":[{"t":"시간에 따라 달라지는 모습","correct":true},{"t":"자료를 조사한 사람","mis":"M4-2-u5-X03"},{"t":"세로 눈금 한 칸의 크기","mis":"M4-2-u5-X02"},{"t":"자료를 모은 곳","mis":"M4-2-u5-X16"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"variant_rule":{"alt":[{"stem":"지유는 나무의 키를 두 달마다 재어 점을 찍고 그 점들을 선분으로 이었어요. 이런 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null},{"stem":"시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#2','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C2',1,'mc','auto','아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 운동장의 기온","correct":true},{"t":"가로: 운동장의 기온, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 운동장의 기온, 세로: 운동장의 기온","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각, 세로에는 운동장의 기온을 °C 단위로 나타냈어요.","가로: 시각, 세로: 운동장의 기온이에요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,16,22,30,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 도서관에서 빌려 간 책 수","correct":true},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 도서관에서 빌려 간 책 수","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 도서관에서 빌려 간 책 수를 권 단위로 나타냈어요.","가로: 월, 세로: 도서관에서 빌려 간 책 수예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[180,230,260,200,270]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 선인장 줄기의 길이","correct":true},{"t":"가로: 선인장 줄기의 길이, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 선인장 줄기의 길이, 세로: 선인장 줄기의 길이","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 선인장 줄기의 길이를 cm 단위로 나타냈어요.","가로: 월, 세로: 선인장 줄기의 길이예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[20,26,34,36,40]}],"step":2,"ymax":42,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#3','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C3',1,'mc','auto','온실 안의 온도처럼 값들이 서로 가까운 자료를 그릴 때 알맞은 방법은 어느 것인가요?',ARRAY['M4-2-u5-X08','M4-2-u5-X06','M4-2-u5-X01']::text[],true,'{"seq":3,"concept":"M4-2-u5-C3","difficulty":1,"kind":"mc","stem":"온실 안의 온도처럼 값들이 서로 가까운 자료를 그릴 때 알맞은 방법은 어느 것인가요?","options":[{"t":"물결선을 넣고 세로 눈금 한 칸을 작게 해요.","correct":true},{"t":"0부터 그리고 세로 눈금 한 칸을 크게 해요.","mis":"M4-2-u5-X08"},{"t":"점을 곡선으로 이어요.","mis":"M4-2-u5-X06"},{"t":"가로와 세로를 바꿔요.","mis":"M4-2-u5-X01"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"variant_rule":{"alt":[{"stem":"물결선(≈)이 있는 그래프는 무엇을 줄인 것인가요?","options":[{"t":"세로 눈금에서 0부터의 필요 없는 부분","correct":true},{"t":"가장 큰 값","mis":"M4-2-u5-X05"},{"t":"조사한 자료의 수","mis":"M4-2-u5-X05"},{"t":"가로 눈금의 수","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null},{"stem":"꺾은선그래프에서 물결선(≈)을 쓰면 어떤 점이 좋은가요?","options":[{"t":"필요 없는 부분을 줄여 변화하는 모습이 잘 보여요.","correct":true},{"t":"나타낼 값이 많아져요.","mis":"M4-2-u5-X05"},{"t":"자료의 값이 커져요.","mis":"M4-2-u5-X05"},{"t":"가로 눈금이 촘촘해져요.","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#4','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C4',1,'mc','auto','점을 이을 때 지켜야 할 것은 무엇인가요?',ARRAY['M4-2-u5-X06']::text[],true,'{"seq":4,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"점을 이을 때 지켜야 할 것은 무엇인가요?","options":[{"t":"가로 눈금의 순서대로 선분으로 이어요.","correct":true},{"t":"큰 값부터 차례로 이어요.","mis":"M4-2-u5-X06"},{"t":"곡선으로 부드럽게 이어요.","mis":"M4-2-u5-X06"},{"t":"이웃하지 않은 점끼리 이어요.","mis":"M4-2-u5-X06"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"연도별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"가로: 년, 세로: 일","correct":true},{"t":"가로: 일, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 년, 세로: 년","mis":"M4-2-u5-X01"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null},{"stem":"표를 보고 꺾은선그래프로 나타낼 때 맨 마지막에 하는 일은 무엇인가요?","options":[{"t":"점을 찍고 순서대로 선분으로 이어요.","correct":true},{"t":"제목을 써요.","mis":"M4-2-u5-X21"},{"t":"가로와 세로에 나타낼 것을 정해요.","mis":"M4-2-u5-X21"},{"t":"세로 눈금 한 칸의 크기를 정해요.","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#5','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C5',1,'sa','auto','표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 cm까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 cm까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["130"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 130 cm예요.","그래서 세로 눈금은 적어도 130 cm까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월","9월"],"counts":[20,35,55,90,100,130],"vh":"해바라기의 키","unit":"cm","title":"월별 해바라기의 키"},"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 30 °C예요.","그래서 세로 눈금은 적어도 30 °C까지 나타내요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[24,30,20,28,24],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"}},{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["150"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 150회예요.","그래서 세로 눈금은 적어도 150회까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[150,90,120,95,55],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#6','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C6',1,'mc','auto','1인당 하루 물 사용량은 278 L부터 297 L까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"1인당 하루 물 사용량은 278 L부터 297 L까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 278 L 사이","correct":true},{"t":"278 L와 292 L 사이","mis":"M4-2-u5-X09"},{"t":"292 L와 297 L 사이","mis":"M4-2-u5-X09"},{"t":"297 L 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 278 L예요.","그래서 물결선은 0과 278 L 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"준우의 몸무게는 35 kg부터 41 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 35 kg 사이","correct":true},{"t":"35 kg과 37 kg 사이","mis":"M4-2-u5-X09"},{"t":"37 kg과 41 kg 사이","mis":"M4-2-u5-X09"},{"t":"41 kg 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 35 kg이에요.","그래서 물결선은 0과 35 kg 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"준우의 몸무게는 32 kg부터 42 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 32 kg 사이","correct":true},{"t":"32 kg과 35 kg 사이","mis":"M4-2-u5-X09"},{"t":"35 kg과 42 kg 사이","mis":"M4-2-u5-X09"},{"t":"42 kg 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 32 kg이에요.","그래서 물결선은 0과 32 kg 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#7','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',1,'mc','auto','교실 온도는 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":7,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"교실 온도는 어떻게 변하고 있나요?","options":[{"t":"10시까지 늘어났고 10시부터는 줄어들었어요.","correct":true},{"t":"9시부터 13시까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"9시부터 13시까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"10시까지 줄어들었고 10시부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 10시까지 올라가다가 그 뒤로 내려가요.","10시까지 늘어났고 10시부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[23,26,21,20,16]}],"step":1,"ymax":27,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"도서관에서 빌려 간 책 수는 어떻게 변하고 있나요?","options":[{"t":"5월까지 줄어들었고 5월부터는 늘어났어요.","correct":true},{"t":"3월부터 8월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"3월부터 8월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"5월까지 늘어났고 5월부터는 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 5월까지 내려가다가 그 뒤로 올라가요.","5월까지 줄어들었고 5월부터는 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[90,70,60,140,170,270]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"태풍 발생 횟수는 어떻게 변하고 있나요?","options":[{"t":"2018년까지 늘어났고 2018년부터는 줄어들었어요.","correct":true},{"t":"2016년부터 2020년까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"2016년부터 2020년까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"2018년까지 줄어들었고 2018년부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 2018년까지 올라가다가 그 뒤로 내려가요.","2018년까지 늘어났고 2018년부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[4,8,9,3,1]}],"step":1,"ymax":10,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#8','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C11',1,'mc','auto','하루 동안 시각별 교실 온도가 어떻게 변했는지 알아보려면 어떤 그래프가 알맞은가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],true,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"하루 동안 시각별 교실 온도가 어떻게 변했는지 알아보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"해마다 잰 키가 어떻게 자랐는지 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null},{"stem":"시간에 따른 자료의 변화를 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#9','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C2',2,'sa','auto','4월의 자외선 지수 매우 높음 일수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C2","difficulty":2,"kind":"sa","stem":"4월의 자외선 지수 매우 높음 일수는 며칠인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["세로 눈금 한 칸은 1일이에요.","4월의 점을 따라 세로 눈금을 읽어요.","4월의 자외선 지수 매우 높음 일수는 14일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[14,11,10,21,16]}],"step":1,"ymax":22,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"2020년의 미세 먼지 나쁨 일수는 며칠인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["세로 눈금 한 칸은 1일이에요.","2020년의 점을 따라 세로 눈금을 읽어요.","2020년의 미세 먼지 나쁨 일수는 22일이에요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[6,12,16,17,22,25]}],"step":1,"ymax":26,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}},{"stem":"7월의 도서관에서 빌려 간 책 수는 몇 권인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["세로 눈금 한 칸은 10권이에요.","7월의 점은 0에서 12칸 위에 있어요.","12 × 10 = 120 — 7월의 도서관에서 빌려 간 책 수는 120권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[100,70,160,170,120]}],"step":10,"ymax":180,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#10','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C3',2,'mc','auto','6월에는 조사하지 않았어요. 6월의 해바라기의 키는 약 몇 cm였을까요?',ARRAY['M4-2-u5-X04']::text[],true,'{"seq":10,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"6월에는 조사하지 않았어요. 6월의 해바라기의 키는 약 몇 cm였을까요?","options":[{"t":"약 55 cm","correct":true},{"t":"약 30 cm","mis":"M4-2-u5-X04"},{"t":"약 80 cm","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["5월과 7월의 두 점을 이은 선분을 봐요.","6월 위의 선분은 30 cm와 80 cm의 한가운데쯤을 지나요.","그래서 약 55 cm였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[20,30,null,80,85]}],"step":5,"ymax":90,"ylab":"(cm)","xlab":"(월)","title":"월별 해바라기의 키"},"variant_rule":{"alt":[{"stem":"11시에는 조사하지 않았어요. 11시의 교실 온도는 약 몇 °C였을까요?","options":[{"t":"약 21 °C","correct":true},{"t":"약 27 °C","mis":"M4-2-u5-X04"},{"t":"약 15 °C","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["10시와 12시의 두 점을 이은 선분을 봐요.","11시 위의 선분은 27 °C와 15 °C의 한가운데쯤을 지나요.","그래서 약 21 °C였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[21,27,null,15,19]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}},{"stem":"2018년에는 조사하지 않았어요. 2018년의 폭염 일수는 약 며칠이었을까요?","options":[{"t":"약 7일","correct":true},{"t":"약 4일","mis":"M4-2-u5-X04"},{"t":"약 10일","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["2017년과 2019년의 두 점을 이은 선분을 봐요.","2018년 위의 선분은 4일과 10일의 한가운데쯤을 지나요.","그래서 약 7일이었을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[4,null,10,14,22]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#11','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C4',2,'mc','auto','아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07']::text[],true,'{"seq":11,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 선분이 아니라 곡선으로 이었어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[8,12,20,30,32]}],"step":2,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온","curve":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점만 찍고 선분으로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[13,24,18,14,4]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수","dots":true}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 순서대로 잇지 않았어요.","correct":true},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 순서대로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[14,20,17,24,19]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도","order":[0,2,1,3,4]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#12','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C6',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 2017년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 2017년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.","answer":["198"],"explanation":["물결선 바로 위 세로 눈금은 185이고, 한 칸은 1만 톤이에요.","2017년의 점은 185에서 13칸 위에 있어요.","185 + 13 = 198 — 198만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[198,196,190,201,209]}],"step":1,"ymax":210,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":185,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 2019년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.","answer":["560"],"explanation":["물결선 바로 위 세로 눈금은 400이고, 한 칸은 10가구예요.","2019년의 점은 400에서 16칸 위에 있어요.","400 + 160 = 560 — 560가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[430,510,560,570,610,640]}],"step":10,"ymax":650,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 7월의 준우의 몸무게는 몇 kg인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["물결선 바로 위 세로 눈금은 30이고, 한 칸은 1 kg이에요.","7월의 점은 30에서 3칸 위에 있어요.","30 + 3 = 33 — 33 kg이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[35,37,40,39,33]}],"step":1,"ymax":41,"ylab":"(kg)","xlab":"(월)","title":"월별 준우의 몸무게","y0":30,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#13','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C9',2,'mc','auto','줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],true,'{"seq":13,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"3월과 4월 사이","correct":true},{"t":"5월과 6월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −55, −10, +45, −40.","가장 많이 늘어난 것은 45회이지만, 3월과 4월에 55회 줄어들었어요.","그래서 가장 많이 변한 때는 3월과 4월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[105,50,40,85,45]}],"step":5,"ymax":110,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"5월과 6월 사이","correct":true},{"t":"3월과 4월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +35, −30, −60, +25, +15.","가장 많이 늘어난 것은 35회이지만, 5월과 6월에 60회 줄어들었어요.","그래서 가장 많이 변한 때는 5월과 6월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[90,125,95,35,60,75]}],"step":5,"ymax":130,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"5월과 6월 사이","correct":true},{"t":"4월과 5월 사이","mis":"M4-2-u5-X11"},{"t":"3월과 4월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, +35, −50, +15.","가장 많이 늘어난 것은 35회이지만, 5월과 6월에 50회 줄어들었어요.","그래서 가장 많이 변한 때는 5월과 6월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[45,50,85,35,50]}],"step":5,"ymax":90,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#14','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C10',2,'mc','auto','꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":14,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"시각별 교실 온도","correct":true},{"t":"층별 교실 수","mis":"M4-2-u5-X15"},{"t":"교실별 화분 수","mis":"M4-2-u5-X15"},{"t":"반별 선풍기 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「시각별 교실 온도」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 우리나라 바다의 수온","correct":true},{"t":"바다별 물고기 종류 수","mis":"M4-2-u5-X15"},{"t":"항구별 배의 수","mis":"M4-2-u5-X15"},{"t":"나라별 해안선 길이","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 우리나라 바다의 수온」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null},{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 폭염 일수","correct":true},{"t":"지역별 폭염 일수","mis":"M4-2-u5-X15"},{"t":"우리 반이 좋아하는 계절","mis":"M4-2-u5-X15"},{"t":"학교별 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 폭염 일수」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#15','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C11',2,'mc','auto','「시각별 운동장 기온」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":15,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「시각별 운동장 기온」을 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[12,18,15,14,22]}],"step":1,"ymax":23,"title":"시각별 운동장 기온","ylab":"(°C)","xlab":"(시)"},"variant_rule":{"alt":[{"stem":"「월별 빌려 간 책 수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[130,180,140,220,110]}],"step":10,"ymax":230,"title":"월별 빌려 간 책 수","ylab":"(권)","xlab":"(월)"}},{"stem":"「6월부터 10월까지의 월별 최고 온도」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[26,27,33,28,32]}],"step":1,"ymax":34,"title":"6월부터 10월까지의 월별 최고 온도","ylab":"(°C)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#16','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C12',2,'sa','auto','6월의 우유와 주스의 판매량 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"6월의 우유와 주스의 판매량 차는 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["이름표로 두 선을 먼저 가려요.","6월의 우유 70개, 주스 100개예요.","100 − 70 = 30개예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[110,80,45,70,60]},{"name":"주스","vals":[115,90,85,100,130]}],"step":5,"ymax":135,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"3월의 하준과 서아의 줄넘기 기록 차는 몇 회인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이름표로 두 선을 먼저 가려요.","3월의 하준 45회, 서아 50회예요.","50 − 45 = 5회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[45,55,75,115,130]},{"name":"서아","vals":[50,100,115,135,140]}],"step":5,"ymax":145,"title":"월별 줄넘기 기록","ylab":"(회)","xlab":"(월)"}},{"stem":"2019년의 유소년층과 노년층의 인구수 차는 몇만 명인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이름표로 두 선을 먼저 가려요.","2019년의 유소년층 640만 명, 노년층 740만 명이에요.","740 − 640 = 100만 명이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,640,620,610,560]},{"name":"노년층","vals":[730,740,830,880,910]}],"step":10,"ymax":920,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#17','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C5',3,'sa','auto','세로 눈금 한 칸이 20권인 꺾은선그래프예요. 80권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"세로 눈금 한 칸이 20권인 꺾은선그래프예요. 80권은 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 칸이 20권이니 한 칸 올라갈 때마다 20씩 커져요.","80 ÷ 20 = 4로 구해요.","80권은 0에서 4째 눈금이에요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 5 cm인 꺾은선그래프예요. 40 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 칸이 5 cm이니 한 칸 올라갈 때마다 5씩 커져요.","40 ÷ 5 = 8로 구해요.","40 cm는 0에서 8째 눈금이에요."],"asset":null},{"stem":"세로 눈금 한 칸이 2 cm인 꺾은선그래프예요. 10 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸이 2 cm이니 한 칸 올라갈 때마다 2씩 커져요.","10 ÷ 2 = 5로 구해요.","10 cm는 0에서 5째 눈금이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#18','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C7',3,'sa','auto','물결선이 있는 꺾은선그래프예요. 우유 생산량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 톤인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 우유 생산량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇만 톤인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이웃한 두 때의 변화: +8, +1, +5, +2.","오른쪽 위로 가장 가파르게 올라간 곳은 2017년과 2018년 사이예요.","가장 많이 늘어난 정도는 8만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[194,202,203,208,210]}],"step":1,"ymax":211,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":190,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 1인당 하루 물 사용량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 L인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이웃한 두 때의 변화: +5, −3, +8, −9, −2.","오른쪽 위로 가장 가파르게 올라간 곳은 2018년과 2019년 사이예요.","가장 많이 늘어난 정도는 8 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[291,296,293,301,292,290]}],"step":1,"ymax":302,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":285,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 정원 해바라기의 키가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["이웃한 두 때의 변화: +5, +10, +3, +1.","오른쪽 위로 가장 가파르게 올라간 곳은 7월과 8월 사이예요.","가장 많이 늘어난 정도는 10 cm예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[172,177,187,190,191]}],"step":1,"ymax":192,"ylab":"(cm)","xlab":"(월)","title":"월별 정원 해바라기의 키","y0":170,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#19','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C9',3,'sa','auto','폭염 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"폭염 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −5, +2, −10, +6, −7.","가장 가파른 선분은 2019년과 2020년 사이로, 10일 줄어들었어요.","가장 많이 변한 정도는 10일이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[23,18,20,10,16,9]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"},"variant_rule":{"alt":[{"stem":"자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, −7, +8, −6.","가장 가파른 선분은 6월과 7월 사이로, 8일 늘어났어요.","가장 많이 변한 정도는 8일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[12,17,10,18,12]}],"step":1,"ymax":19,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"교실 온도가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, −7, +1, +3.","가장 가파른 선분은 10시와 11시 사이로, 7 °C 줄어들었어요.","가장 많이 변한 정도는 7 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[23,28,21,22,25]}],"step":1,"ymax":29,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#20','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C10',3,'sa','auto','표를 보고 답하세요. 줄넘기 기록이 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"표를 보고 답하세요. 줄넘기 기록이 가장 많았던 때와 가장 적었던 때의 차는 몇 회인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["가장 큰 값은 7월의 110회예요.","가장 작은 값은 6월의 65회예요.","110 − 65 = 45회예요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[95,75,90,65,110],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 미세 먼지 나쁨 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["가장 큰 값은 2020년의 27일이에요.","가장 작은 값은 2016년의 16일이에요.","27 − 16 = 11일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020","2021"],"counts":[16,24,17,23,27,22],"vh":"미세 먼지 나쁨 일수","unit":"일","title":"연도별 미세 먼지 나쁨 일수"}},{"stem":"표를 보고 답하세요. 폭염 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["가장 큰 값은 2017년의 22일이에요.","가장 작은 값은 2021년의 10일이에요.","22 − 10 = 12일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[22,14,17,11,10],"vh":"폭염 일수","unit":"일","title":"연도별 폭염 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#21','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C12',3,'sa','auto','남학생과 여학생의 도서관 이용자 수 차가 가장 많은 때, 그 차는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-2-u5-C12","difficulty":3,"kind":"sa","stem":"남학생과 여학생의 도서관 이용자 수 차가 가장 많은 때, 그 차는 몇 명인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 30, 4월 140, 5월 70, 6월 40, 7월 60.","가장 많은 때는 4월, 차는 140명이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"남학생","vals":[130,220,140,150,200]},{"name":"여학생","vals":[100,80,70,110,140]}],"step":10,"ymax":230,"title":"월별 도서관 이용자 수","ylab":"(명)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"가 식물과 나 식물의 키 차가 가장 많은 때, 그 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 4월 6, 5월 14, 6월 16, 7월 18, 8월 2.","가장 많은 때는 7월, 차는 18 cm예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[8,10,14,20,38]},{"name":"나 식물","vals":[14,24,30,38,40]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"}},{"stem":"우유와 주스의 판매량 차가 가장 많은 때, 그 차는 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 15, 4월 55, 5월 40, 6월 10, 7월 30.","가장 많은 때는 4월, 차는 55개예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[90,70,110,75,60]},{"name":"주스","vals":[105,125,150,85,90]}],"step":5,"ymax":155,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#22','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',3,'mc','auto','태풍 발생 횟수가 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],true,'{"seq":22,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"태풍 발생 횟수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2019년부터 2020년까지","correct":true},{"t":"2016년부터 2017년까지","mis":"M4-2-u5-X13"},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2018년부터 2019년까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 2019년과 2020년 사이에 있어요.","2019년과 2020년 모두 4회예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[1,6,10,4,4,6]}],"step":1,"ymax":11,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"},"variant_rule":{"alt":[{"stem":"운동장의 기온이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"11시부터 12시까지","correct":true},{"t":"9시부터 10시까지","mis":"M4-2-u5-X13"},{"t":"10시부터 11시까지","mis":"M4-2-u5-X13"},{"t":"12시부터 13시까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 11시와 12시 사이에 있어요.","11시와 12시 모두 16 °C예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[20,24,16,16,10]}],"step":2,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}},{"stem":"줄넘기 기록이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"5월부터 6월까지","correct":true},{"t":"3월부터 4월까지","mis":"M4-2-u5-X13"},{"t":"4월부터 5월까지","mis":"M4-2-u5-X13"},{"t":"6월부터 7월까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 5월과 6월 사이에 있어요.","5월과 6월 모두 55회예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[30,20,55,55,110]}],"step":5,"ymax":115,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#23','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C5',4,'sa','auto','해바라기의 키는 55 cm, 85 cm, 90 cm, 95 cm, 100 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u5-C5","difficulty":4,"kind":"sa","stem":"해바라기의 키는 55 cm, 85 cm, 90 cm, 95 cm, 100 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 큰 값은 100 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 2이면 20칸으로 40까지밖에 못 나타내요.","한 칸이 5이면 100까지 나타낼 수 있고 값도 모두 5의 배수라 답은 5예요."],"variant_rule":{"alt":[{"stem":"나무의 키는 30 cm, 50 cm, 130 cm, 180 cm, 200 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 큰 값은 200 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 5이면 20칸으로 100까지밖에 못 나타내요.","한 칸이 10이면 200까지 나타낼 수 있고 값도 모두 10의 배수라 답은 10이에요."],"asset":null},{"stem":"선인장 줄기의 길이는 12 cm, 16 cm, 26 cm, 34 cm, 36 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["가장 큰 값은 36 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 1이면 20칸으로 20까지밖에 못 나타내요.","한 칸이 2이면 40까지 나타낼 수 있고 값도 모두 2의 배수라 답은 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#24','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C8',4,'sa','auto','전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +8, −5, +7, +2, −6, −4.","늘어난 때: 5월, 7월, 8월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[11,19,14,21,23,17,13]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +9, +3, −8, −2, −1, −6.","늘어난 때: 5월, 6월.","모두 2번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[9,18,21,13,11,10,4]}],"step":1,"ymax":22,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: −11, +7, −2, +3, +9, −4.","늘어난 때: 6월, 8월, 9월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[17,6,13,11,14,23,19]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_c#25','math',4,2,'u5','','g4_2_math_u5_review_c','unit_review','M4-2-u5-C9',4,'essay','teacher','국제선 운항 횟수는 2017년부터 2019년까지 늘다가 2020년에 크게 줄었어요. 「가장 많이 변한 때」를 찾을 때 늘어난 곳만 보면 안 되는 까닭을 쓰고, 선분의 모양으로 가장 많이 변한 때를 찾는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u5-C9","difficulty":4,"kind":"essay","stem":"국제선 운항 횟수는 2017년부터 2019년까지 늘다가 2020년에 크게 줄었어요. 「가장 많이 변한 때」를 찾을 때 늘어난 곳만 보면 안 되는 까닭을 쓰고, 선분의 모양으로 가장 많이 변한 때를 찾는 방법을 써 보세요.","answer_guide":{"answer":"예: 줄어든 것도 값이 달라진 것이므로 변한 것이다. 늘어난 곳만 보면 크게 줄어든 2019년과 2020년 사이를 놓친다. 이웃한 두 점을 이은 선분 가운데 위로든 아래로든 가장 가파른 선분을 찾으면 그때가 가장 많이 변한 때이다.","scoring_points":["줄어든 것도 변한 것이라고 썼는가","크게 줄어든 때를 놓친다고 썼는가","가장 가파른 선분(위·아래 모두)을 찾는다고 썼는가"]},"explanation":["줄어든 것도 변한 거예요.","늘어난 곳만 보면 크게 줄어든 때를 놓쳐요.","위로든 아래로든 가장 가파른 선분을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#1','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C1',1,'mc','auto','지유는 나무의 키를 두 달마다 재어 점을 찍고 그 점들을 선분으로 이었어요. 이런 그래프를 무엇이라고 하나요?',ARRAY['M4-2-u5-X03']::text[],true,'{"seq":1,"concept":"M4-2-u5-C1","difficulty":1,"kind":"mc","stem":"지유는 나무의 키를 두 달마다 재어 점을 찍고 그 점들을 선분으로 이었어요. 이런 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"수직선","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"variant_rule":{"alt":[{"stem":"시간에 따라 변화하는 양을 점으로 표시하고, 그 점들을 선분으로 이어 그린 그래프를 무엇이라고 하나요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"막대그래프","mis":"M4-2-u5-X03"},{"t":"그림그래프","mis":"M4-2-u5-X03"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null},{"stem":"꺾은선그래프는 어떻게 그린 그래프인가요?","options":[{"t":"변화하는 양을 점으로 표시하고 점들을 선분으로 이은 그래프","correct":true},{"t":"수량을 막대 모양으로 나타낸 그래프","mis":"M4-2-u5-X03"},{"t":"수량을 그림의 크기와 수로 나타낸 그래프","mis":"M4-2-u5-X03"},{"t":"점을 찍고 곡선으로 부드럽게 이은 그래프","mis":"M4-2-u5-X06"}],"explanation":["꺾은선그래프는 시간에 따라 변화하는 양을 나타내요.","가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 그 점들을 선분으로 이어요.","그래서 양이 어떻게 달라졌는지 한눈에 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#2','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C2',1,'mc','auto','아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":2,"concept":"M4-2-u5-C2","difficulty":1,"kind":"mc","stem":"아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 도서관에서 빌려 간 책 수","correct":true},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 도서관에서 빌려 간 책 수, 세로: 도서관에서 빌려 간 책 수","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 도서관에서 빌려 간 책 수를 권 단위로 나타냈어요.","가로: 월, 세로: 도서관에서 빌려 간 책 수예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[180,230,260,200,270]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 월, 세로: 선인장 줄기의 길이","correct":true},{"t":"가로: 선인장 줄기의 길이, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 월","mis":"M4-2-u5-X01"},{"t":"가로: 선인장 줄기의 길이, 세로: 선인장 줄기의 길이","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 월, 세로에는 선인장 줄기의 길이를 cm 단위로 나타냈어요.","가로: 월, 세로: 선인장 줄기의 길이예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[20,26,34,36,40]}],"step":2,"ymax":42,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프에서 가로와 세로는 각각 무엇을 나타내나요?","options":[{"t":"가로: 시각, 세로: 운동장의 기온","correct":true},{"t":"가로: 운동장의 기온, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 시각, 세로: 시각","mis":"M4-2-u5-X01"},{"t":"가로: 운동장의 기온, 세로: 운동장의 기온","mis":"M4-2-u5-X01"}],"explanation":["가로 눈금 아래에 적힌 것이 가로가 나타내는 것이에요.","가로에는 시각, 세로에는 운동장의 기온을 °C 단위로 나타냈어요.","가로: 시각, 세로: 운동장의 기온이에요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[24,26,34,22,26]}],"step":2,"ymax":36,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#3','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C3',1,'mc','auto','물결선(≈)이 있는 그래프는 무엇을 줄인 것인가요?',ARRAY['M4-2-u5-X05']::text[],true,'{"seq":3,"concept":"M4-2-u5-C3","difficulty":1,"kind":"mc","stem":"물결선(≈)이 있는 그래프는 무엇을 줄인 것인가요?","options":[{"t":"세로 눈금에서 0부터의 필요 없는 부분","correct":true},{"t":"가장 큰 값","mis":"M4-2-u5-X05"},{"t":"조사한 자료의 수","mis":"M4-2-u5-X05"},{"t":"가로 눈금의 수","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프에서 물결선(≈)을 쓰면 어떤 점이 좋은가요?","options":[{"t":"필요 없는 부분을 줄여 변화하는 모습이 잘 보여요.","correct":true},{"t":"나타낼 값이 많아져요.","mis":"M4-2-u5-X05"},{"t":"자료의 값이 커져요.","mis":"M4-2-u5-X05"},{"t":"가로 눈금이 촘촘해져요.","mis":"M4-2-u5-X05"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null},{"stem":"물결선(≈)은 꺾은선그래프의 어디에 넣나요?","options":[{"t":"세로 눈금에서 필요 없는 아랫부분","correct":true},{"t":"가로 눈금의 맨 끝","mis":"M4-2-u5-X09"},{"t":"가장 큰 값 위쪽","mis":"M4-2-u5-X09"},{"t":"점과 점 사이","mis":"M4-2-u5-X06"}],"explanation":["값이 크거나 서로 가까우면 0부터 그릴 때 아랫부분이 길게 비어요.","물결선(≈)으로 0과 가장 작은 값 사이의 필요 없는 부분을 줄여요.","그러면 세로 눈금 한 칸을 작게 잡아 변화가 뚜렷하게 보여요 — 값은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#4','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C4',1,'mc','auto','연도별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X01']::text[],true,'{"seq":4,"concept":"M4-2-u5-C4","difficulty":1,"kind":"mc","stem":"연도별 미세 먼지 나쁨 일수를 꺾은선그래프로 나타낼 때 가로와 세로 눈금의 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"가로: 년, 세로: 일","correct":true},{"t":"가로: 일, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 월, 세로: 년","mis":"M4-2-u5-X01"},{"t":"가로: 년, 세로: 년","mis":"M4-2-u5-X01"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타낼 때 맨 마지막에 하는 일은 무엇인가요?","options":[{"t":"점을 찍고 순서대로 선분으로 이어요.","correct":true},{"t":"제목을 써요.","mis":"M4-2-u5-X21"},{"t":"가로와 세로에 나타낼 것을 정해요.","mis":"M4-2-u5-X21"},{"t":"세로 눈금 한 칸의 크기를 정해요.","mis":"M4-2-u5-X21"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null},{"stem":"세로 눈금 한 칸의 크기를 정할 때 꼭 생각해야 하는 것은 무엇인가요?","options":[{"t":"가장 큰 값까지 나타낼 수 있는지","correct":true},{"t":"가장 작은 값만 나타낼 수 있는지","mis":"M4-2-u5-X07"},{"t":"가로 눈금이 몇 개인지","mis":"M4-2-u5-X07"},{"t":"제목이 얼마나 긴지","mis":"M4-2-u5-X07"}],"explanation":["다섯 걸음 — ① 제목 ② 가로·세로에 나타낼 것 ③ 눈금의 단위 ④ 세로 눈금 한 칸의 크기.","⑤ 가로 눈금과 세로 눈금이 만나는 곳에 점을 찍고, 순서대로 선분으로 이어요.","세로 눈금은 가장 큰 값까지 나타낼 수 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#5','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C5',1,'sa','auto','표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u5-C5","difficulty":1,"kind":"sa","stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 °C까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["30"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 30 °C예요.","그래서 세로 눈금은 적어도 30 °C까지 나타내요."],"asset":{"type":"picg","only":"table","head":"시각(시)","cols":["9시","10시","11시","12시","13시"],"counts":[24,30,20,28,24],"vh":"운동장의 기온","unit":"°C","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 회까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["150"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 150회예요.","그래서 세로 눈금은 적어도 150회까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["3월","4월","5월","6월","7월"],"counts":[150,90,120,95,55],"vh":"줄넘기 기록","unit":"회","title":"월별 줄넘기 기록"}},{"stem":"표를 보고 꺾은선그래프로 나타내려고 해요. 세로 눈금은 적어도 몇 cm까지 나타내어야 하나요? 숫자로 쓰세요.","answer":["40"],"explanation":["세로 눈금은 모든 값을 찍을 수 있어야 해요.","표에서 가장 큰 값은 40 cm예요.","그래서 세로 눈금은 적어도 40 cm까지 나타내요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["6월","7월","8월","9월","10월"],"counts":[6,14,30,34,40],"vh":"선인장 줄기의 길이","unit":"cm","title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#6','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C6',1,'mc','auto','준우의 몸무게는 35 kg부터 41 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?',ARRAY['M4-2-u5-X09']::text[],true,'{"seq":6,"concept":"M4-2-u5-C6","difficulty":1,"kind":"mc","stem":"준우의 몸무게는 35 kg부터 41 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 35 kg 사이","correct":true},{"t":"35 kg과 37 kg 사이","mis":"M4-2-u5-X09"},{"t":"37 kg과 41 kg 사이","mis":"M4-2-u5-X09"},{"t":"41 kg 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 35 kg이에요.","그래서 물결선은 0과 35 kg 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"variant_rule":{"alt":[{"stem":"준우의 몸무게는 32 kg부터 42 kg까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 32 kg 사이","correct":true},{"t":"32 kg과 35 kg 사이","mis":"M4-2-u5-X09"},{"t":"35 kg과 42 kg 사이","mis":"M4-2-u5-X09"},{"t":"42 kg 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 32 kg이에요.","그래서 물결선은 0과 32 kg 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null},{"stem":"어느 마을의 가구 수는 470가구부터 580가구까지예요. 물결선(≈)을 어디에 넣으면 좋을까요?","options":[{"t":"0과 470가구 사이","correct":true},{"t":"470가구와 560가구 사이","mis":"M4-2-u5-X09"},{"t":"560가구와 580가구 사이","mis":"M4-2-u5-X09"},{"t":"580가구 위쪽","mis":"M4-2-u5-X09"}],"explanation":["물결선은 필요 없는 아랫부분을 줄일 때 써요.","자료에서 가장 작은 값은 470가구예요.","그래서 물결선은 0과 470가구 사이에 넣어요 — 자료의 수 범위 안에는 넣지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#7','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',1,'mc','auto','도서관에서 빌려 간 책 수는 어떻게 변하고 있나요?',ARRAY['M4-2-u5-X10']::text[],true,'{"seq":7,"concept":"M4-2-u5-C8","difficulty":1,"kind":"mc","stem":"도서관에서 빌려 간 책 수는 어떻게 변하고 있나요?","options":[{"t":"5월까지 줄어들었고 5월부터는 늘어났어요.","correct":true},{"t":"3월부터 8월까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"3월부터 8월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"5월까지 늘어났고 5월부터는 줄어들었어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 5월까지 내려가다가 그 뒤로 올라가요.","5월까지 줄어들었고 5월부터는 늘어났어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[90,70,60,140,170,270]}],"step":10,"ymax":280,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"},"variant_rule":{"alt":[{"stem":"태풍 발생 횟수는 어떻게 변하고 있나요?","options":[{"t":"2018년까지 늘어났고 2018년부터는 줄어들었어요.","correct":true},{"t":"2016년부터 2020년까지 계속 늘어났어요.","mis":"M4-2-u5-X10"},{"t":"2016년부터 2020년까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"2018년까지 줄어들었고 2018년부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 2018년까지 올라가다가 그 뒤로 내려가요.","2018년까지 늘어났고 2018년부터는 줄어들었어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020"],"series":[{"vals":[4,8,9,3,1]}],"step":1,"ymax":10,"ylab":"(회)","xlab":"(년)","title":"연도별 태풍 발생 횟수"}},{"stem":"선인장 줄기의 길이는 어떻게 변하고 있나요?","options":[{"t":"6월부터 11월까지 계속 늘어났어요.","correct":true},{"t":"6월부터 11월까지 계속 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"9월까지 늘어났고 9월부터는 줄어들었어요.","mis":"M4-2-u5-X10"},{"t":"9월까지 줄어들었고 9월부터는 늘어났어요.","mis":"M4-2-u5-X10"}],"explanation":["꺾은선이 오른쪽 위로 올라가면 늘어난 것, 아래로 내려가면 줄어든 것이에요.","이 그래프는 오른쪽 위로만 올라가요.","6월부터 11월까지 계속 늘어났어요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월","11월"],"series":[{"vals":[8,18,32,36,38,46]}],"step":2,"ymax":48,"ylab":"(cm)","xlab":"(월)","title":"월별 선인장 줄기의 길이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#8','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C11',1,'mc','auto','해마다 잰 키가 어떻게 자랐는지 한눈에 보려면 어떤 그래프가 알맞은가요?',ARRAY['M4-2-u5-X17','M4-2-u5-X03']::text[],true,'{"seq":8,"concept":"M4-2-u5-C11","difficulty":1,"kind":"mc","stem":"해마다 잰 키가 어떻게 자랐는지 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"시간에 따른 자료의 변화를 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null},{"stem":"연도별 해수면 높이가 어떻게 달라졌는지 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프","mis":"M4-2-u5-X17"},{"t":"막대그래프","mis":"M4-2-u5-X17"},{"t":"표","mis":"M4-2-u5-X03"}],"explanation":["변화를 알아보려는 자료예요.","꺾은선그래프는 선분이 기울어진 모양으로 늘어남과 줄어듦이 보여요.","그래서 꺾은선그래프가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#9','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C2',2,'sa','auto','2020년의 미세 먼지 나쁨 일수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u5-C2","difficulty":2,"kind":"sa","stem":"2020년의 미세 먼지 나쁨 일수는 며칠인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["세로 눈금 한 칸은 1일이에요.","2020년의 점을 따라 세로 눈금을 읽어요.","2020년의 미세 먼지 나쁨 일수는 22일이에요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[6,12,16,17,22,25]}],"step":1,"ymax":26,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"7월의 도서관에서 빌려 간 책 수는 몇 권인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["세로 눈금 한 칸은 10권이에요.","7월의 점은 0에서 12칸 위에 있어요.","12 × 10 = 120 — 7월의 도서관에서 빌려 간 책 수는 120권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[100,70,160,170,120]}],"step":10,"ymax":180,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}},{"stem":"9월의 자외선 지수 매우 높음 일수는 며칠인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["세로 눈금 한 칸은 1일이에요.","9월의 점을 따라 세로 눈금을 읽어요.","9월의 자외선 지수 매우 높음 일수는 23일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월"],"series":[{"vals":[5,9,12,14,22,23]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#10','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C3',2,'mc','auto','11시에는 조사하지 않았어요. 11시의 교실 온도는 약 몇 °C였을까요?',ARRAY['M4-2-u5-X04']::text[],true,'{"seq":10,"concept":"M4-2-u5-C3","difficulty":2,"kind":"mc","stem":"11시에는 조사하지 않았어요. 11시의 교실 온도는 약 몇 °C였을까요?","options":[{"t":"약 21 °C","correct":true},{"t":"약 27 °C","mis":"M4-2-u5-X04"},{"t":"약 15 °C","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["10시와 12시의 두 점을 이은 선분을 봐요.","11시 위의 선분은 27 °C와 15 °C의 한가운데쯤을 지나요.","그래서 약 21 °C였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[21,27,null,15,19]}],"step":1,"ymax":28,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"},"variant_rule":{"alt":[{"stem":"2018년에는 조사하지 않았어요. 2018년의 폭염 일수는 약 며칠이었을까요?","options":[{"t":"약 7일","correct":true},{"t":"약 4일","mis":"M4-2-u5-X04"},{"t":"약 10일","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["2017년과 2019년의 두 점을 이은 선분을 봐요.","2018년 위의 선분은 4일과 10일의 한가운데쯤을 지나요.","그래서 약 7일이었을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021"],"series":[{"vals":[4,null,10,14,22]}],"step":1,"ymax":23,"ylab":"(일)","xlab":"(년)","title":"연도별 폭염 일수"}},{"stem":"6월에는 조사하지 않았어요. 6월의 줄넘기 기록은 약 몇 회였을까요?","options":[{"t":"약 115회","correct":true},{"t":"약 80회","mis":"M4-2-u5-X04"},{"t":"약 150회","mis":"M4-2-u5-X04"},{"t":"알 수 없어요.","mis":"M4-2-u5-X04"}],"explanation":["5월과 7월의 두 점을 이은 선분을 봐요.","6월 위의 선분은 80회와 150회의 한가운데쯤을 지나요.","그래서 약 115회였을 것이라고 짐작해요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[25,70,80,null,150]}],"step":5,"ymax":155,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#11','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C4',2,'mc','auto','아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u5-X06','M4-2-u5-X07']::text[],true,'{"seq":11,"concept":"M4-2-u5-C4","difficulty":2,"kind":"mc","stem":"아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점만 찍고 선분으로 잇지 않았어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점만 찍고 선분으로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[13,24,18,14,4]}],"step":1,"ymax":25,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수","dots":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 순서대로 잇지 않았어요.","correct":true},{"t":"점을 선분이 아니라 곡선으로 이었어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 순서대로 잇지 않았어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[14,20,17,24,19]}],"step":1,"ymax":25,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도","order":[0,2,1,3,4]}},{"stem":"이번에는 다른 그림이에요. 아래 꺾은선그래프는 잘못 그렸어요. 잘못 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"점을 선분이 아니라 곡선으로 이었어요.","correct":true},{"t":"점을 순서대로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"점만 찍고 선분으로 잇지 않았어요.","mis":"M4-2-u5-X06"},{"t":"세로 눈금을 가장 큰 값까지 나타내지 않았어요.","mis":"M4-2-u5-X07"}],"explanation":["꺾은선그래프는 점을 찍고 가로 눈금의 순서대로 선분으로 이어요.","이 그래프는 점을 선분이 아니라 곡선으로 이었어요.","순서대로 선분으로 이어야 사이의 값을 바르게 짐작할 수 있어요."],"asset":{"type":"lgraph","xs":["3월","5월","7월","9월","11월"],"series":[{"vals":[50,110,130,170,200]}],"step":10,"ymax":210,"ylab":"(cm)","xlab":"(월)","title":"월별 나무의 키","curve":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#12','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C6',2,'sa','auto','물결선이 있는 꺾은선그래프예요. 2019년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-2-u5-C6","difficulty":2,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 2019년의 어느 마을의 가구 수는 몇 가구인가요? 숫자로 쓰세요.","answer":["560"],"explanation":["물결선 바로 위 세로 눈금은 400이고, 한 칸은 10가구예요.","2019년의 점은 400에서 16칸 위에 있어요.","400 + 160 = 560 — 560가구예요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[430,510,560,570,610,640]}],"step":10,"ymax":650,"ylab":"(가구)","xlab":"(년)","title":"연도별 어느 마을의 가구 수","y0":400,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 7월의 준우의 몸무게는 몇 kg인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["물결선 바로 위 세로 눈금은 30이고, 한 칸은 1 kg이에요.","7월의 점은 30에서 3칸 위에 있어요.","30 + 3 = 33 — 33 kg이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[35,37,40,39,33]}],"step":1,"ymax":41,"ylab":"(kg)","xlab":"(월)","title":"월별 준우의 몸무게","y0":30,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 2021년의 우유 생산량은 몇만 톤인가요? 숫자로 쓰세요.","answer":["207"],"explanation":["물결선 바로 위 세로 눈금은 190이고, 한 칸은 1만 톤이에요.","2021년의 점은 190에서 17칸 위에 있어요.","190 + 17 = 207 — 207만 톤이에요."],"asset":{"type":"lgraph","xs":["2017","2018","2019","2020","2021","2022"],"series":[{"vals":[191,196,198,201,207,208]}],"step":1,"ymax":209,"ylab":"(만 톤)","xlab":"(년)","title":"연도별 우유 생산량","y0":190,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#13','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C9',2,'mc','auto','줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?',ARRAY['M4-2-u5-X11','M4-2-u5-X21']::text[],true,'{"seq":13,"concept":"M4-2-u5-C9","difficulty":2,"kind":"mc","stem":"줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"5월과 6월 사이","correct":true},{"t":"3월과 4월 사이","mis":"M4-2-u5-X11"},{"t":"4월과 5월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +35, −30, −60, +25, +15.","가장 많이 늘어난 것은 35회이지만, 5월과 6월에 60회 줄어들었어요.","그래서 가장 많이 변한 때는 5월과 6월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[90,125,95,35,60,75]}],"step":5,"ymax":130,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"5월과 6월 사이","correct":true},{"t":"4월과 5월 사이","mis":"M4-2-u5-X11"},{"t":"3월과 4월 사이","mis":"M4-2-u5-X21"},{"t":"6월과 7월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, +35, −50, +15.","가장 많이 늘어난 것은 35회이지만, 5월과 6월에 50회 줄어들었어요.","그래서 가장 많이 변한 때는 5월과 6월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[45,50,85,35,50]}],"step":5,"ymax":90,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"이번에는 다른 그림이에요. 줄넘기 기록이 이웃한 두 때 사이에서 가장 많이 변한 때는 언제인가요?","options":[{"t":"4월과 5월 사이","correct":true},{"t":"7월과 8월 사이","mis":"M4-2-u5-X11"},{"t":"3월과 4월 사이","mis":"M4-2-u5-X12"},{"t":"5월과 6월 사이","mis":"M4-2-u5-X21"}],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +30, −45, +10, −35, +40.","가장 많이 늘어난 것은 40회이지만, 4월과 5월에 45회 줄어들었어요.","그래서 가장 많이 변한 때는 4월과 5월 사이예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[75,105,60,70,35,75]}],"step":5,"ymax":110,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#14','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C10',2,'mc','auto','꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?',ARRAY['M4-2-u5-X15']::text[],true,'{"seq":14,"concept":"M4-2-u5-C10","difficulty":2,"kind":"mc","stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 우리나라 바다의 수온","correct":true},{"t":"바다별 물고기 종류 수","mis":"M4-2-u5-X15"},{"t":"항구별 배의 수","mis":"M4-2-u5-X15"},{"t":"나라별 해안선 길이","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 우리나라 바다의 수온」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"variant_rule":{"alt":[{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"연도별 폭염 일수","correct":true},{"t":"지역별 폭염 일수","mis":"M4-2-u5-X15"},{"t":"우리 반이 좋아하는 계절","mis":"M4-2-u5-X15"},{"t":"학교별 학생 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「연도별 폭염 일수」는 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null},{"stem":"꺾은선그래프로 나타내기에 알맞은 조사 주제는 어느 것인가요?","options":[{"t":"월별 우리 집 전기 사용량","correct":true},{"t":"가전제품별 전기 사용량","mis":"M4-2-u5-X15"},{"t":"방별 전등 수","mis":"M4-2-u5-X15"},{"t":"반별 에너지 지킴이 수","mis":"M4-2-u5-X15"}],"explanation":["꺾은선그래프는 시간에 따라 달라지는 자료에 알맞아요.","「월별 우리 집 전기 사용량」은 시간에 따라 달라지는 자료예요.","지역별·학교별처럼 시간과 관계없이 항목끼리 견주는 자료는 어울리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#15','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C11',2,'mc','auto','「월별 빌려 간 책 수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M4-2-u5-X18','M4-2-u5-X17']::text[],true,'{"seq":15,"concept":"M4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「월별 빌려 간 책 수」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[130,180,140,220,110]}],"step":10,"ymax":230,"title":"월별 빌려 간 책 수","ylab":"(권)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"「6월부터 10월까지의 월별 최고 온도」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[26,27,33,28,32]}],"step":1,"ymax":34,"title":"6월부터 10월까지의 월별 최고 온도","ylab":"(°C)","xlab":"(월)"}},{"stem":"「연도별 해수면 높이」를 막대그래프로 나타냈어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"틀린 것은 아니지만 변화의 흐름을 알아보기는 어려워요.","correct":true},{"t":"이어진 자료이므로 막대그래프로 나타내면 틀린 것이에요.","mis":"M4-2-u5-X18"},{"t":"막대그래프가 언제나 꺾은선그래프보다 좋아요.","mis":"M4-2-u5-X17"},{"t":"이런 자료는 어떤 그래프로도 나타낼 수 없어요.","mis":"M4-2-u5-X17"}],"explanation":["이어진 자료를 막대그래프로 나타내도 틀린 것은 아니에요.","막대그래프로는 때마다의 크기를 견주기 좋아요.","다만 어떻게 달라져 왔는지와 두 때 사이의 값은 알아보기 어려워요."],"asset":{"type":"lgraph","mode":"bar","xs":["2018","2019","2020","2021","2022"],"series":[{"vals":[21,30,26,29,37]}],"step":1,"ymax":38,"title":"연도별 해수면 높이","ylab":"(cm)","xlab":"(년)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#16','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C12',2,'sa','auto','3월의 하준과 서아의 줄넘기 기록 차는 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u5-C12","difficulty":2,"kind":"sa","stem":"3월의 하준과 서아의 줄넘기 기록 차는 몇 회인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이름표로 두 선을 먼저 가려요.","3월의 하준 45회, 서아 50회예요.","50 − 45 = 5회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[45,55,75,115,130]},{"name":"서아","vals":[50,100,115,135,140]}],"step":5,"ymax":145,"title":"월별 줄넘기 기록","ylab":"(회)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"2019년의 유소년층과 노년층의 인구수 차는 몇만 명인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["이름표로 두 선을 먼저 가려요.","2019년의 유소년층 640만 명, 노년층 740만 명이에요.","740 − 640 = 100만 명이에요."],"asset":{"type":"lgraph","xs":["2018","2019","2020","2021","2022"],"series":[{"name":"유소년층","vals":[680,640,620,610,560]},{"name":"노년층","vals":[730,740,830,880,910]}],"step":10,"ymax":920,"title":"연도별 인구수","ylab":"(만 명)","xlab":"(년)","y0":550,"wave":true}},{"stem":"7월의 서울과 부산의 낮 최고 기온 차는 몇 °C인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["이름표로 두 선을 먼저 가려요.","7월의 서울 25 °C, 부산 28 °C예요.","28 − 25 = 3 °C예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"서울","vals":[6,10,11,17,25]},{"name":"부산","vals":[8,14,22,24,28]}],"step":1,"ymax":29,"title":"월별 낮 최고 기온","ylab":"(°C)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#17','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C5',3,'sa','auto','세로 눈금 한 칸이 5 cm인 꺾은선그래프예요. 40 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u5-C5","difficulty":3,"kind":"sa","stem":"세로 눈금 한 칸이 5 cm인 꺾은선그래프예요. 40 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 칸이 5 cm이니 한 칸 올라갈 때마다 5씩 커져요.","40 ÷ 5 = 8로 구해요.","40 cm는 0에서 8째 눈금이에요."],"variant_rule":{"alt":[{"stem":"세로 눈금 한 칸이 2 cm인 꺾은선그래프예요. 10 cm는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 칸이 2 cm이니 한 칸 올라갈 때마다 2씩 커져요.","10 ÷ 2 = 5로 구해요.","10 cm는 0에서 5째 눈금이에요."],"asset":null},{"stem":"세로 눈금 한 칸이 5회인 꺾은선그래프예요. 35회는 0에서 몇째 눈금인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸이 5회이니 한 칸 올라갈 때마다 5씩 커져요.","35 ÷ 5 = 7로 구해요.","35회는 0에서 7째 눈금이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#18','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C7',3,'sa','auto','물결선이 있는 꺾은선그래프예요. 1인당 하루 물 사용량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u5-C7","difficulty":3,"kind":"sa","stem":"물결선이 있는 꺾은선그래프예요. 1인당 하루 물 사용량이 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 L인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이웃한 두 때의 변화: +5, −3, +8, −9, −2.","오른쪽 위로 가장 가파르게 올라간 곳은 2018년과 2019년 사이예요.","가장 많이 늘어난 정도는 8 L예요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[291,296,293,301,292,290]}],"step":1,"ymax":302,"ylab":"(L)","xlab":"(년)","title":"연도별 1인당 하루 물 사용량","y0":285,"wave":true},"variant_rule":{"alt":[{"stem":"물결선이 있는 꺾은선그래프예요. 정원 해바라기의 키가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["이웃한 두 때의 변화: +5, +10, +3, +1.","오른쪽 위로 가장 가파르게 올라간 곳은 7월과 8월 사이예요.","가장 많이 늘어난 정도는 10 cm예요."],"asset":{"type":"lgraph","xs":["6월","7월","8월","9월","10월"],"series":[{"vals":[172,177,187,190,191]}],"step":1,"ymax":192,"ylab":"(cm)","xlab":"(월)","title":"월별 정원 해바라기의 키","y0":170,"wave":true}},{"stem":"물결선이 있는 꺾은선그래프예요. 수영장 물의 온도가 이웃한 두 때 사이에서 가장 많이 늘어난 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["이웃한 두 때의 변화: +5, −3, +1, −2, −6.","오른쪽 위로 가장 가파르게 올라간 곳은 9시와 10시 사이예요.","가장 많이 늘어난 정도는 5 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시","14시"],"series":[{"vals":[28,33,30,31,29,23]}],"step":1,"ymax":34,"ylab":"(°C)","xlab":"(시)","title":"시각별 수영장 물의 온도","y0":20,"wave":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#19','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C9',3,'sa','auto','자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u5-C9","difficulty":3,"kind":"sa","stem":"자외선 지수 매우 높음 일수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 며칠인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, −7, +8, −6.","가장 가파른 선분은 6월과 7월 사이로, 8일 늘어났어요.","가장 많이 변한 정도는 8일이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"vals":[12,17,10,18,12]}],"step":1,"ymax":19,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"교실 온도가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 °C인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: +5, −7, +1, +3.","가장 가파른 선분은 10시와 11시 사이로, 7 °C 줄어들었어요.","가장 많이 변한 정도는 7 °C예요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[23,28,21,22,25]}],"step":1,"ymax":29,"ylab":"(°C)","xlab":"(시)","title":"시각별 교실 온도"}},{"stem":"도서관에서 빌려 간 책 수가 이웃한 두 때 사이에서 가장 많이 변한 정도는 몇 권인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["늘어난 것과 줄어든 것을 모두 견주어요: −30, −90, +110, +60, +50.","가장 가파른 선분은 5월과 6월 사이로, 110권 늘어났어요.","가장 많이 변한 정도는 110권이에요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월","8월"],"series":[{"vals":[180,150,60,170,230,280]}],"step":10,"ymax":290,"ylab":"(권)","xlab":"(월)","title":"월별 도서관에서 빌려 간 책 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#20','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C10',3,'sa','auto','표를 보고 답하세요. 미세 먼지 나쁨 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-2-u5-C10","difficulty":3,"kind":"sa","stem":"표를 보고 답하세요. 미세 먼지 나쁨 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["가장 큰 값은 2020년의 27일이에요.","가장 작은 값은 2016년의 16일이에요.","27 − 16 = 11일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2016","2017","2018","2019","2020","2021"],"counts":[16,24,17,23,27,22],"vh":"미세 먼지 나쁨 일수","unit":"일","title":"연도별 미세 먼지 나쁨 일수"},"variant_rule":{"alt":[{"stem":"표를 보고 답하세요. 폭염 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["가장 큰 값은 2017년의 22일이에요.","가장 작은 값은 2021년의 10일이에요.","22 − 10 = 12일이에요."],"asset":{"type":"picg","only":"table","head":"연도(년)","cols":["2017","2018","2019","2020","2021"],"counts":[22,14,17,11,10],"vh":"폭염 일수","unit":"일","title":"연도별 폭염 일수"}},{"stem":"표를 보고 답하세요. 자외선 지수 매우 높음 일수가 가장 많았던 때와 가장 적었던 때의 차는 며칠인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가장 큰 값은 7월의 22일이에요.","가장 작은 값은 4월의 2일이에요.","22 − 2 = 20일이에요."],"asset":{"type":"picg","only":"table","head":"월(월)","cols":["4월","5월","6월","7월","8월","9월"],"counts":[2,11,18,22,21,16],"vh":"자외선 지수 매우 높음 일수","unit":"일","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#21','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C12',3,'sa','auto','가 식물과 나 식물의 키 차가 가장 많은 때, 그 차는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M4-2-u5-C12","difficulty":3,"kind":"sa","stem":"가 식물과 나 식물의 키 차가 가장 많은 때, 그 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 4월 6, 5월 14, 6월 16, 7월 18, 8월 2.","가장 많은 때는 7월, 차는 18 cm예요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월"],"series":[{"name":"가 식물","vals":[8,10,14,20,38]},{"name":"나 식물","vals":[14,24,30,38,40]}],"step":2,"ymax":42,"title":"월별 두 식물의 키","ylab":"(cm)","xlab":"(월)"},"variant_rule":{"alt":[{"stem":"우유와 주스의 판매량 차가 가장 많은 때, 그 차는 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 15, 4월 55, 5월 40, 6월 10, 7월 30.","가장 많은 때는 4월, 차는 55개예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"우유","vals":[90,70,110,75,60]},{"name":"주스","vals":[105,125,150,85,90]}],"step":5,"ymax":155,"title":"월별 판매량","ylab":"(개)","xlab":"(월)"}},{"stem":"하준과 서아의 줄넘기 기록 차가 가장 많은 때, 그 차는 몇 회인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["같은 때의 두 점 사이가 가장 먼 곳을 찾아요.","때마다의 차: 3월 20, 4월 10, 5월 30, 6월 25, 7월 15.","가장 많은 때는 5월, 차는 30회예요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"name":"하준","vals":[35,50,55,75,125]},{"name":"서아","vals":[55,60,85,100,140]}],"step":5,"ymax":145,"title":"월별 줄넘기 기록","ylab":"(회)","xlab":"(월)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#22','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',3,'mc','auto','운동장의 기온이 변하지 않은 때는 언제부터 언제까지인가요?',ARRAY['M4-2-u5-X13']::text[],true,'{"seq":22,"concept":"M4-2-u5-C8","difficulty":3,"kind":"mc","stem":"운동장의 기온이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"11시부터 12시까지","correct":true},{"t":"9시부터 10시까지","mis":"M4-2-u5-X13"},{"t":"10시부터 11시까지","mis":"M4-2-u5-X13"},{"t":"12시부터 13시까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 11시와 12시 사이에 있어요.","11시와 12시 모두 16 °C예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["9시","10시","11시","12시","13시"],"series":[{"vals":[20,24,16,16,10]}],"step":2,"ymax":26,"ylab":"(°C)","xlab":"(시)","title":"시각별 운동장의 기온"},"variant_rule":{"alt":[{"stem":"줄넘기 기록이 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"5월부터 6월까지","correct":true},{"t":"3월부터 4월까지","mis":"M4-2-u5-X13"},{"t":"4월부터 5월까지","mis":"M4-2-u5-X13"},{"t":"6월부터 7월까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 5월과 6월 사이에 있어요.","5월과 6월 모두 55회예요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["3월","4월","5월","6월","7월"],"series":[{"vals":[30,20,55,55,110]}],"step":5,"ymax":115,"ylab":"(회)","xlab":"(월)","title":"월별 줄넘기 기록"}},{"stem":"미세 먼지 나쁨 일수가 변하지 않은 때는 언제부터 언제까지인가요?","options":[{"t":"2016년부터 2017년까지","correct":true},{"t":"2017년부터 2018년까지","mis":"M4-2-u5-X13"},{"t":"2018년부터 2019년까지","mis":"M4-2-u5-X13"},{"t":"2019년부터 2020년까지","mis":"M4-2-u5-X13"}],"explanation":["값이 변하지 않으면 선분이 오른쪽으로 평평하게 가요.","평평한 선분은 2016년과 2017년 사이에 있어요.","2016년과 2017년 모두 17일이에요 — 변하지 않았어요."],"asset":{"type":"lgraph","xs":["2016","2017","2018","2019","2020","2021"],"series":[{"vals":[17,17,18,14,9,19]}],"step":1,"ymax":20,"ylab":"(일)","xlab":"(년)","title":"연도별 미세 먼지 나쁨 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#23','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C5',4,'sa','auto','나무의 키는 30 cm, 50 cm, 130 cm, 180 cm, 200 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u5-C5","difficulty":4,"kind":"sa","stem":"나무의 키는 30 cm, 50 cm, 130 cm, 180 cm, 200 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 큰 값은 200 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 5이면 20칸으로 100까지밖에 못 나타내요.","한 칸이 10이면 200까지 나타낼 수 있고 값도 모두 10의 배수라 답은 10이에요."],"variant_rule":{"alt":[{"stem":"선인장 줄기의 길이는 12 cm, 16 cm, 26 cm, 34 cm, 36 cm예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["가장 큰 값은 36 cm예요 — 20칸 안에 들어가야 해요.","한 칸이 1이면 20칸으로 20까지밖에 못 나타내요.","한 칸이 2이면 40까지 나타낼 수 있고 값도 모두 2의 배수라 답은 2예요."],"asset":null},{"stem":"줄넘기 기록은 10회, 25회, 75회, 95회, 100회예요. 세로 눈금을 0부터 20칸까지만 그릴 수 있어요. 세로 눈금 한 칸을 1, 2, 5, 10 가운데 하나로 정할 때, 모든 값을 눈금 위에 찍을 수 있는 가장 작은 한 칸은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 큰 값은 100회예요 — 20칸 안에 들어가야 해요.","한 칸이 2이면 20칸으로 40까지밖에 못 나타내요.","한 칸이 5이면 100까지 나타낼 수 있고 값도 모두 5의 배수라 답은 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#24','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C8',4,'sa','auto','전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u5-C8","difficulty":4,"kind":"sa","stem":"전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: +9, +3, −8, −2, −1, −6.","늘어난 때: 5월, 6월.","모두 2번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[9,18,21,13,11,10,4]}],"step":1,"ymax":22,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: −11, +7, −2, +3, +9, −4.","늘어난 때: 6월, 8월, 9월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[17,6,13,11,14,23,19]}],"step":1,"ymax":24,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}},{"stem":"이번에는 다른 그림이에요. 전월과 비교하여 자외선 지수 매우 높음 일수가 늘어난 때는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분을 하나씩 보며 오른쪽 위로 올라간 것을 세요: −9, +8, +3, −1, −6, +2.","늘어난 때: 6월, 7월, 10월.","모두 3번이에요."],"asset":{"type":"lgraph","xs":["4월","5월","6월","7월","8월","9월","10월"],"series":[{"vals":[14,5,13,16,15,9,11]}],"step":1,"ymax":17,"ylab":"(일)","xlab":"(월)","title":"월별 자외선 지수 매우 높음 일수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u5_review_d#25','math',4,2,'u5','','g4_2_math_u5_review_d','unit_review','M4-2-u5-C11',4,'essay','teacher','「연도별 유적지 관람객 수」와 「나라별 관람객 수」를 그래프로 나타내려고 해요. 각각에 알맞은 그래프를 고르고, 그렇게 고른 까닭을 자료를 모은 목적과 특성으로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u5-C11","difficulty":4,"kind":"essay","stem":"「연도별 유적지 관람객 수」와 「나라별 관람객 수」를 그래프로 나타내려고 해요. 각각에 알맞은 그래프를 고르고, 그렇게 고른 까닭을 자료를 모은 목적과 특성으로 설명해 보세요.","answer_guide":{"answer":"예: 연도별 유적지 관람객 수는 시간에 따라 달라지는 자료이고 어떻게 달라졌는지 알아보려는 것이므로 꺾은선그래프가 알맞다. 나라별 관람객 수는 나라끼리 견주는 자료이므로 막대그래프나 그림그래프가 알맞다.","scoring_points":["연도별 자료에 꺾은선그래프를 골랐는가","나라별 자료에 막대(그림)그래프를 골랐는가","시간에 따른 변화 / 항목끼리 견주기로 까닭을 썼는가"]},"explanation":["연도별 = 시간에 따른 변화 → 꺾은선그래프.","나라별 = 항목끼리 견주기 → 막대·그림그래프.","목적과 자료의 특성을 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
